// tools/audit_sequential_tabs.js
const puppeteer = require('puppeteer-core');
const fs = require('fs');
const path = require('path');

const TABS = [
  { id: 'fullscan', num: '01', name: 'FULL SCAN', pageId: 'pageFullScan', btnId: 'navTabFullScan' },
  { id: 'diettrades', num: '02', name: 'MEAL PLANNER', pageId: 'pageDietTrades', btnId: 'navTabDietTrades' },
  { id: 'metabolic', num: '03', name: 'METABOLIC', pageId: 'pageMetabolic', btnId: 'navTabMetabolic' },
  { id: 'reports', num: '04', name: 'REPORTS', pageId: 'pageReports', btnId: 'navTabReports' },
  { id: 'learning', num: '05', name: 'LEARNING', pageId: 'pageLearning', btnId: 'navTabLearning' },
  { id: 'operations', num: '06', name: 'OPERATIONS', pageId: 'pageOperations', btnId: 'navTabOperations' },
  { id: 'help', num: '07', name: 'FAQ', pageId: 'pageHelp', btnId: 'navTabHelp' },
  { id: 'goals', num: '08', name: 'CLINICAL GOALS', pageId: 'pageGoals', btnId: 'navTabGoals' },
  { id: 'medication', num: '09', name: 'MEDICATION', pageId: 'pageMedication', btnId: 'navTabMedication' },
  { id: 'setup', num: '10', name: 'CONFIG', pageId: 'pageSetup', btnId: 'navTabSetup' },
  { id: 'watchfaces', num: '11', name: 'WATCH', pageId: 'pageWatchFaces', btnId: 'navTabWatchFaces' },
  { id: 'log', num: '12', name: 'DATA LOG', pageId: 'pageLog', btnId: 'navTabLog' },
  { id: 'export', num: '13', name: 'EXPORT', pageId: 'pageExport', btnId: 'navTabExport' },
  { id: 'troubleshooting', num: '14', name: 'TROUBLESHOOTING', pageId: 'pageTroubleshooting', btnId: 'navTabTroubleshooting' }
];

async function runSequentialTabAudit() {
  console.log('======================================================================');
  console.log('   SEQUENTIAL 14-TAB MULTI-SCREEN AUDIT ENGINE (TABS 01 - 14)        ');
  console.log('======================================================================\n');

  const browser = await puppeteer.launch({
    executablePath: 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
    headless: "new",
    args: ['--allow-file-access-from-files', '--disable-web-security', '--no-sandbox']
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1440, height: 900 });

  const consoleErrors = [];
  page.on('console', msg => {
    if (msg.type() === 'error') {
      consoleErrors.push(msg.text());
    }
  });

  const pageErrors = [];
  page.on('pageerror', err => {
    pageErrors.push(err.message);
  });

  await page.goto('file:///D:/veepoo/BFM.HTM', { waitUntil: 'domcontentloaded', timeout: 30000 });
  await new Promise(r => setTimeout(r, 2000));

  const results = [];

  for (let i = 0; i < TABS.length; i++) {
    const t = TABS[i];
    const errorsBefore = consoleErrors.length + pageErrors.length;

    // Switch tab
    await page.evaluate((tabId) => {
      switchTab(tabId);
    }, t.id);

    await new Promise(r => setTimeout(r, 800));

    // Audit tab state in DOM
    const audit = await page.evaluate((tInfo) => {
      const pageEl = document.getElementById(tInfo.pageId);
      const btnEl = document.getElementById(tInfo.btnId);

      const isActivePage = pageEl ? pageEl.classList.contains('active-page') : false;
      const isActiveBtn = btnEl ? btnEl.classList.contains('active') : false;
      const isVisible = pageEl ? (pageEl.offsetWidth > 0 && pageEl.offsetHeight > 0) : false;
      const htmlLen = pageEl ? pageEl.innerHTML.length : 0;
      const childCount = pageEl ? pageEl.children.length : 0;

      // Check text content quality: verify no raw placeholders or error strings
      const text = pageEl ? pageEl.innerText : '';
      const hasUndefined = /\bundefined\b/i.test(text);
      const hasNaN = /\bNaN\b/.test(text);
      const hasNull = /\bnull\b/.test(text);
      const hasFakeSine = /sine wave/i.test(text);

      return {
        isActivePage,
        isActiveBtn,
        isVisible,
        htmlLen,
        childCount,
        textLen: text.length,
        hasUndefined,
        hasNaN,
        hasNull,
        hasFakeSine
      };
    }, t);

    const errorsAfter = consoleErrors.length + pageErrors.length;
    const newErrors = errorsAfter - errorsBefore;

    const pass = audit.isActivePage && audit.isActiveBtn && audit.isVisible && 
                 audit.htmlLen > 100 && !audit.hasNaN && !audit.hasFakeSine && newErrors === 0;

    results.push({
      tab: t,
      audit,
      newErrors,
      pass
    });

    console.log(`[TAB ${t.num}: ${t.name}] -> Active: ${audit.isActivePage} | Visible: ${audit.isVisible} | DOM Bytes: ${audit.htmlLen} | Children: ${audit.childCount} | Errors: ${newErrors} => ${pass ? 'PASS' : 'FAIL'}`);
  }

  await browser.close();

  console.log('\n======================================================================');
  const allPass = results.every(r => r.pass);
  console.log(`AUDIT FINISHED: ${results.filter(r => r.pass).length} / ${results.length} TABS PASSED (Overall: ${allPass ? '100% SIX SIGMA' : 'DEFECTS DETECTED'})`);
  console.log('======================================================================\n');

  if (!allPass) {
    process.exit(1);
  }
}

runSequentialTabAudit().catch(err => {
  console.error('Fatal execution error:', err);
  process.exit(1);
});

