const puppeteer = require('puppeteer-core');
const path = require('path');

const CHROME_PATH = "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe";
const TARGET_URL = 'file:///' + path.resolve(__dirname, '../BFM.HTM').replace(/\\/g, '/');

(async () => {
  console.log(`[STABILITY AUDIT] Launching headless Chrome via puppeteer-core...`);
  console.log(`[STABILITY AUDIT] Target URL: ${TARGET_URL}`);

  const browser = await puppeteer.launch({
    executablePath: CHROME_PATH,
    headless: "new",
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-web-security',
      '--allow-file-access-from-files',
      '--js-flags=--expose-gc'
    ]
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });

  const errors = [];
  page.on('console', msg => {
    const text = msg.text();
    if (msg.type() === 'error' || text.toLowerCase().includes('uncaught') || text.toLowerCase().includes('error:')) {
      errors.push(`[CONSOLE ${msg.type()}] ${text}`);
    }
  });

  page.on('pageerror', err => {
    errors.push(`[PAGE ERROR] ${err.toString()}`);
  });

  console.log(`[STABILITY AUDIT] Navigating to page...`);
  await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 30000 });
  console.log(`[STABILITY AUDIT] Page loaded successfully.`);

  // Monitor memory and DOM nodes over 30 seconds
  const samples = [];
  for (let i = 1; i <= 6; i++) {
    await new Promise(r => setTimeout(r, 5000));
    const metrics = await page.metrics();
    const domCount = await page.evaluate(() => document.getElementsByTagName('*').length);
    console.log(`[T+${i*5}s] JSHeapUsed: ${(metrics.JSHeapUsedSize / 1024 / 1024).toFixed(2)} MB | JSHeapTotal: ${(metrics.JSHeapTotalSize / 1024 / 1024).toFixed(2)} MB | DOM Nodes: ${domCount} | LayoutCount: ${metrics.LayoutCount}`);
    samples.push({ t: i * 5, heap: metrics.JSHeapUsedSize, dom: domCount });
  }

  if (errors.length > 0) {
    console.log(`[ERRORS DETECTED (${errors.length})]:`);
    errors.forEach(e => console.log('  ' + e));
  } else {
    console.log(`[CLEAN] Zero console errors during initial 30s monitoring.`);
  }

  await browser.close();
  console.log(`[STABILITY AUDIT] Initial check complete.`);
})();

