let _refreshThrottleTimer = null;
let _isPipelineRunning = false;
function scheduleFullPipelineRefresh() {
  if (_refreshThrottleTimer) return;
  _refreshThrottleTimer = setTimeout(async () => {
    _refreshThrottleTimer = null;
    if (_isPipelineRunning) return;
    _isPipelineRunning = true;
    try {
      await runFullPipelineAndRefreshAllScreens();
    } finally {
      _isPipelineRunning = false;
    }
  }, 350);
}

async function runFullPipelineAndRefreshAllScreens() {
  // 1. Fetch latest telemetry and populate state from current cache/database
  try {
    if (typeof pollLiveTelemetryChanges === 'function') {
      await pollLiveTelemetryChanges(true);
    }
  } catch (e) {}

  // 2. Propagate current real measurements across dynamic fields (Zero Is Zero)
  if (typeof propagateFullScanResultsToAllPages === 'function' && window._latestTelemetry) {
    const vit = window._latestTelemetry;
    const g = (vit.GLUCOSE && vit.GLUCOSE.value1 > 0) ? Math.round(vit.GLUCOSE.value1) : (typeof lastGlucoseMg !== 'undefined' ? lastGlucoseMg : 0);
    const sys = (vit.BLOOD_PRESSURE && vit.BLOOD_PRESSURE.value1 > 0) ? Math.round(vit.BLOOD_PRESSURE.value1) : (typeof lastSystolic !== 'undefined' ? lastSystolic : 0);
    const dia = (vit.BLOOD_PRESSURE && vit.BLOOD_PRESSURE.value2 > 0) ? Math.round(vit.BLOOD_PRESSURE.value2) : (typeof lastDiastolic !== 'undefined' ? lastDiastolic : 0);
    const sp = (vit.SPO2 && vit.SPO2.value1 > 0) ? Math.round(vit.SPO2.value1) : ((vit.BLOOD_OXYGEN && vit.BLOOD_OXYGEN.value1 > 0) ? Math.round(vit.BLOOD_OXYGEN.value1) : (typeof lastSpO2 !== 'undefined' ? lastSpO2 : 0));
    const hr = (vit.HEART_RATE && vit.HEART_RATE.value1 > 0) ? Math.round(vit.HEART_RATE.value1) : (typeof lastHR !== 'undefined' ? lastHR : 0);
    const bF = (vit.TEMPERATURE && vit.TEMPERATURE.value1 > 0) ? vit.TEMPERATURE.value1 : (typeof lastBodyF !== 'undefined' ? lastBodyF : 0);
    const sF = (vit.TEMPERATURE && vit.TEMPERATURE.value2 > 0) ? vit.TEMPERATURE.value2 : (typeof lastSkinF !== 'undefined' ? lastSkinF : 0);
    const bC = bF > 0 ? parseFloat(((bF - 32) * 5 / 9).toFixed(1)) : 0;
    const hrvVal = (vit.HRV_STRESS && vit.HRV_STRESS.value1 > 0) ? Math.round(vit.HRV_STRESS.value1) : (typeof lastHRV !== 'undefined' ? lastHRV : 0);
    const stVal = (vit.HRV_STRESS && vit.HRV_STRESS.value2 > 0) ? Math.round(vit.HRV_STRESS.value2) : (typeof lastStress !== 'undefined' ? lastStress : 0);

    propagateFullScanResultsToAllPages({
      glucose: g,
      bp: { sys: sys, dia: dia },
      spo2: sp,
      hr: hr,
      temp: { bodyF: bF, skinF: sF, bodyC: bC },
      hrv: { hrv: hrvVal, stress: stVal }
    }, false);
  }

  // 3. Recalculate daily hydration chart from journals
  if (typeof renderDailyHydrationChart === 'function') {
    renderDailyHydrationChart('curveTimelineFluidWater');
  }

  // 4. Recalculate clinical goals audit
  if (typeof runGoalComplianceAudit === 'function') {
    runGoalComplianceAudit(false);
  }

  // 5. Active Tab Scoped Re-renders (Prevents Background DOM & WebGL Thrashing)
  const pageReports = document.getElementById('pageReports');
  const isReportsActive = pageReports && pageReports.classList.contains('active-page');
  if (isReportsActive && typeof renderReportsView === 'function') {
    renderReportsView();
  }

  const pageDiet = document.getElementById('pageDiet');
  const pageMetabolic = document.getElementById('pageMetabolic');
  const isDietActive = (pageDiet && pageDiet.classList.contains('active-page')) || (pageMetabolic && pageMetabolic.classList.contains('active-page'));
  if (isDietActive && typeof renderDietHistory === 'function') {
    renderDietHistory();
  }

  const pageMed = document.getElementById('pageMedication');
  if (pageMed && pageMed.classList.contains('active-page')) {
    if (typeof renderMedicationRegimen === 'function') renderMedicationRegimen();
    if (typeof renderMedicationChangeHistory === 'function') renderMedicationChangeHistory();
  }

  if (isReportsActive) {
    if (typeof loadFeelingsFor3D === 'function') loadFeelingsFor3D();
    if (typeof render3DMultiChannelScene === 'function') render3DMultiChannelScene();
  }

  const pageWatch = document.getElementById('pageWatch');
  if (pageWatch && pageWatch.classList.contains('active-page') && typeof renderWatchTabConnectedDetails === 'function') {
    renderWatchTabConnectedDetails();
  }

  if (typeof render360HealthView === 'function') {
    render360HealthView();
  }
}

