const puppeteer = require('puppeteer-core');
const path = require('path');

const CHROME_PATH = "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe";
const TARGET_URL = 'file:///' + path.resolve(__dirname, '../BFM.HTM').replace(/\\/g, '/');

(async () => {
  console.log(`========================================================================`);
  console.log(`[STABILITY 180S AUDIT] 3-Minute Live Standalone Runtime Certification`);
  console.log(`[STABILITY 180S AUDIT] Target URL: ${TARGET_URL}`);
  console.log(`========================================================================`);

  const browser = await puppeteer.launch({
    executablePath: CHROME_PATH,
    headless: "new",
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-web-security',
      '--allow-file-access-from-files',
      '--js-flags=--expose-gc'
    ]
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1440, height: 900 });

  const errors = [];
  page.on('console', msg => {
    const text = msg.text();
    if (msg.type() === 'error' && !text.includes('Failed to load resource')) {
      errors.push(`[CONSOLE ERROR] ${text}`);
    }
  });

  page.on('pageerror', err => {
    errors.push(`[PAGE ERROR] ${err.toString()}`);
  });

  console.log(`[STABILITY 180S AUDIT] Loading page under standalone file:/// protocol...`);
  await page.goto(TARGET_URL, { waitUntil: 'load', timeout: 30000 });
  console.log(`[STABILITY 180S AUDIT] Page loaded. Starting 180-second stress cycle...`);

  const tabs = [
    'fullscan', 'mealplanner', 'metabolic', 'reports', 'learning',
    'operations', 'faq', 'clinicalgoals', 'medication', 'config',
    'watch', 'datalog', 'export', 'troubleshooting'
  ];

  let initialHeap = 0;
  let maxHeap = 0;
  const startTime = Date.now();
  let cycle = 0;

  while ((Date.now() - startTime) < 180000) {
    cycle++;
    const currentTab = tabs[(cycle - 1) % tabs.length];

    // Switch tab
    await page.evaluate((tabId) => {
      if (typeof switchTab === 'function') switchTab(tabId);
    }, currentTab);

    // Wait 15 seconds
    await new Promise(r => setTimeout(r, 15000));

    const metrics = await page.metrics();
    const heapMB = (metrics.JSHeapUsedSize / 1024 / 1024).toFixed(2);
    const totalHeapMB = (metrics.JSHeapTotalSize / 1024 / 1024).toFixed(2);
    const domCount = await page.evaluate(() => document.getElementsByTagName('*').length);
    const elapsedSec = Math.round((Date.now() - startTime) / 1000);

    if (cycle === 1) initialHeap = parseFloat(heapMB);
