    INSERT INTO vital_records
    (timestamp, metric, value1, value2, unit, progress, status, mode, raw_hex, device_id)
    VALUES (?, 'PEDOMETER', 44.0, 2.0, 'steps', 100, 'ACTIVE', 'LIVE_WATCH_TELEMETRY', '07 00 00 00 2C 00 00 00 C8', 'VEE_5010')
""", (now_iso,))
conn.commit()
print("Inserted 44 steps record into SQLite.")
conn.close()

