# -------------------------------------------------------------
with open('D:/veepoo/w11_htm_app/server.py', 'r', encoding='utf-8') as f:
    server_code = f.read()

# Fix insert_vital_record signature & device_id logic
old_insert = """def insert_vital_record(metric, value1, value2, unit, progress, status, mode, raw_hex, custom_ts=None):
    ts = custom_ts or datetime.datetime.now().isoformat()
    with db_lock:
        conn = get_db()
        cur = conn.cursor()
        try:
            device_id = str(payload.get("device_id") or "VEE_5010").strip()
            cur.execute(\"\"\"
                INSERT INTO vital_records
                (timestamp, metric, value1, value2, unit, progress, status, mode, raw_hex, device_id)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(timestamp, metric) DO UPDATE SET
                    value1 = excluded.value1,
                    value2 = excluded.value2,
                    unit = excluded.unit,
                    progress = excluded.progress,
                    status = excluded.status,
                    mode = excluded.mode,
                    raw_hex = excluded.raw_hex,
                    device_id = excluded.device_id
            \"\"\", (ts, metric, value1, value2, unit, progress, status, mode, raw_hex, device_id))
            conn.commit()
            cur.execute("SELECT COUNT(*) FROM vital_records")
            ble_state["total_records"] = cur.fetchone()[0]
        except Exception as e:
            print(f"[DB Error] insert_vital_record: {e}")
        finally:
            conn.close()"""

new_insert = """def insert_vital_record(metric, value1, value2, unit, progress, status, mode, raw_hex, custom_ts=None, device_id="VEE_5010"):
    ts = custom_ts or datetime.datetime.now().isoformat()
    dev_id = str(device_id or "VEE_5010").strip()
    with db_lock:
        conn = get_db()
        cur = conn.cursor()
        try:
            cur.execute(\"\"\"
                INSERT INTO vital_records
                (timestamp, metric, value1, value2, unit, progress, status, mode, raw_hex, device_id)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(timestamp, metric) DO UPDATE SET
                    value1 = excluded.value1,
                    value2 = excluded.value2,
                    unit = excluded.unit,
