import os
import re
import subprocess
import sqlite3

# -------------------------------------------------------------
# 1. Patch BFM.HTM
# -------------------------------------------------------------
with open('D:/veepoo/BFM.HTM', 'r', encoding='utf-8') as f:
    html = f.read()

# Replace Star Trek terms in UI & Diagnostics
replacements = [
    # Transponder -> Smartwatch Sensor / Hardware
    ('<div class="ribbon-label">AUTHORIZED WATCH TRANSPONDER</div>', '<div class="ribbon-label">AUTHORIZED SMARTWATCH SENSORS</div>'),
    ('All 6 biometric transponders on Model 5010', 'All 6 biometric sensors on Model 5010'),
    ('wake the transponder before initiating pairing', 'wake the smartwatch display before initiating pairing'),
    ('watch transponder', 'smartwatch sensor'),
    ('Watch transponder', 'Smartwatch sensor'),
    ('WATCH TRANSPONDER', 'SMARTWATCH SENSORS'),
    ('transponders returned to idle', 'sensors returned to idle'),
    ('Transponder offline in charging dock', 'Watch sensor offline in charging dock'),
    ('PAUSING 1.5s TO CLEAR SENSOR TRANSPONDER...', 'PAUSING 1.5s TO CLEAR SENSOR BUFFER...'),
    ('BLE Transponder Query', 'BLE Hardware Sensor Query'),
    ('watch optical sensors halted. Transponders returned to idle', 'watch optical sensors halted. Sensor arrays returned to idle'),
    ('biometric transponders linked in standby', 'biometric sensors linked in standby'),

    # Subspace -> Bluetooth / System
    ('SUBSPACE BLE RADIO RECOVERY', 'BLUETOOTH BLE RADIO RECOVERY'),
    ('01. SUBSPACE TELEMETRY BRIDGE', '01. BLUETOOTH TELEMETRY BRIDGE'),
    ('BFM Subspace Port 8899', 'BFM Bluetooth Port 8899'),
    ('TAB 6: SUBSPACE BLE LOG', 'TAB 6: BLUETOOTH BLE LOG'),
    ('SUBSPACE BLE PROTOCOL PACKET LOG', 'BLUETOOTH BLE PROTOCOL PACKET LOG'),
    ('BFM 5010 Subspace Telemetry Stream Online', 'BFM 5010 Bluetooth Telemetry Stream Online'),
    ('Subspace Diagnostic Bus Online', 'Bluetooth Diagnostic Bus Online'),
    ('ENGAGING SUBSPACE BLE LINK:', 'ENGAGING BLUETOOTH BLE LINK:'),
    ('[+] GATT Subspace connection established!', '[+] GATT Bluetooth connection established!'),
    ('BLE Subspace Link Connected', 'BLE Bluetooth Link Connected'),
    ('Active BLE Subspace Device Discovery', 'Active BLE Device Discovery'),
    ('Subspace Telemetry Bus Warning / Error', 'Bluetooth Telemetry Bus Warning / Error'),

    # Starfleet Registry NCC- -> BFM-
    ('NCC-5010-A', 'BFM-5010-01'),

    # Shuttle / Shuttlecraft -> Mobile Phone
    ('CANNOT FIND CELL PROCEDURE (MOBILE SHUTTLE PROVISIONING & DISCOVERY)', 'CANNOT FIND CELL PROCEDURE (MOBILE PHONE PROVISIONING & DISCOVERY)'),
    ('Approve Shuttle Enrollment:', 'Approve Phone Enrollment:'),
    ('APPROVE CELL SHUTTLE', 'APPROVE MOBILE PHONE'),

    # Button: ADD CELL -> ADD PHONE
    ('>📱 ADD CELL<', '>📱 ADD PHONE<'),
    ('📱 ADD CELL &bull; CELL PROVISIONING', '📱 ADD PHONE &bull; MOBILE APP PROVISIONING'),

    # Version bump
    ('BUILD beta.00.01.0032', 'BUILD beta.00.01.0034'),
    ('BUILD beta.00.01.0033', 'BUILD beta.00.01.0034'),
]

for old, new in replacements:
    if old in html:
        html = html.replace(old, new)
        print(f"Replaced: {old[:40]} -> {new[:40]}")
    else:
        print(f"NOTE: Pattern not directly found: {old[:40]}")

# Add phone connection auto-verification and auto-close logic to modalProvisionCell
old_prov_func = """    async function openProvisionModal() {
      const modal = document.getElementById('modalProvisionCell');
      if (modal) modal.style.display = 'flex';
      const res = document.getElementById('provResultBox');
      if (res) res.style.display = 'none';
      const qrBox = document.getElementById('provCellQrContainer');
      const apiBase = (window.location.protocol === 'file:') ? 'http://127.0.0.1:8899' : '';
      try {
        const resp = await fetch(`${apiBase}/api/qrcode/cell?_t=${Date.now()}`);
        if (resp.ok) {
          const svgText = await resp.text();
          if (qrBox && svgText && svgText.includes('<svg')) {
            qrBox.innerHTML = svgText;
            const svgEl = qrBox.querySelector('svg');
            if (svgEl) {
              svgEl.setAttribute('width', '100%');
              svgEl.setAttribute('height', '100%');
              svgEl.style.display = 'block';
              svgEl.style.fill = '#000000';
              svgEl.querySelectorAll('path').forEach(p => {
                p.setAttribute('fill', '#000000');
                p.style.fill = '#000000';
              });
            }
            return;
          }
        }
      } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
      const qr = document.getElementById('provCellQrImg');
      if (qr) qr.src = `${apiBase}/api/qrcode/cell?_t=${Date.now()}`;
    }"""

new_prov_func = """    let _phoneVerifyPollTimer = null;

    async function openProvisionModal() {
      const modal = document.getElementById('modalProvisionCell');
      if (modal) modal.style.display = 'flex';
      const res = document.getElementById('provResultBox');
      if (res) {
        res.style.display = 'block';
        res.innerHTML = '<span style="color: #38bdf8;">⏳ WAITING FOR MOBILE PHONE TO CONNECT...</span>';
      }
      const qrBox = document.getElementById('provCellQrContainer');
      const apiBase = (window.location.protocol === 'file:') ? 'http://127.0.0.1:8899' : '';
      try {
        const resp = await fetch(`${apiBase}/api/qrcode/cell?_t=${Date.now()}`);
        if (resp.ok) {
          const svgText = await resp.text();
          if (qrBox && svgText && svgText.includes('<svg')) {
            qrBox.innerHTML = svgText;
            const svgEl = qrBox.querySelector('svg');
            if (svgEl) {
              svgEl.setAttribute('width', '100%');
              svgEl.setAttribute('height', '100%');
              svgEl.style.display = 'block';
              svgEl.style.fill = '#000000';
              svgEl.querySelectorAll('path').forEach(p => {
                p.setAttribute('fill', '#000000');
                p.style.fill = '#000000';
              });
            }
          }
        }
      } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
      const qr = document.getElementById('provCellQrImg');
      if (qr) qr.src = `${apiBase}/api/qrcode/cell?_t=${Date.now()}`;

      // Start automatic phone connection verification watchdog
      if (_phoneVerifyPollTimer) clearInterval(_phoneVerifyPollTimer);
      _phoneVerifyPollTimer = setInterval(async () => {
        try {
          const r = await fetch(`${apiBase}/api/shuttle/roster?_t=${Date.now()}`);
          if (!r.ok) return;
          const data = await r.json();
          const roster = data.roster || [];
          const activeCell = roster.find(c => c.status === 'ACTIVE' || c.status === 'CONNECTED');
          if (activeCell) {
            clearInterval(_phoneVerifyPollTimer);
            _phoneVerifyPollTimer = null;
            if (res) {
              res.style.display = 'block';
              res.innerHTML = `✅ <strong style="color: #4ade80;">MOBILE PHONE CONNECTED & VERIFIED!</strong><br><span style="color: #cbd5e1;">Device: ${activeCell.phone_name || 'Mobile Phone'} linked. Closing setup window...</span>`;
            }
            if (typeof loadFamilyCellsRoster === 'function') loadFamilyCellsRoster();
            setTimeout(() => { closeProvisionModal(); }, 1800);
          }
        } catch (err) {
          console.warn('[MIL-SPEC HANDLED FAULT]', err);
        }
      }, 1500);
    }

    function closeProvisionModal() {
      if (_phoneVerifyPollTimer) {
        clearInterval(_phoneVerifyPollTimer);
        _phoneVerifyPollTimer = null;
      }
      const modal = document.getElementById('modalProvisionCell');
      if (modal) modal.style.display = 'none';
    }"""

assert old_prov_func in html, "old_prov_func not found in BFM.HTM"
html = html.replace(old_prov_func, new_prov_func)

# Also update closeProvisionModal in existing code if separate
html = html.replace(
    "function closeProvisionModal() {\n      const modal = document.getElementById('modalProvisionCell');\n      if (modal) modal.style.display = 'none';\n    }",
    "// closeProvisionModal defined with watchdog cancellation above"
)

# Write to all 3 mirrors
for path in ['D:/veepoo/BFM.HTM', 'D:/veepoo/index.html', 'D:/veepoo/w11_htm_app/index.html']:
    with open(path, 'w', encoding='utf-8') as f:
        f.write(html)
    print(f"Updated mirror: {path}")

# -------------------------------------------------------------
# 2. Patch server.py: Remove Star Trek default strings
# -------------------------------------------------------------
with open('D:/veepoo/w11_htm_app/server.py', 'r', encoding='utf-8') as f:
    srv = f.read()

srv = srv.replace("'SHUTTLECRAFT_CELL'", "'MOBILE_PHONE_CELL'")
srv = srv.replace("John Mobile (Shuttlecraft-A)", "John Mobile Phone")
