      console.warn('[MIL-SPEC HANDLED FAULT]', e);
    }
  }

  if (!uiCtrlCharacteristic || !uiDataCharacteristic) {
    const msg = 'HARDWARE VERDICT: Watch firmware does NOT expose Veepoo UI Transfer Service (F0030001) — Watch cannot perform BLE watch-face upgrades.';
    logLCARS(`[!] ${msg}`, 'err');
    if (elTx) elTx.textContent = 'UNSUPPORTED: NO F0030001 UI SERVICE';
    setUi(100, 'HARDWARE UNSUPPORTED (NO F0030001)', msg, '#ef4444');
    soundError();
    return { supported: false, reason: 'NO_F0030001_SERVICE' };
  }

  // 3. Query base partition info (0x50 0x02 <uiFromType>)
  setUi(18, '3/7: QUERYING FLASH PARTITION (0x50 0x02)...', `Querying watch SPI flash base address & CRC for type 0x0${uiFromType}...`);
  let baseInfo = null;
  try {
    const waitInfo = waitFor0x50Response(2, uiFromType, 4000);
    const qPkt = new Uint8Array(20);
    qPkt[0] = 0x50; qPkt[1] = 0x02; qPkt[2] = uiFromType;
    await sendCommandBytes(qPkt);
    baseInfo = await waitInfo;
  } catch (e) {
    console.warn('[MIL-SPEC HANDLED FAULT]', e);
  }

  if (!baseInfo || !baseInfo.isOk || !baseInfo.maxLen) {
    const msg = 'HARDWARE VERDICT: Watch rejected 0x50 flash partition query — Watch face upgrades not supported on this firmware.';
    logLCARS(`[!] ${msg}`, 'err');
    if (elTx) elTx.textContent = 'REJECTED: 0x50 0x02 QUERY FAILED';
    setUi(100, 'HARDWARE REJECTED (0x50 0x02)', msg, '#ef4444');
    soundError();
    return { supported: false, reason: '0x50_INFO_REJECTED' };
  }

  // 4-byte align with 0xFF and calculate CRC-16 Modbus
  const padRem = rawBytes.length % 4;
  let padded = rawBytes;
  if (padRem !== 0) {
    padded = new Uint8Array(rawBytes.length + (4 - padRem));
    padded.fill(0xFF);
    padded.set(rawBytes, 0);
  }
  if (padded.length > baseInfo.maxLen) {
    const msg = `Binary (${padded.length} B) exceeds watch flash capacity (${baseInfo.maxLen} B).`;
    logLCARS(`[!] ${msg}`, 'err');
    setUi(100, 'SIZE EXCEEDS FLASH', msg, '#ef4444');
    soundError();
    return { supported: false, reason: 'EXCEEDS_MAX_LEN' };
  }

  const appCrc = calcVeepooCrc16(padded);
  if (appCrc === baseInfo.currentCrc) {
    logLCARS(`[!] Device CRC already equals 0x${appCrc.toString(16).toUpperCase()} — use Relabel Test to verify fresh flash write.`, 'rx');
  }

  // 4. Enter update mode (0x50 0x01 <uiFromType>) per vp_dc.java
  setUi(24, '4/7: ENTERING FLASH UPDATE MODE (0x50 0x01)...', `Addr 0x${baseInfo.flashAddr.toString(16)} | Size ${padded.length}B | CRC 0x${appCrc.toString(16).toUpperCase()}`);
  const addr = baseInfo.flashAddr >>> 0;
  const flen = padded.length >>> 0;
  const enterPkt = new Uint8Array(20);
  enterPkt[0] = 0x50;
  enterPkt[1] = 0x01;
  enterPkt[2] = uiFromType;
  enterPkt[3] = addr & 0xFF; enterPkt[4] = (addr >> 8) & 0xFF; enterPkt[5] = (addr >> 16) & 0xFF; enterPkt[6] = (addr >> 24) & 0xFF;
  enterPkt[7] = flen & 0xFF; enterPkt[8] = (flen >> 8) & 0xFF; enterPkt[9] = (flen >> 16) & 0xFF; enterPkt[10] = (flen >> 24) & 0xFF;
  if (uiFromType === 0x01) {
    const bType = baseInfo.binDataType || 0;
    enterPkt[11] = bType & 0xFF; enterPkt[12] = (bType >> 8) & 0xFF;
    enterPkt[13] = appCrc & 0xFF; enterPkt[14] = (appCrc >> 8) & 0xFF;
    enterPkt[15] = 0x01;
  }

  let enterAck = null;
  try {
    const waitEnter = waitFor0x50Response(1, uiFromType, 4000);
    await sendCommandBytes(enterPkt);
    enterAck = await waitEnter;
  } catch (e) {
    console.warn('[MIL-SPEC HANDLED FAULT]', e);
  }

  if (!enterAck || !enterAck.isOk) {
    const msg = 'HARDWARE VERDICT: Watch rejected 0x50 0x01 Enter UI Update Mode — firmware refuses external dial writes.';
    logLCARS(`[!] ${msg}`, 'err');
    if (elTx) elTx.textContent = 'REJECTED: 0x50 0x01 UPDATE MODE';
    setUi(100, 'UPDATE MODE REJECTED', msg, '#ef4444');
    soundError();
    return { supported: false, reason: 'ENTER_UPDATE_REJECTED' };
  }

  try {
    // 5. DOOG Start UI Update [68, 79, 79, 71, 5, 0]
    setUi(28, '5/7: STARTING DOOG UI SESSION...', 'Sending DOOG Start Update command on F0030002...');
    const waitStart = waitForDoogResponse(0x05, null, 5000);
    await writeUiCtrl(new Uint8Array([0x44, 0x4F, 0x4F, 0x47, 0x05, 0x00]));
    await waitStart;

    // 6. DOOG Clear/Erase UI Flash [68, 79, 79, 71, 1, addrLE, lenLE]
    setUi(32, '5/7: ERASING SPI FLASH PARTITION...', 'Waiting for watch SPI flash erase completion...');
    const erasePkt = new Uint8Array([
      0x44, 0x4F, 0x4F, 0x47, 0x01,
      addr & 0xFF, (addr >> 8) & 0xFF, (addr >> 16) & 0xFF, (addr >> 24) & 0xFF,
      flen & 0xFF, (flen >> 8) & 0xFF, (flen >> 16) & 0xFF, (flen >> 24) & 0xFF
    ]);
    const waitEraseDone = waitForDoogResponse(0x01, 0x03, 25000, (b) => {
      if (b[0] === 0x01 && b.length >= 3) {
        setUi(34, '5/7: ERASING SPI FLASH PARTITION...', `Watch flash erase sector ${b[2]} (op=${b[1]})...`);
      }
    });
    await writeUiCtrl(erasePkt);
    await waitEraseDone;

    // 7. Stream binary chunks on F0030003
    let chunkSize = 20;
    const totalChunks = Math.ceil(padded.length / chunkSize);
    let offset = 0;
    let idx = 0;
    let lastUiTick = 0;
    while (offset < padded.length) {
      const end = Math.min(offset + chunkSize, padded.length);
      await writeUiData(padded.subarray(offset, end));
      offset = end;
      idx++;
      if (idx % 12 === 0 || offset >= padded.length) {
        const pct = 35 + Math.round((offset / padded.length) * 55);
        const now = Date.now();
        if (now - lastUiTick > 150 || offset >= padded.length) {
          lastUiTick = now;
          setUi(pct, `6/7: STREAMING "${dialName}" TO WATCH...`, `Block ${idx}/${totalChunks} (${(offset / 1024).toFixed(1)} / ${(padded.length / 1024).toFixed(1)} KB)`);
        }
        await new Promise(r => setTimeout(r, 8));
      }
    }

    // 8. DOOG End Update [68, 79, 79, 71, 2, 0...]
    setUi(92, '7/7: FINALIZING & VERIFYING HARDWARE CRC...', 'Sending DOOG End Update on F0030002...');
    const waitEnd = waitForDoogResponse(0x02, null, 8000);
    const endPkt = new Uint8Array(20);
    endPkt[0] = 0x44; endPkt[1] = 0x4F; endPkt[2] = 0x4F; endPkt[3] = 0x47; endPkt[4] = 0x02;
    await writeUiCtrl(endPkt);
    await waitEnd;

    // 9. DOOG Check CRC [68, 79, 79, 71, 3, crcLE...]
    const waitCrc = waitForDoogResponse(0x03, null, 8000);
    const crcPkt = new Uint8Array(20);
    crcPkt[0] = 0x44; crcPkt[1] = 0x4F; crcPkt[2] = 0x4F; crcPkt[3] = 0x47; crcPkt[4] = 0x03;
    crcPkt[5] = appCrc & 0xFF; crcPkt[6] = (appCrc >> 8) & 0xFF;
    await writeUiCtrl(crcPkt);
    const crcResp = await waitCrc;
    const devCrc = (crcResp.length >= 3) ? ((crcResp[1] & 0xFF) | ((crcResp[2] & 0xFF) << 8)) : -1;

    if (devCrc !== appCrc) {
      const msg = `CRC MISMATCH: App=0x${appCrc.toString(16).toUpperCase()} vs Watch=0x${devCrc.toString(16).toUpperCase()}`;
      logLCARS(`[!] ${msg}`, 'err');
      if (elTx) elTx.textContent = msg;
      setUi(100, 'DOOG CRC MISMATCH', msg, '#ef4444');
      soundError();
      return { supported: false, reason: 'CRC_MISMATCH', appCrc, devCrc };
    }

    // 10. Activate Slot 3 via 0xC7
    const sPkt = new Uint8Array(20);
    sPkt[0] = 0xC7; sPkt[1] = 0x01; sPkt[2] = 0x03; sPkt[3] = uiFromType;
    await sendCommandBytes(sPkt);

    const elAct = document.getElementById('lblCurrentActiveFace');
    const elSlot = document.getElementById('lblActiveFaceSlot');
    const elSrc = document.getElementById('lblActiveFaceSource');
    if (elAct) elAct.textContent = `FLASHED DIAL: ${dialName.toUpperCase()}`;
    if (elSlot) elSlot.textContent = `Slot 3 (Type 0x0${uiFromType})`;
    if (elSrc) elSrc.textContent = uiFromType === 0x02 ? 'SPI FLASH CUSTOM (0x02)' : 'SERVER THEME (0x01)';
    if (elTx) elTx.textContent = `✔ HARDWARE PASS: DOOG FLASH + CRC 0x${devCrc.toString(16).toUpperCase()} VERIFIED`;

    setUi(100, `✔ HARDWARE PASS: "${dialName}" FLASHED (CRC 0x${devCrc.toString(16).toUpperCase()})`, 'Watch accepted binary & verified CRC-16 match — Watch face upgrades SUPPORTED!', '#22c55e');
    logLCARS(`[✔] HARDWARE PASS: Watch accepted "${dialName}" (${padded.length} B, CRC 0x${devCrc.toString(16).toUpperCase()})!`, 'rx');
    if (typeof soundSuccess === 'function') soundSuccess();

    setTimeout(async () => {
      try {
        const qPkt = new Uint8Array(20);
        qPkt[0] = 0xC7; qPkt[1] = 0x02;
        await sendCommandBytes(qPkt);
      } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
    }, 400);

    return { supported: true, appCrc, devCrc };
  } catch (err) {
    console.warn('[MIL-SPEC HANDLED FAULT]', err);
    const msg = `DOOG Transfer Fault: ${err.message}`;
    logLCARS(`[!] ${msg}`, 'err');
    if (elTx) elTx.textContent = msg;
    setUi(100, 'DOOG TRANSFER INTERRUPTED', msg, '#ef4444');
    soundError();
    return { supported: false, reason: err.message };
  }
}

async function loadStockDialInventory() {
