async function flashCloudDialToWatch(dialName, fileUrl, previewUrl, crc) {
  soundButtonPress();
  const dialApiBase = (window.location.protocol === 'file:' ? 'http://127.0.0.1:8899' : '');
  logLCARS(`[*] Loading "${dialName}" watch face binary for real DOOG BLE upgrade...`, "tx");

  let binBytes = null;
  try {
    const localResp = await fetch(`${dialApiBase}/api/dial/binary/${encodeURIComponent(dialName)}`);
    if (localResp.ok) {
      const buf = await localResp.arrayBuffer();
      binBytes = new Uint8Array(buf);
      const magic = String.fromCharCode(...binBytes.slice(0, 6));
      logLCARS(`[+] Loaded Local Stock Binary: ${dialName} (${(buf.byteLength / 1024).toFixed(1)} KB) | Magic="${magic}"`, "rx");
    } else if (fileUrl) {
      logLCARS(`[*] Local binary not cached, fetching from Veepoo CDN: ${fileUrl}...`, "tx");
      const cdnResp = await fetch(fileUrl);
      if (cdnResp.ok) {
        const buf = await cdnResp.arrayBuffer();
        binBytes = new Uint8Array(buf);
        logLCARS(`[+] Downloaded from Veepoo CDN: ${dialName} (${(buf.byteLength / 1024).toFixed(1)} KB)`, "rx");
      }
    }
  } catch (e) {
    console.warn('[MIL-SPEC HANDLED FAULT]', e);
    logLCARS(`[!] Failed to load binary for "${dialName}": ${e.message}`, "err");
  }

  if (!binBytes || binBytes.length < 16) {
    const msg = `Cannot flash "${dialName}": binary not available in local Shape 4 vault or blocked by offline/CORS policy.`;
    logLCARS(`[!] ${msg}`, 'err');
    const elTx = document.getElementById('lblLastGattTx');
    if (elTx) elTx.textContent = msg;
    soundError();
    return;
  }

  await flashDialBinaryViaDoogProtocol(dialName, binBytes, 0x01);
}

async function loadVeepooDialCatalog() {
  const dialApiBase = (window.location.protocol === 'file:' ? 'http://127.0.0.1:8899' : '');
