      : '';
    const downloadHref = item.local_verified
      ? `${dialApiBase}/api/dial/binary/${encodeURIComponent(item.name)}`
      : (item.fileUrl || `${dialApiBase}/api/dial/binary/${encodeURIComponent(item.name)}`);
    return `
    <div style="background: rgba(12, 14, 20, 0.95); border: 1px solid var(--lcars-border); border-radius: 8px; padding: 10px; display: flex; flex-direction: column; justify-content: space-between; align-items: center; text-align: center; transition: border-color 0.2s;">
      <div style="width: 100%; height: 170px; background: #000; border-radius: 6px; overflow: hidden; display: flex; align-items: center; justify-content: center; margin-bottom: 8px; border: 1px solid #222;">
        <img src="${previewSrc}" alt="${item.name}" loading="lazy" style="max-width: 100%; max-height: 100%; object-fit: contain;" onerror="this.style.display='none'; if(this.nextElementSibling) this.nextElementSibling.style.display='block';">
        <div style="display: none; font-size: 0.75rem; color: var(--lcars-gray); font-family: var(--lcars-mono);">[PREVIEW N/A]<br>${item.name}</div>
      </div>
      <div style="width: 100%;">
        <div style="font-weight: bold; color: var(--lcars-banana); font-size: 0.95rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.name}${localBadge}</div>
        <div style="font-size: 0.72rem; color: var(--lcars-gray); margin-top: 2px;">Size: ${(item.fileLength ? (item.fileLength / 1024).toFixed(0) + ' KB' : 'ROM')} • Dial ${item.dialShape}</div>
        <div style="display: flex; gap: 6px; margin-top: 8px;">
          <button class="lcars-btn btn-banana" style="flex: 1.3; padding: 6px 4px; font-size: 0.75rem; font-weight: bold; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 4px;" onclick="flashCloudDialToWatch('${item.name}', '${item.fileUrl || ''}', '${previewSrc}', ${item.crc || 0})">
            <span>⚡ APPLY / FLASH</span>
          </button>
          <a href="${downloadHref}" target="_blank" download="${item.name}.bin" class="lcars-btn btn-green" style="flex: 0.7; text-decoration: none; padding: 6px 2px; font-size: 0.75rem; font-weight: bold; display: flex; align-items: center; justify-content: center;">
            <span>💾 .BIN</span>
          </a>
        </div>
      </div>
    </div>
  `;
  }).join('');
}

