function updateWatchFaceWritableVisibility(isWritable, reason = '') {
  const activeId = (typeof window !== 'undefined' && window._connectedWatchId) ||
                   (typeof localStorage !== 'undefined' ? localStorage.getItem('bfm_connected_watch_id') : null) ||
                   'VEE_5010';
  watchFaceWritableSupported = !!isWritable;
  window._watchFaceWritable = watchFaceWritableSupported;
  watchFaceWritableReason = reason || (watchFaceWritableSupported ? 'SUPPORTED' : 'NOT_COMPATIBLE');
  try {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(`bfm_watchface_writable_${activeId}`, watchFaceWritableSupported ? '1' : '0');
    }
  } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }

  const sec = document.getElementById('watchFaceWritableSections');
  if (sec) {
    sec.style.display = watchFaceWritableSupported ? 'flex' : 'none';
  }
  if (watchFaceWritableSupported) {
    try { if (typeof initUnifiedGlucoseRing === 'function') initUnifiedGlucoseRing(); } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
    try { if (typeof loadStockDialInventory === 'function' && (!stockDialInventory || stockDialInventory.length === 0)) loadStockDialInventory(); } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
    try { if (typeof veepooCatalog !== 'undefined' && veepooCatalog.length === 0 && typeof loadVeepooDialCatalog === 'function') loadVeepooDialCatalog(); } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
  }
}

function syncWatchFaceWritableUI() {
  const activeId = (typeof window !== 'undefined' && window._connectedWatchId) ||
                   (typeof localStorage !== 'undefined' ? localStorage.getItem('bfm_connected_watch_id') : null) ||
                   'VEE_5010';
  const liveSessionWritable = !!(uiCtrlCharacteristic && uiDataCharacteristic && lastUiBaseInfo && lastUiBaseInfo.isOk && lastUiBaseInfo.flashAddr > 0 && lastUiBaseInfo.maxLen > 0);
  let isWritable = liveSessionWritable;
  if (!isWritable && activeId !== 'VEE_5010') {
    try {
      isWritable = (typeof localStorage !== 'undefined' && localStorage.getItem(`bfm_watchface_writable_${activeId}`) === '1');
    } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
  }
  if (activeId === 'VEE_5010' && !liveSessionWritable) {
    isWritable = false;
  }
  watchFaceWritableSupported = isWritable;
  window._watchFaceWritable = isWritable;
  const sec = document.getElementById('watchFaceWritableSections');
  if (sec) {
    sec.style.display = isWritable ? 'flex' : 'none';
  }
  return isWritable;
}

