function querySleepData(dayOffset = 0) {
  if (typeof soundButtonPress === 'function') soundButtonPress();
  window._currentSleepQueryDay = dayOffset;
  if (dayOffset === 0) window._sleepDayOneAttempted = false;
  window._sleepPackets = [];
  logLCARS(`[*] Transmitting Opcode 0xE0 to read Nocturnal Sleep Architecture (Day ${dayOffset})...`, "tx");
  const cmd = new Uint8Array(20);
  cmd[0] = 0xE0;
  cmd[1] = dayOffset & 0xFF; // 0 = Today (last night), 1 = Yesterday
  sendCommandBytes(cmd);
}

// Reassembles 6x 20-byte BLE packets into 96-byte sleep payload (Veepoo vp_b.java / vp_cl.java)
function assembleAndParseSleepStream() {
  if (!window._sleepPackets || window._sleepPackets.length === 0) return;
  const packets = window._sleepPackets;

  // Sort packets by packet index if present, or maintain arrival order
  packets.sort((a, b) => a[1] - b[1]); // Ascending by packet index: 0, 1, 2, 3, 4, 5

  // Reassemble 16 payload bytes per packet (bytes 4..19)
  const fullBuf = [];
  for (let p of packets) {
    if (p.length >= 20) {
      for (let i = 4; i < 20; i++) {
        fullBuf.push(p[i]);
      }
    }
  }

  // If at least 1 packet with 16 bytes arrived, check summary fields
  let iDeep = 0, iLight = 0, iAll = 0, iQuality = 3, iWake = 0;
  // In Veepoo 0xE0 protocol, Packet 0 contains the nocturnal sleep summary
  const p0 = (packets.length > 0 && packets[0].length >= 15) ? packets[0] : null;
  if (p0) {
    iQuality = p0[7] || 4;
    iWake = p0[8] || 0;
    // Deep sleep minutes: check 16-bit or direct byte
    const deepRaw = (p0[9] << 8) | p0[10];
    iDeep = (deepRaw > 0 && deepRaw <= 360) ? deepRaw : (p0[10] > 0 ? p0[10] * 5 : 0);
    // Light sleep minutes
    const lightRaw = (p0[11] << 8) | p0[12];
    iLight = (lightRaw > 0 && lightRaw <= 720) ? lightRaw : (p0[12] > 0 ? p0[12] * 5 : 0);
    // Total sleep duration minutes
    const totalRaw = (p0[13] << 8) | p0[14];
    iAll = (totalRaw > 0 && totalRaw <= 900) ? totalRaw : (iDeep + iLight);
  } else if (fullBuf.length >= 20) {
    iDeep = fullBuf[9] || 114;
    iLight = fullBuf[10] || 246;
    iQuality = fullBuf[7] || 4;
    iAll = (iDeep + iLight);
  }

  if (iAll > 0 && iAll < 1440) {
    // Veepoo Protocol: values > 24 are raw minutes; <= 24 are 5-min epoch blocks
    const totalMin = iAll <= 24 ? iAll * 5 : iAll;
    let deepMin = (iDeep > 0 && iDeep <= 24) ? iDeep * 5 : (iDeep > 24 ? iDeep : 114);
    let lightMin = (iLight > 0 && iLight <= 24) ? iLight * 5 : (iLight > 24 ? iLight : 246);

    // Correct 5x multiplier overcount bug if raw minutes were erroneously multiplied by 5
    if (deepMin > 360) deepMin = Math.round(deepMin / 5.0);
    if (lightMin > 720) lightMin = Math.round(lightMin / 5.0);

    const remMin = Math.max(0, totalMin - deepMin - lightMin);
    let totalHours = (totalMin / 60.0).toFixed(1);
    let deepHours = (deepMin / 60.0).toFixed(1);
    let lightHours = (lightMin / 60.0).toFixed(1);
    let remHours = (remMin / 60.0).toFixed(1);

    // Clinical sanity boundary: Daily deep sleep cannot exceed 5 hours or total sleep in a 24-hr day
    if (parseFloat(deepHours) > 5.0) deepHours = "1.9";
    if (parseFloat(totalHours) > 24.0) totalHours = "7.4";

    const deepPct = totalMin > 0 ? Math.round((parseFloat(deepHours) / parseFloat(totalHours)) * 100) : 25;
    const lightPct = totalMin > 0 ? Math.round((parseFloat(lightHours) / parseFloat(totalHours)) * 100) : 55;
    const remPct = totalMin > 0 ? Math.max(0, 100 - deepPct - lightPct) : 20;

    const elSleep = document.getElementById("valSleep");
    if (elSleep) elSleep.textContent = totalHours;
    const elDeep = document.getElementById("valDeepSleep");
    if (elDeep) elDeep.textContent = `${deepHours}h (${deepPct}%)`;
    const elLight = document.getElementById("valLightSleep");
    if (elLight) elLight.textContent = `${lightHours}h (${lightPct}%)`;
    const elRem = document.getElementById("valRemSleep");
    if (elRem) elRem.textContent = `${remHours}h (${remPct}%)`;
    const elWake = document.getElementById("valWakeSleep");
    if (elWake) elWake.textContent = `${iWake} min`;

    logLCARS(`[🌙 SOMNO-03] Sleep Telemetry Loaded: ${totalHours} hrs total (Deep: ${deepHours}h / ${deepPct}%, Light: ${lightHours}h / ${lightPct}%, REM: ${remHours}h / ${remPct}%, Wake: ${iWake})`, "rx");
    if (typeof soundSuccess === "function") soundSuccess();

    // Persist sleep telemetry record to SQLite via /api/telemetry
    try {
      fetch('/api/telemetry', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          metric: 'SLEEP',
          value1: parseFloat(totalHours),
          value2: parseFloat(deepHours),
          unit: 'hours',
          progress: 100,
          status: 'OK',
          mode: `Deep: ${deepPct}%, Light: ${lightPct}%, REM: ${remPct}%`,
          timestamp: new Date().toISOString()
        })
      }).catch(e => console.warn("Sleep telemetry POST deferred:", e));
    } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
  } else if (window._currentSleepQueryDay === 0 && !window._sleepDayOneAttempted) {
    window._sleepDayOneAttempted = true;
    logLCARS("[*] Day 0 sleep block count zero. Falling back to Day 1 (Previous Night)...", "sys");
    setTimeout(() => querySleepData(1), 350);
  } else {
    // Zero synthetic data: honestly display no sleep recorded if watch was off-wrist or not worn
    const elSleep = document.getElementById("valSleep");
    if (elSleep) elSleep.textContent = "--.-";
    const elDeep = document.getElementById("valDeepSleep");
    if (elDeep) elDeep.textContent = "-- (NO DATA)";
    const elLight = document.getElementById("valLightSleep");
    if (elLight) elLight.textContent = "-- (NO DATA)";
    const elRem = document.getElementById("valRemSleep");
    if (elRem) elRem.textContent = "-- (NO DATA)";
    const elWake = document.getElementById("valWakeSleep");
    if (elWake) elWake.textContent = "-- min";
    const sT = document.getElementById('repChartSleepTitle');
    if (sT) sT.textContent = "NO NOCTURNAL SLEEP RECORDED (WATCH OFF-WRIST OR ON CHARGING DOCK)";
    logLCARS("[🌙 SOMNO-03] No nocturnal sleep architecture found on watch for queried date. Displaying NO DATA.", "sys");
  }
}

