// =========================================================================
// H BAND-STYLE 24-HOUR DAILY SLEEP & NAP HYPNOGRAM RENDERER (00:01 - 23:59)
// Detailed stages: Deep Sleep (#15803d), Light Sleep (#2563eb), REM (#0891b2), Awake (#e11d48)
// =========================================================================
function formatMinToClock(minVal) {
  const m = Math.max(0, Math.min(1439, Math.round(minVal)));
  const h24 = Math.floor(m / 60);
  const mm = m % 60;
  const ampm = h24 >= 12 ? 'PM' : 'AM';
  const h12 = (h24 % 12) || 12;
  return `${h12}:${String(mm).padStart(2, '0')} ${ampm}`;
}

function renderNocturnalSleepHypnogram(containerId) {
  let container = document.getElementById(containerId);
  if (!container) {
    if (containerId === 'repChartSleep') container = document.getElementById('curveTimelineSleep');
  }
  if (!container) return;

  const sData = (window.lastDailySleepData && Array.isArray(window.lastDailySleepData.sessions))
    ? window.lastDailySleepData
    : null;
  const sessions = sData ? sData.sessions : [];

  if (!sData || sessions.length === 0 || (sData.totalMin || 0) <= 0) {
    container.innerHTML = `
      <div style="display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; min-height: 200px; color: #64748b; font-family: var(--lcars-mono); text-align: center; border: 1.5px dashed #cbd5e1; border-radius: 6px; background: rgba(248, 250, 252, 0.85); padding: 18px;">
        <div style="font-size: 1rem; font-weight: 800; color: #0284c7; letter-spacing: 0.05em; margin-bottom: 6px;">
          [NO SLEEP OR NAP RECORDED TODAY — AWAITING WATCH 0xE0 SYNC]
        </div>
        <div style="font-size: 0.78rem; color: #64748b;">
          Daily 24-hour hypnogram (00:01 to 23:59) updates automatically with nocturnal sleep &amp; daytime naps once watch sync completes.
        </div>
