  const totMin = sData.totalMin;
  const deepMin = sData.deepMin || 0;
  const lightMin = sData.lightMin || 0;
  const remMin = sData.remMin || 0;
  const awakeMin = sData.awakeMin || 0;
  const totH = parseFloat((totMin / 60.0).toFixed(1));
  const deepH = parseFloat((deepMin / 60.0).toFixed(1));
  const lightH = parseFloat((lightMin / 60.0).toFixed(1));
  const remH = parseFloat((remMin / 60.0).toFixed(1));
  const sleepEff = sData.efficiency || (totMin > 0 ? Math.round(((totMin - awakeMin) / totMin) * 100) : 0);

