    { name: "LIGHT SLEEP",    color: "#2563eb", bg: "rgba(219, 234, 254, 0.45)", border: "#bfdbfe", y: padTop + rowH * 2 },
    { name: "DEEP SLEEP",     color: "#15803d", bg: "rgba(220, 252, 231, 0.50)", border: "#86efac", y: padTop + rowH * 3 }
