16939:     function formatMinToClock(minVal) {
16940:       const m = Math.max(0, Math.min(1439, Math.round(minVal)));
16941:       const h24 = Math.floor(m / 60);
16942:       const mm = m % 60;
16943:       const ampm = h24 >= 12 ? 'PM' : 'AM';
16944:       const h12 = (h24 % 12) || 12;
16945:       return `${h12}:${String(mm).padStart(2, '0')} ${ampm}`;
16946:     }
