Set-Location D:\veepoo
@'
import os, re, sqlite3

plog = r'D:\veepoo\w11_htm_app\packet_log.txt'
with open(plog, 'rb') as f:
    sz = os.path.getsize(plog)
    f.seek(max(0, sz - 2000000))
    tail = f.read().decode('utf-8', errors='ignore')
lines = tail.splitlines()
print('Last 15 lines of packet_log.txt:')
for l in lines[-15:]:
    print(' ', l[:140])

op_counts = {}
for l in lines[-15000:]:
    m = re.search(r'(?:RX|TX|DATA|HEX|NOTIFY|BLE)[^0-9A-Fa-f]*([0-9A-Fa-f]{2}(?:\s+[0-9A-Fa-f]{2}){3,})', l, re.I)
    if not m:
        m = re.search(r'\b([0-9A-Fa-f]{2}(?:\s+[0-9A-Fa-f]{2}){5,})', l)
    if m:
        b0 = m.group(1).split()[0].upper()
        op_counts[b0] = op_counts.get(b0, 0) + 1
print('Tail 15k lines opcodes:', sorted(op_counts.items(), key=lambda x: -x[1])[:35])

# Check telemetry.db for ANY records between 2026-11-25T00:00 and 2026-11-25T09:00 WITHOUT Z vs WITH Z
conn = sqlite3.connect(r'D:\veepoo\w11_htm_app\telemetry.db')
cur = conn.cursor()
print('--- Count by hour (local) for 2026-11-25 across all metrics ---')
from datetime import datetime, timezone
rows = cur.execute("SELECT timestamp, metric, value1, value2 FROM vital_records WHERE timestamp >= '2026-11-24T20:00:00' ORDER BY timestamp ASC").fetchall()
hour_buckets = {}
for ts, met, v1, v2 in rows:
    try:
        s = ts.strip()
        if s.endswith('Z'):
            dt = datetime.fromisoformat(s[:-1]).replace(tzinfo=timezone.utc).astimezone().replace(tzinfo=None)
        else:
            dt = datetime.fromisoformat(s.replace(' ', 'T'))
        if dt.date().isoformat() == '2026-11-25':
            k = (dt.hour, met)
            hour_buckets[k] = hour_buckets.get(k, 0) + 1
    except Exception:
        pass
for h in range(24):
    mets = {m: c for (hh, m), c in hour_buckets.items() if hh == h}
    if mets:
        print(f'  2026-11-25 {h:02d}:00 -> {mets}')

print('--- Check if any 5-min / origin / D1 / D5 packets exist anywhere in packet_log tail ---')
for op in ['D1','D2','D3','D5','D9','E1','E5','E9','49','20','B0','D0']:
    ms = [l for l in lines[-20000:] if re.search(r'(?:^|\s|\]|:)' + op + r'\s+[0-9A-Fa-f]{2}\s+[0-9A-Fa-f]{2}\s+[0-9A-Fa-f]{2}', l.upper())]
    if ms:
        print(f'  OP {op} ({len(ms)}): {ms[-1][:140]}')
