    }
    const saved = localStorage.getItem('veepoo_user_config');
    if (saved) {
      const cfg = JSON.parse(saved);
      if (cfg && cfg.timeFormat !== undefined) {
        return parseInt(cfg.timeFormat, 10) !== 24;
      }
    }
  } catch (e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
  return true; // Default Model 5010 setting: 12-Hour AM/PM
}

function formatAxisHourLabel(hr) {
  if (!isWatch12HourFormat()) {
    return hr === 24 ? "24:00" : `${String(hr).padStart(2, '0')}:00`;
  }
  if (hr === 0 || hr === 24) return "12 AM";
  if (hr < 12) return `${hr} AM`;
  if (hr === 12) return "12 PM";
  return `${hr - 12} PM`;
}

function formatClockMin(minVal) {
  const m = Math.max(0, Math.min(1439, Math.round(minVal)));
  const h24 = Math.floor(m / 60);
  const mm = m % 60;
  if (!isWatch12HourFormat()) {
