async function runFullPipelineAndRefreshAllScreens() {
  // 1. Fetch ALL latest telemetry, 48-hr timeline, sleep, Lorenz R-R, and sub-reports in parallel
  try {
    await Promise.allSettled([
      (typeof pollLiveTelemetryChanges === 'function') ? pollLiveTelemetryChanges(true) : Promise.resolve(),
      (typeof fetchServer2DayTimeline === 'function') ? fetchServer2DayTimeline() : Promise.resolve(),
      (typeof fetchTodaySleepSessions === 'function') ? fetchTodaySleepSessions() : Promise.resolve(),
