20413:     function project3D(x, y, z, width, height) {
20414:       // CLE 3D perspective projection
20415:       const px = x + cam3D.panX;
20416:       const py = y + cam3D.panY;
20417:       const pz = z;
20418: 
20419:       // Rotation around Y (yaw)
20420:       const cosY = Math.cos(cam3D.yaw);
20421:       const sinY = Math.sin(cam3D.yaw);
20422:       const x1 = px * cosY - pz * sinY;
20423:       const z1 = px * sinY + pz * cosY;
20424: 
20425:       // Rotation around X (pitch)
20426:       const cosP = Math.cos(cam3D.pitch);
20427:       const sinP = Math.sin(cam3D.pitch);
20428:       const y2 = py * cosP - z1 * sinP;
20429:       const z2 = py * sinP + z1 * cosP + cam3D.distance;
20430: 
20431:       if (z2 <= 10) return null; // Behind camera clipping
20432:       const fov = 750 * cam3D.zoom;
20433:       const screenX = (width / 2) + (x1 * fov) / z2;
20434:       const screenY = (height / 2) - (y2 * fov) / z2;
20435:       return { x: screenX, y: screenY, z: z2 };
20436:     }
