20438:     function render3DMultiChannelScene() {
20439:       const pageReports = document.getElementById('pageReports');
20440:       if (!pageReports || !pageReports.classList.contains('active-page')) return;
20441:       const canvas = document.getElementById('canvas3DMultiChannel');
20442:       if (!canvas) return;
20443:       const ctx = canvas.getContext('2d');
20444:       if (!ctx) return;
20445: 
20446:       const W = canvas.width;
20447:       const H = canvas.height;
20448:       ctx.clearRect(0, 0, W, H);
20449: 
20450:       // Light Gray Technical Deck background gradient (SETI 3D Plot Box Model)
20451:       const bgGrad = ctx.createLinearGradient(0, 0, 0, H);
20452:       bgGrad.addColorStop(0, '#f8fafc');
20453:       bgGrad.addColorStop(1, '#e2e8f0');
20454:       ctx.fillStyle = bgGrad;
20455:       ctx.fillRect(0, 0, W, H);
20456: 
20457:       // Time points along X (-380 to +380) representing active timeframe (Daily, Weekly, Monthly, Quarterly, Yearly)
20458:       const tf = (typeof currentGlobalTimeframe !== 'undefined') ? currentGlobalTimeframe : (typeof currentTallChartTimeframe !== 'undefined' ? currentTallChartTimeframe : 'daily');
20459:       const dataset = (typeof getTallSynchronizedDataset === 'function') ? getTallSynchronizedDataset(tf) : [];
20460:       const numPoints = Math.max(2, dataset.length);
20461:       const xStep = 760 / (numPoints - 1);
20462:       const zSpacing = 52; // Spacing between channels along Z
20463:       const zStart = -((CHANNELS_3D.length - 1) * zSpacing) / 2;
20464: 
20465:       // Check if any real data exists across dataset
20466:       let hasRealData = false;
