20474:       if (overlay) overlay.style.display = hasRealData ? 'none' : 'flex';
20475: 
20476:       // =======================================================================
20477:       // SETI@home-STYLE 3D PLOT BOX WIREFRAME BOUNDING CAGE
20478:       // =======================================================================
20479:       const xBoxMin = -380; // Time Start
20480:       const xBoxMax = 380;  // Time End
20481:       const yBoxFloor = 0;  // Baseline / Floor
20482:       const yBoxCeil = 125; // Amplitude Ceiling
