20488:       const b100 = project3D(xBoxMax, yBoxFloor, zBoxFront, W, H); // Bottom-Front-Right
20489:       const b101 = project3D(xBoxMax, yBoxFloor, zBoxBack, W, H);  // Bottom-Back-Right
20490:       const b001 = project3D(xBoxMin, yBoxFloor, zBoxBack, W, H);  // Bottom-Back-Left
20491:       const b010 = project3D(xBoxMin, yBoxCeil,  zBoxFront, W, H); // Top-Front-Left
20492:       const b110 = project3D(xBoxMax, yBoxCeil,  zBoxFront, W, H); // Top-Front-Right
20493:       const b111 = project3D(xBoxMax, yBoxCeil,  zBoxBack, W, H);  // Top-Back-Right
20494:       const b011 = project3D(xBoxMin, yBoxCeil,  zBoxBack, W, H);  // Top-Back-Left
20495: 
20496:       // 1. Shaded Floor Plane (SETI@home 3D Plot Box light gray model deck)
20497:       if (b000 && b100 && b101 && b001) {
20498:         ctx.beginPath();
20499:         ctx.moveTo(b000.x, b000.y);
20500:         ctx.lineTo(b100.x, b100.y);
20501:         ctx.lineTo(b101.x, b101.y);
20502:         ctx.lineTo(b001.x, b001.y);
