20512:       if (b001 && b101 && b111 && b011) {
20513:         ctx.beginPath();
20514:         ctx.moveTo(b001.x, b001.y);
20515:         ctx.lineTo(b101.x, b101.y);
20516:         ctx.lineTo(b111.x, b111.y);
20517:         ctx.lineTo(b011.x, b011.y);
20518:         ctx.closePath();
