20523:       // 3. Shaded Left Wall Plane
20524:       if (b000 && b001 && b011 && b010) {
20525:         ctx.beginPath();
20526:         ctx.moveTo(b000.x, b000.y);
20527:         ctx.lineTo(b001.x, b001.y);
20528:         ctx.lineTo(b011.x, b011.y);
20529:         ctx.lineTo(b010.x, b010.y);
20530:         ctx.closePath();
20531:         ctx.fillStyle = 'rgba(241, 245, 249, 0.30)';
20532:         ctx.fill();
20533:       }
20534: 
20535:       // 4. Floor Grid Lines along Channels (Depth Z)
20536:       ctx.lineWidth = 1;
20537:       for (let c = 0; c < CHANNELS_3D.length; c++) {
20538:         const cz = zStart + c * zSpacing;
20539:         const p1 = project3D(xBoxMin, 0, cz, W, H);
20540:         const p2 = project3D(xBoxMax, 0, cz, W, H);
20541:         if (p1 && p2) {
20542:           ctx.strokeStyle = 'rgba(148, 163, 184, 0.45)';
20543:           ctx.beginPath();
20544:           ctx.moveTo(p1.x, p1.y);
20545:           ctx.lineTo(p2.x, p2.y);
20546:           ctx.stroke();
20547: 
20548:           // Channel Label at start of track
20549:           const pLbl = project3D(xBoxMin - 28, 0, cz, W, H);
20550:           if (pLbl) {
20551:             ctx.fillStyle = CHANNELS_3D[c].color;
20552:             ctx.font = 'bold 10px monospace';
20553:             ctx.textAlign = 'right';
20554:             ctx.textBaseline = 'middle';
20555:             ctx.fillText(CHANNELS_3D[c].name.replace('CH ', 'CH'), pLbl.x, pLbl.y);
20556:           }
20557:         }
20558:       }
20559: 
20560:       // 5. Time Grid lines along Floor at regular ticks
20561:       const numTicks = Math.min(6, numPoints - 1);
20562:       for (let t = 0; t <= numTicks; t++) {
20563:         const ptIdx = Math.min(numPoints - 1, Math.round((t / numTicks) * (numPoints - 1)));
20564:         const tx = xBoxMin + (ptIdx / (numPoints - 1)) * (xBoxMax - xBoxMin);
20565:         const pFront = project3D(tx, 0, zBoxFront, W, H);
20566:         const pBack = project3D(tx, 0, zBoxBack, W, H);
20567:         if (pFront && pBack) {
20568:           ctx.strokeStyle = 'rgba(148, 163, 184, 0.35)';
20569:           ctx.beginPath();
20570:           ctx.moveTo(pFront.x, pFront.y);
20571:           ctx.lineTo(pBack.x, pBack.y);
20572:           ctx.stroke();
20573: 
20574:           // Time / Epoch stamp at front (Honors Watch 12-Hour AM/PM Setting)
20575:           const pTime = project3D(tx, -14, zBoxFront - 6, W, H);
20576:           if (pTime && dataset[ptIdx]) {
20577:             ctx.fillStyle = '#475569';
20578:             ctx.font = 'bold 9px monospace';
20579:             ctx.textAlign = 'center';
20580:             const rawTick = dataset[ptIdx].time || dataset[ptIdx].day || `${ptIdx}`;
20581:             const tickLbl = /\d{1,2}:\d{2}/.test(String(rawTick)) ? formatTimeDisplay(String(rawTick)) : rawTick;
20582:             ctx.fillText(tickLbl, pTime.x, pTime.y);
20583:           }
20584:         }
