20587:       // 4b. Translucent Blue 3D Off-Wrist / Charging / Shower Holes Spanning All 10 Channels
20588:       const gapBlocks3D = [];
20589:       let curGap3D = null;
20590:       for (let i = 0; i < numPoints; i++) {
20591:         const dItem = dataset[i] || {};
20592:         if (!dItem.isFuture && !!dItem.isChargingGap) {
20593:           if (!curGap3D) curGap3D = { start: i, end: i };
20594:           else curGap3D.end = i;
20595:         } else if (curGap3D) {
20596:           gapBlocks3D.push(curGap3D);
20597:           curGap3D = null;
20598:         }
20599:       }
20600:       if (curGap3D) gapBlocks3D.push(curGap3D);
20601: 
20602:       const xOf3D = i => -380 + i * xStep;
20603:       const gap3DStartMap = {};
20604:       const gap3DEndMap = {};
