  function enrichBiometrics(dataset) {
    // Pre-index user's real prescribed medications (strictly non-synthetic, Prime Directive 4)
    const realMeds = (typeof medicationList !== 'undefined' && Array.isArray(medicationList))
      ? medicationList.filter(m => m && m.status !== 'Discontinued')
      : [];
    const morningMeds = realMeds.filter(m => m.slot !== 'dinner');
    const dinnerMeds = realMeds.filter(m => m.slot === 'dinner');
    const medChanges = (typeof medicationChangeLog !== 'undefined' && Array.isArray(medicationChangeLog)) ? medicationChangeLog : [];
    const sData = (window.lastDailySleepData && Array.isArray(window.lastDailySleepData.sessions)) ? window.lastDailySleepData : null;

    return dataset.map((d) => {
      const item = Object.assign({}, d);
      // Zero synthetic HR/BP overwrites — preserve genuine watch measurements verbatim
      if (item.fluidOz === undefined || item.fluidOz === null) item.fluidOz = 0;
      if (item.cumFluidOz === undefined || item.cumFluidOz === null) item.cumFluidOz = 0;

      if (item.meal) {
        const m = Object.assign({}, item.meal);
        if (!m.cal) m.cal = (m.carbs > 30 ? 490 : 380);
        if (!m.protein) m.protein = (m.carbs > 30 ? 32 : 24);
        if (!m.fat) m.fat = (m.carbs > 30 ? 16 : 12);
        if (!m.gl) m.gl = (m.carbs <= 15 ? 1 : (m.carbs <= 35 ? 3 : 8));
        item.meal = m;
      }

      // Map real 0xE0 sleep session if backend slot didn't already carry sleepPct
      if (!item.isFuture && (!item.sleepPct || item.sleepPct <= 0) && sData && item.time && /^\d{2}:\d{2}/.test(item.time)) {
        const pH = parseInt(item.time.substring(0, 2), 10);
        const pM = parseInt(item.time.substring(3, 5), 10);
        const slotS = pH * 60 + pM;
        const slotE = slotS + 30;
        const hit = sData.sessions.find(s => Math.max(slotS, s.startM || 0) < Math.min(slotE, s.endM || 0));
        if (hit) {
          item.sleepPct = hit.isNap ? 75 : 85;
          item.isNap = !!hit.isNap;
        }
      }
      if (item.sleepPct === undefined || item.sleepPct === null) item.sleepPct = 0;

      // Map real user medications (never fake hardcoded prescriptions)
      if (!item.med && !item.isFuture && item.time && /^\d{2}:\d{2}/.test(item.time)) {
        if (item.time === '08:30' && morningMeds.length > 0) {
          item.med = {
            name: morningMeds.map(m => `${m.name}${m.dose ? ' ' + m.dose : ''}`).join(', '),
            taken: morningMeds.some(m => m.lastTaken && !String(m.lastTaken).includes('Pending')),
            isMedChange: medChanges.length > 0 && item.day === 'TODAY'
          };
        } else if (item.time === '19:00' && dinnerMeds.length > 0) {
          item.med = {
            name: dinnerMeds.map(m => `${m.name}${m.dose ? ' ' + m.dose : ''}`).join(', '),
            taken: dinnerMeds.some(m => m.lastTaken && !String(m.lastTaken).includes('Pending')),
            isMedChange: false
          };
        }
      }

      // Merge real feeling_entries (Pain / Mood) fallback
      if (!item.isFuture && (item.pain == null || item.mood == null) && typeof feelingCache3D !== 'undefined' && Array.isArray(feelingCache3D) && feelingCache3D.length > 0 && item.time && /^\d{2}:\d{2}/.test(item.time)) {
        const slotH = parseInt(item.time.substring(0, 2), 10);
        const matchF = feelingCache3D.find(f => {
          if (!f.timestamp) return false;
          const fDt = new Date(f.timestamp);
          return !isNaN(fDt.getTime()) && fDt.getHours() === slotH && (!item.date || f.timestamp.startsWith(item.date));
        });
        if (matchF) {
          if (item.pain == null && matchF.pain_score != null) item.pain = matchF.pain_score;
          if (item.mood == null && matchF.mood_score != null) item.mood = matchF.mood_score;
        }
      }
      return item;
    });
  }

