    if (!d.isFuture && d.fluidOz > 0) {
      const py = flPtsList[i].y;
      svg += `
        <g style="cursor: pointer;" onclick="openTimelinePointCard(${i})">
          <circle cx="${xCoords[i].toFixed(1)}" cy="${py.toFixed(1)}" r="4.5" fill="#0284c7" stroke="#ffffff" stroke-width="1.4"/>
          <text x="${xCoords[i].toFixed(1)}" y="${Math.max(flLane.y + 11, py - 7).toFixed(1)}" text-anchor="middle" fill="#0369a1" font-size="8" font-weight="900">+${d.fluidOz}oz</text>
        </g>
      `;
    }
  });

  // CH 10: Medications & Titration Changes (Strictly Real User medicationList)
  const mLane = lanes[9];
  data.forEach((d, i) => {
    if (d.med) {
      const isChange = d.med.isMedChange || (d.notes && d.notes.includes("MED CHANGE"));
      if (isChange) {
        svg += `
          <line x1="${xCoords[i]}" y1="18" x2="${xCoords[i]}" y2="${H - 42}" stroke="#ff5555" stroke-dasharray="4 4" stroke-width="1.8"/>
          <g style="cursor: pointer;" onclick="openTimelinePointCard(${i})">
            <rect x="${xCoords[i] - 42}" y="${mLane.y + 8}" width="84" height="22" fill="#fef2f2" stroke="#ef4444" stroke-width="1.6" rx="4"/>
            <text x="${xCoords[i]}" y="${mLane.y + 22}" text-anchor="middle" fill="#991b1b" font-size="8.5" font-weight="900">💊 MED CHANGE</text>
          </g>
        `;
      } else {
        svg += `
          <g style="cursor: pointer;" onclick="openTimelinePointCard(${i})">
            <polygon points="${xCoords[i]},${mLane.y + 38} ${xCoords[i] - 7},${mLane.y + 23} ${xCoords[i] + 7},${mLane.y + 23}" fill="#2563eb" stroke="#ffffff" stroke-width="1.4"/>
            <text x="${xCoords[i]}" y="${mLane.y + 19}" text-anchor="middle" fill="#1e40af" font-size="8.5" font-weight="900">▼ Rx</text>
          </g>
        `;
      }
    }
  });

  // CH 11: Sleep Architecture (% from 0xE0 nocturnal + daytime nap sessions)
  const slLane = lanes[10];
  data.forEach((d, i) => {
    if (d.isFuture || d.isChargingGap || !d.sleepPct || d.sleepPct <= 0) return;
    const barH = (Math.min(100, d.sleepPct) / 100) * (slLane.h - 12);
    const barY = slLane.y + slLane.h - barH - 2;
    const slColor = d.sleepPct >= 90 ? "#15803d" : (d.isNap ? "#0891b2" : "#6366f1");
    svg += `<rect x="${(xCoords[i] - 9).toFixed(1)}" y="${barY.toFixed(1)}" width="18" height="${barH.toFixed(1)}" fill="${slColor}" fill-opacity="0.38" stroke="${slColor}" stroke-width="1.2" rx="2"/>`;
  });

  // CH 12: Pain & Mood (0-10 from feeling_entries)
  const pmLane = lanes[11];
  data.forEach((d, i) => {
    if (d.isFuture || d.isChargingGap) return;
    if (d.pain !== null && d.pain !== undefined) {
      const py = pmLane.y + pmLane.h - (Math.min(10, Math.max(0, d.pain)) / 10) * (pmLane.h - 10) - 5;
      svg += `<circle cx="${xCoords[i].toFixed(1)}" cy="${py.toFixed(1)}" r="4" fill="#dc2626" stroke="#ffffff" stroke-width="1.2"/><text x="${xCoords[i].toFixed(1)}" y="${(py - 6).toFixed(1)}" text-anchor="middle" fill="#991b1b" font-size="7.5" font-weight="900">P:${d.pain}</text>`;
    }
    if (d.mood !== null && d.mood !== undefined) {
      const my = pmLane.y + pmLane.h - (Math.min(10, Math.max(0, d.mood)) / 10) * (pmLane.h - 10) - 5;
      svg += `<circle cx="${xCoords[i].toFixed(1)}" cy="${my.toFixed(1)}" r="4" fill="#14b8a6" stroke="#ffffff" stroke-width="1.2"/><text x="${xCoords[i].toFixed(1)}" y="${(my + 11).toFixed(1)}" text-anchor="middle" fill="#0f766e" font-size="7.5" font-weight="900">M:${d.mood}</text>`;
    }
  });

  // Interactive Glucose Points
  gPts.forEach((p, i) => {
    if (p.val !== null && !p.isGap && p.val > 0) {
      svg += `
        <g style="cursor: pointer;" onclick="openTimelinePointCard(${i})">
          <circle class="plot-point" cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="5" fill="#ea580c" stroke="#ffffff" stroke-width="1.8">
            <title>Biometric Function Monitor</title>
          </circle>
          <rect x="${(p.x - 13).toFixed(1)}" y="${(p.y - 19).toFixed(1)}" width="26" height="12" rx="3" fill="#ffffff" stroke="#cbd5e1" stroke-width="1"/>
          <text x="${p.x.toFixed(1)}" y="${(p.y - 10).toFixed(1)}" text-anchor="middle" fill="#78350f" font-size="8.5" font-weight="900">${p.val}</text>
        </g>
      `;
    }
  });

  // Bottom Shared Time Axis Labels (Honors 12/24h Watch Setting)
  let tickStep = 1;
  if (n > 30) tickStep = 6;
  else if (n > 16) tickStep = 4;
  else if (n > 8) tickStep = 2;

  for (let i = 0; i < n; i += tickStep) {
    svg += `
      <text x="${xCoords[i]}" y="${H - 16}" text-anchor="middle" fill="var(--lcars-gray)" font-size="10.5" font-weight="bold">${formatTimeDisplay(data[i].time)}</text>
      <line x1="${xCoords[i]}" y1="${H - 35}" x2="${xCoords[i]}" y2="${H - 28}" stroke="#253549" stroke-width="1.2"/>
    `;
  }
  if ((n - 1) % tickStep !== 0) {
    const lastIdx = n - 1;
    svg += `
      <text x="${xCoords[lastIdx]}" y="${H - 16}" text-anchor="middle" fill="var(--lcars-gray)" font-size="10.5" font-weight="bold">${formatTimeDisplay(data[lastIdx].time)}</text>
      <line x1="${xCoords[lastIdx]}" y1="${H - 35}" x2="${xCoords[lastIdx]}" y2="${H - 28}" stroke="#253549" stroke-width="1.2"/>
    `;
  }

  // Vertical Scrubber Line Spanning All 12 Lanes
  const initialScrubberX = padLeft + (plotW * 0.5);
  svg += `
    <line id="tallVerticalScrubberLine" x1="${initialScrubberX.toFixed(1)}" y1="18" x2="${initialScrubberX.toFixed(1)}" y2="${H - 35}" stroke="var(--lcars-banana)" stroke-width="2.5" stroke-dasharray="6 3" opacity="0.95" style="pointer-events: none;"/>
    <polygon id="tallScrubberHead" points="${initialScrubberX - 7},14 ${initialScrubberX + 7},14 ${initialScrubberX},21" fill="var(--lcars-banana)" style="pointer-events: none;"/>
  `;

  svg += `</svg>`;
  container.innerHTML = svg;

  let initIdx = Math.floor(n / 2);
  for (let i = n - 1; i >= 0; i--) {
    if (data[i] && !data[i].isChargingGap && data[i].g !== null && !data[i].isFuture) {
      initIdx = i;
      break;
    }
  }
  const initPct = n > 1 ? (initIdx / (n - 1)) * 100 : 50;
  const sld = document.getElementById('tallScrubberSlider');
  if (sld) sld.value = initPct;
  onTallScrubberMoved(initPct);
}

// Interactive Scrubber Movement Handler
function onTallScrubberMoved(percent) {
  const data = activeTallDataset;
  if (!data || data.length === 0) return;

  const W = 1000;
  const padLeft = 132;
  const padRight = 45;
  const plotW = W - padLeft - padRight;

  const pNorm = Math.max(0, Math.min(100, parseFloat(percent))) / 100;
  const currentX = padLeft + (pNorm * plotW);

  const scrubber = document.getElementById('tallVerticalScrubberLine');
  const head = document.getElementById('tallScrubberHead');
  if (scrubber) {
    scrubber.setAttribute('x1', currentX.toFixed(1));
    scrubber.setAttribute('x2', currentX.toFixed(1));
  }
  if (head) {
    head.setAttribute('points', `${currentX - 7},14 ${currentX + 7},14 ${currentX},21`);
  }

  const n = data.length;
  const idx = Math.min(n - 1, Math.max(0, Math.round(pNorm * (n - 1))));
  const pt = data[idx];

  const timeBadge = document.getElementById('tallScrubberTimeBadge');
  const hG = document.getElementById('hudGlucose');
  const hBp = document.getElementById('hudBp');
  const hHr = document.getElementById('hudHrHrv');
  const hSp = document.getElementById('hudSpo2');
  const hT = document.getElementById('hudTemp');
  const hEx = document.getElementById('hudExercise');

  if (pt.isChargingGap) {
    if (timeBadge) timeBadge.textContent = `TIMESTAMP: ${formatTimeDisplay(pt.time)} (⚡ WATCH CHARGING ON DOCK • 0 TELEMETRY)`;
    if (hG) hG.textContent = `0 mg/dL (Charging)`;
    if (hBp) hBp.textContent = `-- / -- (Off-Wrist)`;
    if (hHr) hHr.textContent = `0 BPM / 0 ms`;
    if (hSp) hSp.textContent = `-- %`;
    if (hT) hT.textContent = `--.- °F`;
    if (hEx) hEx.textContent = `0 steps • Watch Off-Wrist`;
  } else {
    if (timeBadge) timeBadge.textContent = `TIMESTAMP: ${formatTimeDisplay(pt.time)} (${pt.meal ? pt.meal.type : (pt.ex ? pt.ex.type : (pt.sleepPct > 0 ? (pt.isNap ? 'Daytime Nap' : 'Sleep') : 'Diurnal State'))})`;
    if (hG) hG.textContent = (pt.g !== null && pt.g > 0) ? `${pt.g} mg/dL` : `-- mg/dL`;
    if (hBp) hBp.textContent = (pt.sys && pt.sys > 0) ? `${pt.sys}/${pt.dia} mmHg` : `--/-- mmHg`;
    if (hHr) hHr.textContent = (pt.hr && pt.hr > 0) ? `${pt.hr} BPM / ${pt.hrv || '--'} ms` : `-- BPM / -- ms`;
    if (hSp) hSp.textContent = (pt.spo2 && pt.spo2 > 0) ? `${pt.spo2}%` : `-- %`;
    if (hT) hT.textContent = `${pt.temp ? pt.temp.toFixed(1) : '--.-'}°F`;
    if (hEx) {
      hEx.textContent = pt.ex ? `${pt.steps} steps • ${pt.ex.type} (${pt.ex.delta <= 0 ? pt.ex.delta : '+' + pt.ex.delta} mg/dL)` : `${pt.steps} steps • Resting Homeostasis`;
    }
  }

  const hD = document.getElementById('hudDiet');
  if (hD) {
    const flStr = (pt.cumFluidOz > 0 || pt.fluidOz > 0) ? ` • 💧 ${pt.fluidOz > 0 ? '+' + pt.fluidOz + ' oz (' : ''}${pt.cumFluidOz} oz total${pt.fluidOz > 0 ? ')' : ''}` : '';
    hD.textContent = pt.meal ? `${pt.meal.type}: ${pt.meal.desc} (${pt.meal.carbs}g carbs)${flStr}` : (flStr ? `Fasting${flStr}` : "Fasting / In-Between Meals");
  }

  const hM = document.getElementById('hudMeds');
  if (hM) {
    hM.textContent = pt.med ? `${pt.med.name} ${pt.med.isMedChange ? '★ TITRATION MILESTONE' : 'Active'}` : "[NO MEDICATIONS RECORDED]";
  }
}

function onTallChartMouseMove(evt) {
  const container = document.getElementById('tallChartSvgContainer');
  if (!container) return;
  const rect = container.getBoundingClientRect();
  const relX = evt.clientX - rect.left;
  const padLeft = (132 / 1000) * rect.width;
  const padRight = (45 / 1000) * rect.width;
  const plotW = rect.width - padLeft - padRight;

  if (relX >= padLeft && relX <= padLeft + plotW) {
    const pct = ((relX - padLeft) / plotW) * 100;
    const slider = document.getElementById('tallScrubberSlider');
    if (slider) slider.value = pct;
    onTallScrubberMoved(pct);
  }
}

function onTallChartClick(evt) {
  const data = activeTallDataset;
  if (!data || data.length === 0) return;
  const slider = document.getElementById('tallScrubberSlider');
  const pct = slider ? parseFloat(slider.value) : 50;
  const idx = Math.min(data.length - 1, Math.max(0, Math.round((pct / 100) * (data.length - 1))));
  openTimelinePointCard(idx);
}

// -------------------------------------------------------------------------
// 5. INTERACTIVE TIMELINE POINT AUDIT CARD MODAL
// -------------------------------------------------------------------------
function openTimelinePointCard(idx) {
  soundButtonPress();
  const data = activeTallDataset;
  if (!data || !data[idx]) return;
  const pt = data[idx];

  const modal = document.getElementById('timelinePointCardModal');
  if (!modal) return;
  modal.style.position = 'absolute';
  modal.style.top = '210px';
  modal.style.left = '50%';
  modal.style.transform = 'translateX(-50%)';
  modal.style.zIndex = '9999';

  const dispTime = formatTimeDisplay(pt.time);
  const title = document.getElementById('cardModalTitle');
  const gVal = document.getElementById('cardModalGlucose');
  const bpVal = document.getElementById('cardModalBp');
  const spVal = document.getElementById('cardModalSpo2Hr');
  const dietB = document.getElementById('cardModalDietBadge');
  const dietD = document.getElementById('cardModalDietDesc');
  const dietM = document.getElementById('cardModalDietMacros');
  const exB = document.getElementById('cardModalExBadge');
  const exD = document.getElementById('cardModalExDesc');
  const exG = document.getElementById('cardModalExGlut4');
  const medB = document.getElementById('cardModalMedBadge');
  const medD = document.getElementById('cardModalMedDesc');
  const ins = document.getElementById('cardModalInsight');

  if (pt.isChargingGap) {
    if (title) title.textContent = `POINT AUDIT: ${dispTime} (WATCH NOT SENSING • OFF-WRIST / CHARGING)`;
    if (gVal) gVal.textContent = `0 mg/dL`;
    if (bpVal) bpVal.textContent = `0/0 mmHg`;
    if (spVal) spVal.textContent = `0% / 0 BPM`;
    if (dietB) dietB.textContent = "CHARGING GAP";
    if (dietD) dietD.textContent = "Watch removed from wrist for charging or showering. Zero sensor telemetry recorded.";
    if (dietM) dietM.textContent = "Zero biometric data recorded.";
    if (exB) exB.textContent = "OFF-WRIST";
    if (exD) exD.textContent = "Watch sensor offline in charging dock.";
    if (exG) exG.textContent = "0 Steps / 0 MET";
    if (medB) medB.textContent = "MEDICATIONS";
    if (medD) medD.textContent = "[NO MEDICATIONS RECORDED]";
    if (ins) ins.textContent = "Watch hardware removed from wrist. Optical transducers inactive.";
    modal.style.display = 'block';
    return;
  }
  if (pt.isFuture) {
    if (title) title.textContent = `POINT AUDIT: ${dispTime} (UNELAPSED FUTURE INTERVAL)`;
    if (gVal) gVal.textContent = `0 mg/dL`;
    if (bpVal) bpVal.textContent = `0/0 mmHg`;
    if (spVal) spVal.textContent = `0% / 0 BPM`;
    if (dietB) dietB.textContent = "FUTURE INTERVAL";
    if (dietD) dietD.textContent = "[NO NUTRITION LOGGED — FUTURE INTERVAL]";
    if (dietM) dietM.textContent = "0g Net Carbs • Awaiting live time";
    if (exB) exB.textContent = "FUTURE INTERVAL";
    if (exD) exD.textContent = "0 Steps (Future window)";
    if (exG) exG.textContent = "0 Steps";
    if (medB) medB.textContent = "MEDICATIONS";
    if (medD) medD.textContent = "[NO MEDICATIONS RECORDED]";
    if (ins) ins.textContent = "Interval has not yet elapsed. Strict Zero-Data reality displays 0.";
    modal.style.display = 'block';
    return;
  }

  if (title) title.textContent = `POINT AUDIT: ${dispTime} (${pt.notes || 'Clinical Telemetry'})`;
  if (gVal) gVal.textContent = `${pt.g || 0} mg/dL`;
  if (bpVal) bpVal.textContent = `${pt.sys || 0}/${pt.dia || 0} mmHg`;
  if (spVal) spVal.textContent = `${pt.spo2 || 0}% / ${pt.hr || 0} BPM`;

  if (pt.meal) {
    if (dietB) dietB.textContent = (pt.meal.type || "Meal").toUpperCase();
    if (dietD) dietD.textContent = pt.meal.desc || pt.meal.name || "Dietary Ingestion";
    const cal = pt.meal.cal || 430;
    const pro = pt.meal.protein || 24;
    const fat = pt.meal.fat || 14;
    const gl = pt.meal.gl || 2;
    const flNote = pt.fluidOz > 0 ? ` • 💧 ${pt.fluidOz} fl oz (Cum ${pt.cumFluidOz} fl oz)` : '';
    if (dietM) dietM.innerHTML = `<strong>${cal} kcal</strong> • <strong>${pt.meal.carbs}g Net Carbs</strong> • <strong>${pro}g Protein</strong> • <strong>${fat}g Fat</strong> (GL: ${gl})${flNote}`;

    let postPeak = pt.g || 140;
    let peakTime = pt.time;
    for (let j = idx + 1; j < Math.min(idx + 5, data.length); j++) {
      if (data[j] && data[j].g && data[j].g > postPeak) {
        postPeak = data[j].g;
        peakTime = data[j].time;
      }
    }
    const preG = pt.g || 148;
    const deltaG = postPeak - preG;
    const hasGlut4 = pt.ex || (data[idx+1] && data[idx+1].ex) || (data[idx+2] && data[idx+2].ex);

    if (ins) {
      ins.innerHTML = `
        <div style="background: #fff7ed; border: 1.5px solid #fdba74; border-radius: 6px; padding: 10px 12px; margin-top: 4px;">
          <strong style="color: #c2410c; font-size: 0.95rem;">📊 RETROSPECTIVE MEAL EXCURSION AUDIT (CLINICAL TRAJECTORY)</strong>
          <div style="font-size: 0.85rem; color: #1e293b; margin-top: 4px;">
            Pre-Meal Baseline: <strong>${preG} mg/dL</strong> ➔ Postprandial Peak: <strong>${postPeak} mg/dL</strong> (ΔG: <strong style="color: ${deltaG > 40 ? '#b91c1c' : '#15803d'};">${deltaG >= 0 ? '+' + deltaG : deltaG} mg/dL</strong> at ${formatTimeDisplay(peakTime)}).
          </div>
          <div style="font-size: 0.8rem; color: ${hasGlut4 ? '#15803d' : '#b45309'}; font-weight: bold; margin-top: 5px;">
            ${hasGlut4 ? '✓ Post-meal brisk GLUT4 walk detected, accelerating return to safe euglycemia.' : '⚡ Sedentary postprandial window: Recommend 15-minute GLUT4 walk 20 min post-meal to attenuate spike.'}
          </div>
        </div>`;
    }
  } else {
    if (dietB) dietB.textContent = "FASTING / BASAL";
    if (dietD) dietD.textContent = "[NO NUTRITION LOGGED IN THIS EPOCH]";
    if (dietM) dietM.textContent = `0g Net Carbs • Fluid Cumulative: ${pt.cumFluidOz || 0} fl oz`;
  }

  if (pt.ex) {
    if (exB) exB.textContent = pt.ex.type.toUpperCase();
    if (exD) exD.textContent = `${pt.ex.desc} (${pt.ex.dur} minutes).`;
    if (exG) exG.textContent = `${pt.steps} Steps • Non-Insulin GLUT4 Clearance: ${pt.ex.delta <= 0 ? pt.ex.delta : '+' + pt.ex.delta} mg/dL`;
  } else {
    if (exB) exB.textContent = "SEDENTARY / BASAL";
    if (exD) exD.textContent = `Daily cumulative step count: ${pt.steps || 0} steps.`;
    if (exG) exG.textContent = "Standard resting glucose consumption";
  }

  if (pt.med) {
    if (medB) medB.textContent = pt.med.isMedChange ? "TITRATION EVENT" : "ACTIVE REGIMEN";
    if (medD) medD.textContent = `${pt.med.name}. ${pt.med.isMedChange ? 'Prescription adjusted by attending physician. Evaluated for progress vs regression.' : 'Standard therapeutic maintenance dosage.'}`;
  } else {
    if (medB) medB.textContent = "MAINTENANCE";
    if (medD) medD.textContent = "[NO MEDICATIONS RECORDED]";
  }

  if (ins && !pt.meal) {
    ins.textContent = pt.notes || `At ${dispTime}, optical PPG reading was ${pt.g || '--'} mg/dL. Telemetry tracked across wear period.`;
  }

  modal.style.display = 'block';
}

