function renderTallSynchronizedChart(tf) {
  const container = document.getElementById('tallChartSvgContainer');
  if (!container) return;

  activeTallDataset = getTallSynchronizedDataset(tf);
  const data = activeTallDataset;
  const n = data.length;

  const W = 1000;
  const H = 840;
  const padLeft = 110;
  const padRight = 45;
  const plotW = W - padLeft - padRight;

  // Update slider bounds & labels
  const sStart = document.getElementById('tallScrubberStartLbl');
  const sEnd = document.getElementById('tallScrubberEndLbl');
  if (sStart && data[0]) sStart.textContent = formatTimeDisplay(data[0].time);
  if (sEnd && data[n-1]) sEnd.textContent = formatTimeDisplay(data[n-1].time);

  // Lane Coordinates (Y positions)
  const lanes = [
    { id: "glucose", label: "GLUCOSE (MG/DL)", y: 25, h: 95, minY: 50, maxY: 250, color: "#b45309", unit: "mg/dL" },
    { id: "bp", label: "BLOOD PRESSURE (MMHG)", y: 135, h: 85, minY: 50, maxY: 170, color: "#c2410c", unit: "mmHg" },
    { id: "hr", label: "PULSE & HRV (BPM / MS)", y: 235, h: 80, minY: 40, maxY: 120, color: "#b91c1c", unit: "BPM" },
    { id: "spo2", label: "OXYGEN SPO2 (%)", y: 330, h: 70, minY: 90, maxY: 100, color: "#15803d", unit: "%" },
    { id: "temp", label: "TEMPERATURE (°F)", y: 415, h: 65, minY: 90.0, maxY: 100.5, color: "#1d4ed8", unit: "°F" },
    { id: "exercise", label: "EXERCISE & STEPS", y: 495, h: 80, minY: 0, maxY: 8000, color: "#c2410c", unit: "steps" },
    { id: "diet", label: "DIETARY INTAKE & CARBS", y: 590, h: 80, minY: 0, maxY: 80, color: "#7c3aed", unit: "g" },
    { id: "meds", label: "MEDICATIONS & CHANGES", y: 685, h: 75, minY: 0, maxY: 10, color: "#b45309", unit: "" }
  ];

  // Build SVG
  let svg = `<svg viewBox="0 0 ${W} ${H}" width="100%" height="${H}" style="display: block; font-family: var(--lcars-mono);" id="svgTallMaster">`;

  // Gradients & Defs
  svg += `
    <defs>
      <linearGradient id="gradTallGlucose" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#ea580c" stop-opacity="0.25"/>
        <stop offset="100%" stop-color="var(--lcars-banana)" stop-opacity="0.0"/>
      </linearGradient>
      <linearGradient id="gradTallTir" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="rgba(85,255,119,0.18)"/>
        <stop offset="100%" stop-color="rgba(85,255,119,0.06)"/>
      </linearGradient>
    </defs>
  `;

  // Lane Backgrounds & Y-Axes
  lanes.forEach((lane, lIdx) => {
    svg += `
      <!-- Lane ${lane.id} Background -->
      <rect x="${padLeft}" y="${lane.y}" width="${plotW}" height="${lane.h}" fill="#ffffff" stroke="#e2e8f0" stroke-width="1"/>
      <!-- Lane Title Label -->
      <text x="${padLeft - 10}" y="${lane.y + 16}" text-anchor="end" fill="${lane.color}" font-size="10.5" font-weight="bold">${lane.label}</text>
      <text x="${padLeft - 10}" y="${lane.y + lane.h - 6}" text-anchor="end" fill="var(--lcars-gray)" font-size="9">${lane.unit}</text>
    `;

    // Glucose Shaded Target Band (60 - 200 mg/dL TIR)
    if (lane.id === "glucose") {
      const tirYTop = lane.y + lane.h - ((200 - lane.minY) / (lane.maxY - lane.minY)) * lane.h;
      const tirYBottom = lane.y + lane.h - ((60 - lane.minY) / (lane.maxY - lane.minY)) * lane.h;
      const tirHeight = tirYBottom - tirYTop;
      svg += `
        <rect x="${padLeft}" y="${tirYTop.toFixed(1)}" width="${plotW}" height="${tirHeight.toFixed(1)}" fill="url(#gradTallTir)" stroke="rgba(85,255,119,0.35)" stroke-dasharray="3 3"/>
        <text x="${padLeft + plotW - 6}" y="${tirYTop + 12}" text-anchor="end" fill="var(--lcars-green)" font-size="9" opacity="0.8">TIR SAFE BAND (60-200 MG/DL)</text>
      `;
    }

    // Blood Pressure Normal Reference Lines (120/80)
    if (lane.id === "bp") {
      const y120 = lane.y + lane.h - ((120 - lane.minY) / (lane.maxY - lane.minY)) * lane.h;
      const y80 = lane.y + lane.h - ((80 - lane.minY) / (lane.maxY - lane.minY)) * lane.h;
      svg += `
        <line x1="${padLeft}" y1="${y120.toFixed(1)}" x2="${padLeft + plotW}" y2="${y120.toFixed(1)}" stroke="#ff9944" stroke-dasharray="4 4" stroke-width="1" opacity="0.5"/>
        <line x1="${padLeft}" y1="${y80.toFixed(1)}" x2="${padLeft + plotW}" y2="${y80.toFixed(1)}" stroke="#38b6ff" stroke-dasharray="4 4" stroke-width="1" opacity="0.5"/>
        <text x="${padLeft + plotW - 6}" y="${y120 - 3}" text-anchor="end" fill="#ff9944" font-size="8.5" opacity="0.75">120 SYSTOLIC</text>
        <text x="${padLeft + plotW - 6}" y="${y80 - 3}" text-anchor="end" fill="#38b6ff" font-size="8.5" opacity="0.75">80 DIASTOLIC</text>
      `;
    }

    // SpO2 95% Hypoxia Alert Line
    if (lane.id === "spo2") {
      const y95 = lane.y + lane.h - ((95 - lane.minY) / (lane.maxY - lane.minY)) * lane.h;
      svg += `
        <line x1="${padLeft}" y1="${y95.toFixed(1)}" x2="${padLeft + plotW}" y2="${y95.toFixed(1)}" stroke="#ff5555" stroke-dasharray="4 4" stroke-width="1" opacity="0.6"/>
        <text x="${padLeft + plotW - 6}" y="${y95 - 3}" text-anchor="end" fill="#ff5555" font-size="8.5" opacity="0.75">95% NOCTURNAL HYPOXIA THRESHOLD</text>
      `;
    }
  });

  // Compute Point Coordinates across all lanes
  const xCoords = data.map((d, i) => padLeft + (n > 1 ? (i / (n - 1)) * plotW : plotW / 2));

  // Group contiguous gap indices into single clean charging/shower blocks ONLY
  const gapBlocks = [];
  let curBlock = null;
  data.forEach((d, i) => {
    const isGap = !d.isFuture && !!d.isChargingGap;
    if (isGap) {
      if (!curBlock) curBlock = { start: i, end: i };
      else curBlock.end = i;
    } else {
      if (curBlock) {
        gapBlocks.push(curBlock);
        curBlock = null;
      }
    }
  });
  if (curBlock) gapBlocks.push(curBlock);

  // Compute Exact Midpoint Geometry for Contiguous Off-Wrist / Charging / Shower Blue Holes
  const gapMeta = gapBlocks.map(blk => {
    const xLeft = blk.start > 0 ? (xCoords[blk.start - 1] + xCoords[blk.start]) / 2 : xCoords[blk.start];
    const xRight = blk.end < n - 1 ? (xCoords[blk.end] + xCoords[blk.end + 1]) / 2 : xCoords[blk.end];
    return { start: blk.start, end: blk.end, xLeft, xRight };
  });
  const gapStartMap = {};
  const gapEndMap = {};
  gapMeta.forEach(gm => {
    gapStartMap[gm.start] = gm.xLeft;
    gapEndMap[gm.end] = gm.xRight;
    const gapW = Math.max(18, gm.xRight - gm.xLeft);
    svg += `
      <!-- Contiguous Watch Charging / Off-Wrist Region (Exact Midpoint Blue Hole Across All Lanes) -->
      <rect x="${gm.xLeft.toFixed(1)}" y="20" width="${gapW.toFixed(1)}" height="${H - 55}" fill="rgba(56, 189, 248, 0.18)" stroke="#0284c7" stroke-dasharray="4 3" rx="3">
        <title>Watch off-wrist / charging / shower</title>
      </rect>
    `;
  });

  // Helper to generate discontinuous SVG path segments extending cleanly to the exact edges of blue off-wrist holes
  function buildSegmentedPath(pts, laneObj) {
    let pathD = "";
    let areaD = "";
    const runs = [];
    let curRun = null;

    pts.forEach((p, idx) => {
      const isFutureSlot = data[idx] && data[idx].isFuture;
      if (p.isGap || isFutureSlot) {
        if (curRun) { runs.push(curRun); curRun = null; }
      } else {
        if (!curRun) curRun = { startIdx: idx, endIdx: idx, measured: [] };
        curRun.endIdx = idx;
        if (p.val !== null && p.val !== undefined && p.val > 0) {
          curRun.measured.push(p);
        }
      }
    });
    if (curRun) runs.push(curRun);

    runs.forEach(run => {
      if (run.measured.length === 0) return;
      const seq = [...run.measured];
      // Extend right edge of preceding blue hole into first measured point of this worn run
      if (run.startIdx > 0 && gapEndMap[run.startIdx - 1] !== undefined) {
        const rxEdge = gapEndMap[run.startIdx - 1];
        if (seq[0].x > rxEdge) {
          seq.unshift({ x: rxEdge, y: seq[0].y, val: seq[0].val });
        }
      }
      // Extend last measured point to left edge of following blue hole, or to latest elapsed worn slot
      const lastMeas = seq[seq.length - 1];
      if (run.endIdx < n - 1 && gapStartMap[run.endIdx + 1] !== undefined) {
        const lxEdge = gapStartMap[run.endIdx + 1];
        if (lastMeas.x < lxEdge) {
          seq.push({ x: lxEdge, y: lastMeas.y, val: lastMeas.val });
        }
      } else if (lastMeas.x < xCoords[run.endIdx]) {
        seq.push({ x: xCoords[run.endIdx], y: lastMeas.y, val: lastMeas.val });
      }

      if (seq.length > 0) {
        const first = seq[0];
        const last = seq[seq.length - 1];
        pathD += ` M ${first.x.toFixed(1)} ${first.y.toFixed(1)}`;
        let segArea = ` M ${first.x.toFixed(1)} ${(laneObj.y + laneObj.h).toFixed(1)} L ${first.x.toFixed(1)} ${first.y.toFixed(1)}`;
        for (let k = 1; k < seq.length; k++) {
          pathD += ` L ${seq[k].x.toFixed(1)} ${seq[k].y.toFixed(1)}`;
          segArea += ` L ${seq[k].x.toFixed(1)} ${seq[k].y.toFixed(1)}`;
        }
        segArea += ` L ${last.x.toFixed(1)} ${(laneObj.y + laneObj.h).toFixed(1)} Z`;
        areaD += segArea;
      }
    });
    return { pathD, areaD };
  }

  // Lane 1: Glucose Curve (Discontinuous across Charging Gap)
  const gLane = lanes[0];
  const gPts = data.map((d, i) => {
    const val = (d.isChargingGap || d.g === null) ? null : d.g;
    const y = val !== null ? gLane.y + gLane.h - ((val - gLane.minY) / (gLane.maxY - gLane.minY)) * gLane.h : (gLane.y + gLane.h);
    return { x: xCoords[i], y: y, val: val, label: d.time, isGap: d.isChargingGap };
  });
  const gSegments = buildSegmentedPath(gPts, gLane);
  svg += `
    <path d="${gSegments.areaD}" fill="url(#gradTallGlucose)"/>
    <path d="${gSegments.pathD}" fill="none" stroke="#c2410c" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>
  `;

  // Lane 2: Blood Pressure Dual Curves (Sys / Dia) Discontinuous across gaps
  const bpLane = lanes[1];
  const sysPtsList = data.map((d, i) => ({
    x: xCoords[i],
    y: d.sys !== null ? bpLane.y + bpLane.h - ((d.sys - bpLane.minY) / (bpLane.maxY - bpLane.minY)) * bpLane.h : bpLane.y + bpLane.h,
    val: d.sys, isGap: d.isChargingGap
  }));
  const diaPtsList = data.map((d, i) => ({
    x: xCoords[i],
    y: d.dia !== null ? bpLane.y + bpLane.h - ((d.dia - bpLane.minY) / (bpLane.maxY - bpLane.minY)) * bpLane.h : bpLane.y + bpLane.h,
    val: d.dia, isGap: d.isChargingGap
  }));
  const sysSeg = buildSegmentedPath(sysPtsList, bpLane);
  const diaSeg = buildSegmentedPath(diaPtsList, bpLane);
  svg += `
    <path d="${sysSeg.pathD}" fill="none" stroke="#ff9944" stroke-width="2" stroke-linecap="round"/>
    <path d="${diaSeg.pathD}" fill="none" stroke="#38b6ff" stroke-width="2" stroke-linecap="round"/>
  `;

  // Lane 3: Heart Rate & HRV Discontinuous across gaps
  const hrLane = lanes[2];
  const hrPtsList = data.map((d, i) => ({
    x: xCoords[i],
    y: d.hr !== null ? hrLane.y + hrLane.h - ((d.hr - hrLane.minY) / (hrLane.maxY - hrLane.minY)) * hrLane.h : hrLane.y + hrLane.h,
    val: d.hr, isGap: d.isChargingGap
  }));
  const hrvPtsList = data.map((d, i) => ({
    x: xCoords[i],
    y: d.hrv !== null ? hrLane.y + hrLane.h - ((d.hrv - hrLane.minY) / (hrLane.maxY - hrLane.minY)) * hrLane.h : hrLane.y + hrLane.h,
    val: d.hrv, isGap: d.isChargingGap
  }));
  const hrSeg = buildSegmentedPath(hrPtsList, hrLane);
  const hrvSeg = buildSegmentedPath(hrvPtsList, hrLane);
  svg += `
    <path d="${hrSeg.pathD}" fill="none" stroke="#ff5566" stroke-width="2" stroke-linecap="round"/>
    <path d="${hrvSeg.pathD}" fill="none" stroke="var(--lcars-lilac)" stroke-width="1.8" stroke-dasharray="3 2" stroke-linecap="round"/>
  `;

  // Lane 4: SpO2 Curve Discontinuous across gaps (with sample dots)
  const spLane = lanes[3];
  const spPtsList = data.map((d, i) => ({
    x: xCoords[i],
    y: d.spo2 !== null ? spLane.y + spLane.h - ((Math.max(spLane.minY, Math.min(spLane.maxY, d.spo2)) - spLane.minY) / (spLane.maxY - spLane.minY)) * spLane.h : spLane.y + spLane.h,
    val: d.spo2, isGap: d.isChargingGap
  }));
  const spSeg = buildSegmentedPath(spPtsList, spLane);
  svg += `<path d="${spSeg.pathD}" fill="none" stroke="var(--lcars-green)" stroke-width="2.2" stroke-linecap="round"/>`;
  spPtsList.forEach(p => {
    if (!p.isGap && p.val !== null && p.val > 0) {
      svg += `<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="2.8" fill="var(--lcars-green)" stroke="#ffffff" stroke-width="1"/>`;
    }
  });

  // Lane 5: Temperature Curve Discontinuous across gaps (with sample dots)
  const tLane = lanes[4];
  const tPtsList = data.map((d, i) => ({
    x: xCoords[i],
    y: d.temp !== null ? tLane.y + tLane.h - ((Math.max(tLane.minY, Math.min(tLane.maxY, d.temp)) - tLane.minY) / (tLane.maxY - tLane.minY)) * tLane.h : tLane.y + tLane.h,
    val: d.temp, isGap: d.isChargingGap
  }));
  const tSeg = buildSegmentedPath(tPtsList, tLane);
  svg += `<path d="${tSeg.pathD}" fill="none" stroke="var(--lcars-blue)" stroke-width="2.2" stroke-linecap="round"/>`;
  tPtsList.forEach(p => {
    if (!p.isGap && p.val !== null && p.val > 0) {
      svg += `<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="2.8" fill="var(--lcars-blue)" stroke="#ffffff" stroke-width="1"/>`;
    }
  });

  // Lane 6: Kinetic Steps / Exercise Bars & Badges (skip inside blue off-wrist gaps)
  const exLane = lanes[5];
  const maxSteps = Math.max(...data.map(d => d.steps), 4000);
  data.forEach((d, i) => {
    if (d.isChargingGap || d.isFuture) return;
    const barH = (d.steps / maxSteps) * (exLane.h - 20);
    const barY = exLane.y + exLane.h - barH - 4;
    svg += `
      <rect x="${xCoords[i] - 10}" y="${barY.toFixed(1)}" width="20" height="${barH.toFixed(1)}" fill="rgba(255,153,102,0.35)" stroke="var(--lcars-peach)" stroke-width="1" rx="2"/>
    `;
    if (d.ex) {
      svg += `
        <g style="cursor: pointer;" onclick="openTimelinePointCard(${i})">
          <polygon points="${xCoords[i]},${exLane.y + 10} ${xCoords[i] + 8},${exLane.y + 24} ${xCoords[i] - 8},${exLane.y + 24}" fill="#f97316" stroke="#ffffff" stroke-width="1.5"/>
          <text x="${xCoords[i]}" y="${exLane.y + 35}" text-anchor="middle" fill="#9a3412" font-size="8.5" font-weight="900">▲ GLUT4</text>
        </g>
      `;
    }
  });

  // Lane 7: Dietary Intake & Meal Event Indicators (Clean Non-Overlapping Square Markers)
  const dLane = lanes[6];
  data.forEach((d, i) => {
    if (d.meal) {
      const isLowCarb = d.meal.carbs <= 20;
      const markerColor = isLowCarb ? "#15803d" : (d.meal.carbs > 40 ? "#b91c1c" : "#8b5cf6");
      const mType = (d.meal.type || "Meal").toUpperCase();
      const carbs = d.meal.carbs || 0;
      const cals = d.meal.cal || (carbs > 30 ? 490 : 380);

      svg += `
        <g style="cursor: pointer;" onclick="openTimelinePointCard(${i})">
          <!-- Vertical correlation stem -->
          <line x1="${xCoords[i]}" y1="${lanes[0].y + lanes[0].h}" x2="${xCoords[i]}" y2="${dLane.y + dLane.h}" stroke="${markerColor}" stroke-dasharray="3 3" stroke-width="1.5" opacity="0.5"/>

          <!-- Clean Meal Triangle Indicator (▲) -->
          <polygon points="${xCoords[i]},${dLane.y + 12} ${xCoords[i] + 9},${dLane.y + 28} ${xCoords[i] - 9},${dLane.y + 28}" fill="${markerColor}" stroke="#ffffff" stroke-width="1.5"/>
          <text x="${xCoords[i]}" y="${dLane.y + 42}" text-anchor="middle" fill="#0f172a" font-size="8.5" font-weight="800" font-family="var(--lcars-mono)">${carbs}g</text>
        </g>
      `;
    }
  });

  // Lane 8: Medications & Medication Changes
  const mLane = lanes[7];
  data.forEach((d, i) => {
    if (d.med) {
      const isChange = d.med.isMedChange || (d.notes && d.notes.includes("MED CHANGE"));
      if (isChange) {
        // Milestone Line Cutting All the Way Top to Bottom!
        svg += `
          <line x1="${xCoords[i]}" y1="20" x2="${xCoords[i]}" y2="${H - 45}" stroke="#ff5555" stroke-dasharray="4 4" stroke-width="2"/>
          <g style="cursor: pointer;" onclick="openTimelinePointCard(${i})">
            <rect x="${xCoords[i] - 46}" y="${mLane.y + 10}" width="92" height="24" fill="#fef2f2" stroke="#ef4444" stroke-width="1.8" rx="4"/>
            <text x="${xCoords[i]}" y="${mLane.y + 26}" text-anchor="middle" fill="#991b1b" font-size="9" font-weight="900">💊 MED CHANGE</text>
          </g>
        `;
      } else {
        svg += `
          <g style="cursor: pointer;" onclick="openTimelinePointCard(${i})">
            <polygon points="${xCoords[i]},${mLane.y + 42} ${xCoords[i] - 8},${mLane.y + 26} ${xCoords[i] + 8},${mLane.y + 26}" fill="#2563eb" stroke="#ffffff" stroke-width="1.5"/>
            <text x="${xCoords[i]}" y="${mLane.y + 22}" text-anchor="middle" fill="#1e40af" font-size="8.5" font-weight="900">▼ Rx</text>
          </g>
        `;
      }
    }
  });

  // Interactive Clickable Points on Glucose Curve (Only render real data pills, skip gap clutter)
  gPts.forEach((p, i) => {
    if (p.val !== null && !p.isGap && p.val > 0) {
      svg += `
        <g style="cursor: pointer;" onclick="openTimelinePointCard(${i})">
          <circle class="plot-point" cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="6" fill="#ea580c" stroke="#ffffff" stroke-width="2">
            <title>Biometric Function Monitor</title>
          </circle>
          <rect x="${(p.x - 14).toFixed(1)}" y="${(p.y - 21).toFixed(1)}" width="28" height="13" rx="3" fill="#ffffff" stroke="#cbd5e1" stroke-width="1"/>
          <text x="${p.x.toFixed(1)}" y="${(p.y - 11).toFixed(1)}" text-anchor="middle" fill="#78350f" font-size="9" font-weight="900">${p.val}</text>
        </g>
      `;
    }
  });

  // Bottom Shared Time Axis Labels - Evenly Spaced Ticks to Prevent Collision
  let tickStep = 1;
  if (n > 30) tickStep = 6;      // 48 half-hour slots -> tick every 3 hours
  else if (n > 16) tickStep = 4;
  else if (n > 8) tickStep = 2;

  for (let i = 0; i < n; i += tickStep) {
    svg += `
      <text x="${xCoords[i]}" y="${H - 18}" text-anchor="middle" fill="var(--lcars-gray)" font-size="10.5" font-weight="bold">${formatTimeDisplay(data[i].time)}</text>
      <line x1="${xCoords[i]}" y1="${H - 35}" x2="${xCoords[i]}" y2="${H - 28}" stroke="#253549" stroke-width="1.2"/>
    `;
  }
  if ((n - 1) % tickStep !== 0) {
    const lastIdx = n - 1;
    svg += `
      <text x="${xCoords[lastIdx]}" y="${H - 18}" text-anchor="middle" fill="var(--lcars-gray)" font-size="10.5" font-weight="bold">${formatTimeDisplay(data[lastIdx].time)}</text>
      <line x1="${xCoords[lastIdx]}" y1="${H - 35}" x2="${xCoords[lastIdx]}" y2="${H - 28}" stroke="#253549" stroke-width="1.2"/>
    `;
  }

  // THE VERTICAL CONTINUOUS SCRUBBER LINE (Spanning Top to Bottom Across ALL Lanes)
  const initialScrubberX = padLeft + (plotW * 0.5);
  svg += `
    <line id="tallVerticalScrubberLine" x1="${initialScrubberX.toFixed(1)}" y1="20" x2="${initialScrubberX.toFixed(1)}" y2="${H - 35}" stroke="var(--lcars-banana)" stroke-width="2.5" stroke-dasharray="6 3" opacity="0.95" style="pointer-events: none;"/>
    <polygon id="tallScrubberHead" points="${initialScrubberX - 7},16 ${initialScrubberX + 7},16 ${initialScrubberX},23" fill="var(--lcars-banana)" style="pointer-events: none;"/>
  `;

  svg += `</svg>`;
  container.innerHTML = svg;

  // Initialize HUD to latest active telemetry point
  let initIdx = Math.floor(n / 2);
  for (let i = n - 1; i >= 0; i--) {
    if (data[i] && !data[i].isChargingGap && data[i].g !== null && !data[i].isFuture) {
      initIdx = i;
      break;
    }
  }
  const initPct = n > 1 ? (initIdx / (n - 1)) * 100 : 50;
  const sld = document.getElementById('tallScrubberSlider');
  if (sld) sld.value = initPct;
  onTallScrubberMoved(initPct);
}

// Interactive Scrubber Movement Handler
function onTallScrubberMoved(percent) {
  const data = activeTallDataset;
  if (!data || data.length === 0) return;

  const W = 1000;
  const padLeft = 110;
  const padRight = 45;
  const plotW = W - padLeft - padRight;

  const pNorm = Math.max(0, Math.min(100, parseFloat(percent))) / 100;
  const currentX = padLeft + (pNorm * plotW);

  // Move SVG Vertical Scrubber Line
  const scrubber = document.getElementById('tallVerticalScrubberLine');
  const head = document.getElementById('tallScrubberHead');
  if (scrubber) {
    scrubber.setAttribute('x1', currentX.toFixed(1));
    scrubber.setAttribute('x2', currentX.toFixed(1));
  }
  if (head) {
    head.setAttribute('points', `${currentX - 7},16 ${currentX + 7},16 ${currentX},23`);
  }

  // Find Closest Point in Dataset
  const n = data.length;
  const idx = Math.min(n - 1, Math.max(0, Math.round(pNorm * (n - 1))));
  const pt = data[idx];

  // Handle Watch Charging Gap in Scrubber HUD
  const timeBadge = document.getElementById('tallScrubberTimeBadge');
  const hG = document.getElementById('hudGlucose');
  const hBp = document.getElementById('hudBp');
  const hHr = document.getElementById('hudHrHrv');
  const hSp = document.getElementById('hudSpo2');
  const hT = document.getElementById('hudTemp');
  const hEx = document.getElementById('hudExercise');

  if (pt.isChargingGap) {
    if (timeBadge) timeBadge.textContent = `TIMESTAMP: ${formatTimeDisplay(pt.time)} (⚡ WATCH CHARGING ON DOCK • 0 TELEMETRY)`;
    if (hG) hG.textContent = `0 mg/dL (Charging)`;
    if (hBp) hBp.textContent = `-- / -- (Off-Wrist)`;
    if (hHr) hHr.textContent = `0 BPM / 0 ms`;
    if (hSp) hSp.textContent = `-- %`;
    if (hT) hT.textContent = `--.- °F`;
    if (hEx) hEx.textContent = `0 steps • Watch on Charger (~1.2h)`;
  } else {
    if (timeBadge) timeBadge.textContent = `TIMESTAMP: ${formatTimeDisplay(pt.time)} (${pt.meal ? pt.meal.type : (pt.ex ? pt.ex.type : 'Diurnal State')})`;
    if (hG) hG.textContent = (pt.g !== null && pt.g > 0) ? `${pt.g} mg/dL` : `-- mg/dL`;
    if (hBp) hBp.textContent = (pt.sys && pt.sys > 0) ? `${pt.sys}/${pt.dia} mmHg` : `--/-- mmHg`;
    if (hHr) hHr.textContent = (pt.hr && pt.hr > 0) ? `${pt.hr} BPM / ${pt.hrv || '--'} ms` : `-- BPM / -- ms`;
    if (hSp) hSp.textContent = (pt.spo2 && pt.spo2 > 0) ? `${pt.spo2}%` : `-- %`;
    if (hT) hT.textContent = `${pt.temp ? pt.temp.toFixed(1) : '--.-'}°F`;
    if (hEx) {
      hEx.textContent = pt.ex ? `${pt.steps} steps • ${pt.ex.type} (${pt.ex.delta <= 0 ? pt.ex.delta : '+' + pt.ex.delta} mg/dL)` : `${pt.steps} steps • Resting Homeostasis`;
    }
  }

  const hD = document.getElementById('hudDiet');
  if (hD) {
    hD.textContent = pt.meal ? `${pt.meal.type}: ${pt.meal.desc} (${pt.meal.carbs}g carbs)` : "Fasting / In-Between Meals";
  }

  const hM = document.getElementById('hudMeds');
  if (hM) {
    hM.textContent = pt.med ? `${pt.med.name} ${pt.med.isMedChange ? '★ TITRATION MILESTONE' : 'Active'}` : "Standard Regimen Active";
  }
}

function onTallChartMouseMove(evt) {
  const container = document.getElementById('tallChartSvgContainer');
  if (!container) return;
  const rect = container.getBoundingClientRect();
  const relX = evt.clientX - rect.left;
  const padLeft = (110 / 1000) * rect.width;
  const padRight = (45 / 1000) * rect.width;
  const plotW = rect.width - padLeft - padRight;

  if (relX >= padLeft && relX <= padLeft + plotW) {
    const pct = ((relX - padLeft) / plotW) * 100;
    const slider = document.getElementById('tallScrubberSlider');
    if (slider) slider.value = pct;
    onTallScrubberMoved(pct);
  }
}

