"""Capture fresh live screenshots from running BFM server for presentation & docs."""
import asyncio
import base64
import json
import os
import shutil
import struct
import subprocess
import time
import urllib.request

import aiohttp

CHROME_PATH = r"C:\Program Files\Google\Chrome\Application\chrome.exe"
BASE_URL = "http://127.0.0.1:8899"
WORKSPACE = r"D:\veepoo"

OUT_DIRS = [
    os.path.join(WORKSPACE, "presentation", "images"),
    os.path.join(WORKSPACE, "presentation", "slides", "images"),
    os.path.join(WORKSPACE, "slides", "images"),
    os.path.join(WORKSPACE, "images"),
]


class CDPSession:
    def __init__(self, ws):
        self.ws = ws
        self.msg_id = 1

    async def send(self, method, params=None):
        mid = self.msg_id
        self.msg_id += 1
        payload = {"id": mid, "method": method}
        if params:
            payload["params"] = params
        await self.ws.send_json(payload)
        while True:
            raw = await self.ws.receive_json()
            if raw.get("id") == mid:
                if "error" in raw:
                    raise RuntimeError(f"CDP error on {method}: {raw['error']}")
                return raw.get("result", {})

    async def eval_js(self, expr, await_promise=False):
        res = await self.send(
            "Runtime.evaluate",
            {
                "expression": expr,
                "returnByValue": True,
                "awaitPromise": await_promise,
            },
        )
        if "exceptionDetails" in res:
            raise RuntimeError(f"JS exception: {res['exceptionDetails']}")
        return res.get("result", {}).get("value")

    async def capture_png(self, filename, clip=None):
        params = {"format": "png", "fromSurface": True}
        if clip:
            params["clip"] = clip
        res = await self.send("Page.captureScreenshot", params)
        data = base64.b64decode(res["data"])
        if data[:8] != b"\x89PNG\r\n\x1a\n":
            raise ValueError(f"Invalid PNG signature for {filename}")
        w, h = struct.unpack(">II", data[16:24])
        if len(data) < 15000:
            raise ValueError(f"Captured PNG too small ({len(data)} bytes) for {filename}")
        primary_path = os.path.join(OUT_DIRS[0], filename)
        with open(primary_path, "wb") as fp:
            fp.write(data)
        for d in OUT_DIRS[1:]:
            shutil.copy2(primary_path, os.path.join(d, filename))
        print(f"  [OK] {filename:<42} {len(data):>8} bytes  ({w}x{h})")
        return len(data), w, h


async def scroll_element_top(cdp, elem_id):
    return await cdp.eval_js(
        f"""(() => {{
            const el = document.getElementById({json.dumps(elem_id)});
            if (!el) return null;
            el.scrollIntoView({{block: 'start', behavior: 'instant'}});
            window.scrollBy(0, -12);
            const r = el.getBoundingClientRect();
            return {{found: true, top: r.top, h: r.height}};
        }})()"""
    )


async def capture_all():
    # Verify server is reachable before launching browser
    with urllib.request.urlopen(f"{BASE_URL}/api/telemetry/latest", timeout=5) as resp:
        if resp.status != 200:
            raise RuntimeError(f"Server returned status {resp.status}")

    for od in OUT_DIRS:
        os.makedirs(od, exist_ok=True)

    user_data_dir = os.path.join(WORKSPACE, "_chrome_capture_profile")
    os.makedirs(user_data_dir, exist_ok=True)

    proc = subprocess.Popen(
        [
            CHROME_PATH,
            "--headless=new",
            "--remote-debugging-port=9246",
            f"--user-data-dir={user_data_dir}",
            "--disable-gpu",
            "--no-first-run",
            "--no-default-browser-check",
            "--window-size=1600,1050",
            "about:blank",
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    time.sleep(2.5)

    captured = []
    try:
        async with aiohttp.ClientSession() as session:
            ws_url = None
            for _ in range(15):
                try:
                    async with session.get("http://127.0.0.1:9246/json") as resp:
                        targets = await resp.json()
                        page_targets = [t for t in targets if t.get("type") == "page"]
                        if page_targets:
                            ws_url = page_targets[0]["webSocketDebuggerUrl"]
                            break
                except Exception:
                    time.sleep(0.4)
            if not ws_url:
                raise RuntimeError("Could not attach to Chrome DevTools target")

            async with session.ws_connect(ws_url, max_msg_size=64 * 1024 * 1024) as ws:
                cdp = CDPSession(ws)
                await cdp.send("Page.enable")
                await cdp.send("Runtime.enable")
                await cdp.send(
                    "Emulation.setDeviceMetricsOverride",
                    {"width": 1600, "height": 1050, "deviceScaleFactor": 1, "mobile": False},
                )

                # Pre-load BFM console and enforce 12h clock + accepted legal notice in localStorage
                await cdp.send("Page.navigate", {"url": f"{BASE_URL}/index.html"})
                await asyncio.sleep(3.5)

                # Capture Legal Modal first while visible or explicitly opened
                await cdp.eval_js(
                    """(() => {
                        const m = document.getElementById('modalLegalStartup');
                        if (m) m.style.display = 'flex';
                    })()"""
                )
                await asyncio.sleep(0.5)
                captured.append(("bfm_02_legal_startup_modal.png", await cdp.capture_png("bfm_02_legal_startup_modal.png")))

                # Dismiss legal modal, force light theme + 12h clock mode, hydrate live SQLite telemetry
                await cdp.eval_js(
                    """(async () => {
                        localStorage.setItem('bfm_legal_accepted', 'BFM-BETA1-2026');
                        localStorage.setItem('bfm_time_format', '12h');
                        localStorage.setItem('bfm_time_format_user_set', '1');
                        const m = document.getElementById('modalLegalStartup');
                        if (m) m.style.display = 'none';
                        if (typeof timeFormatUserSet !== 'undefined') timeFormatUserSet = true;
                        const sel = document.getElementById('cfgTimeFormat');
                        if (sel) sel.value = '12h';
                        if (typeof applyTheme === 'function') applyTheme('light');
                        if (typeof pollLiveTelemetryChanges === 'function') await pollLiveTelemetryChanges(true);
                        if (typeof fetchServer2DayTimeline === 'function') await fetchServer2DayTimeline();
                        if (typeof fetchTodaySleepSessions === 'function') await fetchTodaySleepSessions();
                        if (typeof fetchTodayLorenzData === 'function') await fetchTodayLorenzData();
                        if (typeof fetchTodaySubReports === 'function') await fetchTodaySubReports();
                        if (typeof loadMealsFromServer === 'function') await loadMealsFromServer();
                        if (typeof initFullScanView === 'function') initFullScanView();
                        return 'HYDRATED';
                    })()""",
                    await_promise=True,
                )
                await asyncio.sleep(2.0)

                # 1. Tab 01 Full Scan hero + legacy alias + header ribbon
                await cdp.eval_js("switchTab('fullscan'); window.scrollTo(0, 0);")
                await asyncio.sleep(1.2)
                captured.append(("bfm_01_hero_fullscan.png", await cdp.capture_png("bfm_01_hero_fullscan.png")))
                shutil.copy2(os.path.join(OUT_DIRS[0], "bfm_01_hero_fullscan.png"), os.path.join(OUT_DIRS[0], "lcars_tab01_fullscan.png"))
                captured.append(
                    (
                        "bfm_03_header_status_ribbon.png",
                        await cdp.capture_png("bfm_03_header_status_ribbon.png", clip={"x": 0, "y": 0, "width": 1600, "height": 240, "scale": 1}),
                    )
                )

                # 2. Tab 02 Meal Planner + Journal/Hydration + Pantry
                await cdp.eval_js("switchTab('diettrades'); window.scrollTo(0, 0);")
                await asyncio.sleep(1.2)
                captured.append(("bfm_04_tab02_meal_planner.png", await cdp.capture_png("bfm_04_tab02_meal_planner.png")))
                shutil.copy2(os.path.join(OUT_DIRS[0], "bfm_04_tab02_meal_planner.png"), os.path.join(OUT_DIRS[0], "lcars_tab02_meal_planner.png"))
                await cdp.eval_js("window.scrollTo(0, 680);")
                await asyncio.sleep(0.5)
                captured.append(("bfm_05_tab02_meal_journal_hydration.png", await cdp.capture_png("bfm_05_tab02_meal_journal_hydration.png")))
                await cdp.eval_js("window.scrollTo(0, 1450);")
                await asyncio.sleep(0.5)
                captured.append(("bfm_06_tab02_pantry_and_trades.png", await cdp.capture_png("bfm_06_tab02_pantry_and_trades.png")))

                # 3. Tab 03 Metabolic & Cardio
                await cdp.eval_js("switchTab('metabolic'); window.scrollTo(0, 0);")
                await asyncio.sleep(1.0)
                captured.append(("bfm_07_tab03_metabolic_console.png", await cdp.capture_png("bfm_07_tab03_metabolic_console.png")))
                await cdp.eval_js("switchTab('cardio'); window.scrollTo(0, 0);")
                await asyncio.sleep(1.0)
                captured.append(("bfm_08_tab03_cardio_vitals.png", await cdp.capture_png("bfm_08_tab03_cardio_vitals.png")))
                shutil.copy2(os.path.join(OUT_DIRS[0], "bfm_08_tab03_cardio_vitals.png"), os.path.join(OUT_DIRS[0], "lcars_tab03_cardio.png"))

                # 4. Tab 04 Reports — full re-render in 12h mode before scrolling each section
                await cdp.eval_js(
                    """(async () => {
                        switchTab('reports');
                        const sel = document.getElementById('cfgTimeFormat');
                        if (sel) sel.value = '12h';
                        if (typeof fetchServer2DayTimeline === 'function') await fetchServer2DayTimeline();
                        if (typeof renderReportsView === 'function') renderReportsView();
                        if (typeof renderTallSynchronizedChart === 'function') renderTallSynchronizedChart();
                        if (typeof init3DMultiChannelViewer === 'function') init3DMultiChannelViewer();
                        if (typeof render3DMultiChannelScene === 'function') render3DMultiChannelScene();
                        if (typeof renderLorenzScatterPlot === 'function') renderLorenzScatterPlot();
                        if (typeof renderSubReportTrendCharts === 'function') renderSubReportTrendCharts();
                        if (typeof loadGoalsComplianceReport === 'function') loadGoalsComplianceReport();
                        window.scrollTo(0, 0);
                        return 'REPORTS_READY';
                    })()""",
                    await_promise=True,
                )
                await asyncio.sleep(1.8)

                await scroll_element_top(cdp, "box3DMultiChannelViewer")
                await asyncio.sleep(0.8)
                captured.append(("bfm_09_tab04_3d_multichannel.png", await cdp.capture_png("bfm_09_tab04_3d_multichannel.png")))
                shutil.copy2(os.path.join(OUT_DIRS[0], "bfm_09_tab04_3d_multichannel.png"), os.path.join(OUT_DIRS[0], "lcars_tab04_reports.png"))

                await scroll_element_top(cdp, "boxSynchronizedTallChart")
                await asyncio.sleep(0.7)
                captured.append(("bfm_10_tab04_13lane_tall_chart.png", await cdp.capture_png("bfm_10_tab04_13lane_tall_chart.png")))

                # Simulate scrubber move to highlight interactive Point HUD
                await cdp.eval_js(
                    """(() => {
                        const sl = document.getElementById('tallScrubberSlider');
                        if (sl && typeof onTallScrubberMoved === 'function') {
                            sl.value = 34;
                            onTallScrubberMoved(34);
                        }
                    })()"""
                )
                await asyncio.sleep(0.5)
                captured.append(("bfm_11_tab04_tall_chart_scrubber.png", await cdp.capture_png("bfm_11_tab04_tall_chart_scrubber.png")))

                report_sections = [
                    ("boxGoalsComplianceReport", "bfm_12_tab04_goals_compliance.png"),
                    ("boxExerciseMetabolicCorrelation", "bfm_13_tab04_step_glut4_correlator.png"),
                    ("boxSubEcgStress", "bfm_14_tab04_subreport_ecg_stress.png"),
                    ("boxSubBloodComp", "bfm_15_tab04_subreport_blood_body_breath.png"),
                    ("boxChartGlucose", "bfm_16_tab04_glucose_a1c_curves.png"),
                    ("boxChartTemp", "bfm_17_tab04_temp_0x88_curve.png"),
                    ("boxChartHR", "bfm_18_tab04_hr_bp_spo2_curves.png"),
                    ("boxChartFluidWater", "bfm_19_tab04_hydration_80oz.png"),
                    ("boxChartHRV", "bfm_20_tab04_hrv_lorenz_8859.png"),
                    ("boxChartSleep", "bfm_21_tab04_sleep_0xe0_hypnogram.png"),
                    ("boxChartExercise", "bfm_22_tab04_steps_0x07_2000goal.png"),
                    ("boxYtdSummary", "bfm_23_tab04_raw_telemetry_ytd.png"),
                ]
                for elem_id, fname in report_sections:
                    await scroll_element_top(cdp, elem_id)
                    await asyncio.sleep(0.6)
                    captured.append((fname, await cdp.capture_png(fname)))

                # 5. Remaining Workspace Tabs (05..14)
                tab_captures = [
                    ("learning", "bfm_24_tab05_learning_coach.png", "lcars_tab06_learning.png"),
                    ("operations", "bfm_25_tab06_operations_hardware.png", "lcars_tab11_operations.png"),
                    ("goals", "bfm_26_tab08_goals.png", "lcars_tab09_goals.png"),
                    ("medication", "bfm_27_tab09_medication.png", "lcars_tab08_medication.png"),
                    ("setup", "bfm_28_tab10_config_triad_roster.png", "lcars_tab10_config.png"),
                    ("watchfaces", "bfm_29_tab11_watch_5010_boundary.png", "lcars_tab13_watchfaces.png"),
                    ("log", "bfm_30_tab12_datalog_console.png", "lcars_tab12_datalog.png"),
                    ("export", "bfm_31_tab13_export_usb_fhir.png", "lcars_tab05_export.png"),
                    ("troubleshooting", "bfm_32_tab14_troubleshooting.png", None),
                    ("help", "bfm_34_tab07_faq_help.png", "lcars_tab07_help.png"),
                ]
                for tab_id, fname, legacy_alias in tab_captures:
                    await cdp.eval_js(f"switchTab('{tab_id}'); window.scrollTo(0, 0);")
                    if tab_id == "setup":
                        await cdp.eval_js("window.scrollTo(0, 420);")
                    await asyncio.sleep(0.9)
                    captured.append((fname, await cdp.capture_png(fname)))
                    if legacy_alias:
                        src_p = os.path.join(OUT_DIRS[0], fname)
                        shutil.copy2(src_p, os.path.join(OUT_DIRS[0], legacy_alias))
                        for d in OUT_DIRS[1:]:
                            shutil.copy2(src_p, os.path.join(d, legacy_alias))

                # 6. Mobile companion cell.html (#33)
                await cdp.send(
                    "Emulation.setDeviceMetricsOverride",
                    {"width": 520, "height": 960, "deviceScaleFactor": 2, "mobile": True},
                )
                await cdp.send("Page.navigate", {"url": f"{BASE_URL}/cell.html"})
                await asyncio.sleep(2.0)
                captured.append(("bfm_33_mobile_cell_pwa.png", await cdp.capture_png("bfm_33_mobile_cell_pwa.png")))

    finally:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            proc.kill()
        if os.path.exists(user_data_dir):
            shutil.rmtree(user_data_dir, ignore_errors=True)

    print(f"\n[DONE] Captured and replicated {len(captured)} fresh live PNG screenshots across {len(OUT_DIRS)} directories.")


if __name__ == "__main__":
    asyncio.run(capture_all())

