"""Capture 36 seamless live Auto-Fly animation frames of #box3DMultiChannelViewer via Chrome CDP."""
import asyncio
import base64
import hashlib
import os
import shutil
import subprocess
import time
import urllib.request

import aiohttp

CHROME_PATH = r"C:\Program Files\Google\Chrome\Application\chrome.exe"
BASE_URL = "http://127.0.0.1:8899"
WORKSPACE = r"D:\veepoo"

FLY_DIRS = [
    os.path.join(WORKSPACE, "presentation", "images", "fly3d"),
    os.path.join(WORKSPACE, "presentation", "slides", "images", "fly3d"),
    os.path.join(WORKSPACE, "slides", "images", "fly3d"),
    os.path.join(WORKSPACE, "images", "fly3d"),
]


async def capture_flythrough():
    with urllib.request.urlopen(f"{BASE_URL}/api/telemetry/latest", timeout=5) as resp:
        if resp.status != 200:
            raise RuntimeError(f"Server returned {resp.status}")

    for d in FLY_DIRS:
        os.makedirs(d, exist_ok=True)

    ud = os.path.join(WORKSPACE, "_chrome_fly3d")
    os.makedirs(ud, exist_ok=True)
    proc = subprocess.Popen(
        [
            CHROME_PATH,
            "--headless=new",
            "--remote-debugging-port=9250",
            f"--user-data-dir={ud}",
            "--disable-gpu",
            "--no-first-run",
            "--window-size=1600,1050",
            "about:blank",
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    time.sleep(2.4)

    hashes = set()
    try:
        async with aiohttp.ClientSession() as session:
            ws_url = None
            for _ in range(15):
                try:
                    async with session.get("http://127.0.0.1:9250/json") as r:
                        pages = [t for t in await r.json() if t.get("type") == "page"]
                        if pages:
                            ws_url = pages[0]["webSocketDebuggerUrl"]
                            break
                except Exception:
                    time.sleep(0.3)
            if not ws_url:
                raise RuntimeError("Could not attach CDP session")

            async with session.ws_connect(ws_url, max_msg_size=64 * 1024 * 1024) as ws:
                mid = 0

                async def send(m, p=None):
                    nonlocal mid
                    mid += 1
                    await ws.send_json({"id": mid, "method": m, **({"params": p} if p else {})})
                    while True:
                        raw = await ws.receive_json()
                        if raw.get("id") == mid:
                            return raw.get("result", {})

                async def eval_js(expr, await_promise=False):
                    r = await send("Runtime.evaluate", {"expression": expr, "returnByValue": True, "awaitPromise": await_promise})
                    if "exceptionDetails" in r:
                        raise RuntimeError(f"JS error: {r['exceptionDetails']}")
                    return r.get("result", {}).get("value")

                await send("Page.enable")
                await send("Runtime.enable")
                await send(
                    "Emulation.setDeviceMetricsOverride",
                    {"width": 1600, "height": 1050, "deviceScaleFactor": 1, "mobile": False},
                )
                await send("Page.navigate", {"url": f"{BASE_URL}/index.html"})
                await asyncio.sleep(3.2)

                # Hydrate live data, switch to 04-REPORTS in 12h light mode, and frame #box3DMultiChannelViewer
                rect = await eval_js(
                    """(async () => {
                        localStorage.setItem('bfm_legal_accepted', 'BFM-BETA1-2026');
                        localStorage.setItem('bfm_time_format', '12h');
                        localStorage.setItem('bfm_time_format_user_set', '1');
                        const m = document.getElementById('modalLegalStartup');
                        if (m) m.style.display = 'none';
                        if (typeof applyTheme === 'function') applyTheme('light');
                        const sel = document.getElementById('cfgTimeFormat');
                        if (sel) sel.value = '12h';
                        if (typeof pollLiveTelemetryChanges === 'function') await pollLiveTelemetryChanges(true);
                        if (typeof fetchServer2DayTimeline === 'function') await fetchServer2DayTimeline();
                        if (typeof fetchTodaySleepSessions === 'function') await fetchTodaySleepSessions();
                        switchTab('reports');
                        if (typeof init3DMultiChannelViewer === 'function') init3DMultiChannelViewer();
                        const el = document.getElementById('box3DMultiChannelViewer');
                        if (!el) throw new Error('Missing #box3DMultiChannelViewer');
                        el.scrollIntoView({block: 'start', behavior: 'instant'});
                        const ws = document.querySelector('.lcars-workspace');
                        if (ws) ws.scrollTop -= 8;
                        const r = el.getBoundingClientRect();
                        return {x: Math.max(0, Math.floor(r.left)), y: Math.max(0, Math.floor(r.top)), width: Math.floor(r.width), height: Math.min(760, Math.floor(r.height))};
                    })()""",
                    await_promise=True,
                )
                await asyncio.sleep(0.8)

                clip = {"x": rect["x"], "y": rect["y"], "width": rect["width"], "height": rect["height"], "scale": 1}
                print(f"Capturing 36 smooth Auto-Fly frames in clip={clip}...")

                for i in range(36):
                    # Smooth 2*pi orbital camera sweep + fly-in zoom curve
                    await eval_js(
                        f"""(() => {{
                            const th = (2 * Math.PI * {i}) / 36;
                            cam3D.autoFly = false;
                            cam3D.yaw = -0.55 + Math.sin(th) * 0.34;
                            cam3D.pitch = 0.36 + Math.cos(th) * 0.09;
                            cam3D.panX = Math.sin(th) * 95;
                            cam3D.panY = -36 + Math.cos(th * 2) * 14;
                            cam3D.distance = 840 - Math.sin(th) * 140;
                            const btn = document.getElementById('btnAutoFly');
                            if (btn) btn.textContent = '▶ AUTO FLY (ACTIVE SEQUENCE)';
                            render3DMultiChannelScene();
                        }})()"""
                    )
                    await asyncio.sleep(0.08)
                    shot = await send("Page.captureScreenshot", {"format": "jpeg", "quality": 88, "fromSurface": True, "clip": clip})
                    raw = base64.b64decode(shot["data"])
                    if len(raw) <= 15000:
                        raise RuntimeError(f"Frame {i} unexpectedly small: {len(raw)} bytes")
                    hashes.add(hashlib.sha256(raw).hexdigest())
                    fname = f"bfm_3d_fly_{i:02d}.jpg"
                    for d in FLY_DIRS:
                        with open(os.path.join(d, fname), "wb") as fp:
                            fp.write(raw)
                print(f"[OK] Captured 36 3D fly-through frames ({len(hashes)} unique hashes) across 4 fly3d/ folders.")
                if len(hashes) < 30:
                    raise RuntimeError(f"Expected distinct animated frames, got only {len(hashes)} unique hashes")
    finally:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            proc.kill()
        shutil.rmtree(ud, ignore_errors=True)


if __name__ == "__main__":
    asyncio.run(capture_flythrough())

