args.Content:
"""Exhaustive audit of 83 consolidated clinician/user slides: monotonic Tab 01-14 ordering, Slide 02 90-day SVG, Slide 21 36-frame 3D fly-through, zero programmer jargon, PNG/JPG/MP3 integrity, ASTs, and live clinical truth."""
import json
import os
import re
import sqlite3
import struct
import subprocess

WORKSPACE = r"D:\veepoo"
PRES_DIR = os.path.join(WORKSPACE, "presentation")
PRES_SLIDES_DIR = os.path.join(PRES_DIR, "slides")
ROOT_SLIDES_DIR = os.path.join(WORKSPACE, "slides")
AUDIO_DIR = os.path.join(PRES_DIR, "audio")
SLIDES_AUDIO_DIR = os.path.join(ROOT_SLIDES_DIR, "audio")
IMG_DIRS = [
    os.path.join(PRES_DIR, "images"),
    os.path.join(PRES_SLIDES_DIR, "images"),
    os.path.join(ROOT_SLIDES_DIR, "images"),
    os.path.join(WORKSPACE, "images"),
]

JARGON_TOKENS = [
    "CLE-",
    "0xDF",
    "0x88",
    "0xE0",
    "0xB8",
    "0xA3",
    "0x07",
    "0x99",
    "0x89",
    "0x1A",
    "div balance",
    "window.fetch",
    "server.py",
    "El-CARS",
    "Neye-quist",
    "images/lcars_",
]


def verify_png_valid(fpath):
    """Validate PNG magic header, dimensions, and size > 15 KB."""
    with open(fpath, "rb") as fp:
        data = fp.read()
    if len(data) <= 15000:
        return False, f"PNG too small ({len(data)} bytes)"
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        return False, "Invalid PNG magic header"
    w, h = struct.unpack(">II", data[16:24])
    if w < 900 or h < 200:
        return False, f"Unexpected PNG dims {w}x{h}"
    return True, (len(data), w, h)


def verify_jpg_valid(fpath):
    """Validate JPEG SOI header and size > 15 KB."""
    with open(fpath, "rb") as fp:
        data = fp.read()
    if len(data) <= 15000:
        return False, f"JPEG too small ({len(data)} bytes)"
    if data[:3] != b"\xff\xd8\xff":
        return False, "Invalid JPEG SOI header"
    return True, len(data)


def run_audit():
    defects = []

    cov_path = os.path.join(WORKSPACE, "Beta", "docs", "presentation_build_coverage_audit.json")
    if not os.path.exists(cov_path):
        raise FileNotFoundError(f"Missing coverage audit JSON: {cov_path}")
    with open(cov_path, "r", encoding="utf-8") as fp:
        cov = json.load(fp)

    total = len(cov)
    print(f"=== PRESENTATION FULL AUDIT ({total} SLIDES) ===")
    if total != 83:
        defects.append(f"Expected 83 consolidated slides, found {total}")

    # 1. Verify BFM.HTM sidebar tab order matches 01-FULL SCAN -> 02-METABOLIC -> 03-MEAL PLANNER -> 04-REPORTS .. 14
    with open(os.path.join(WORKSPACE, "BFM.HTM"), "r", encoding="utf-8") as fp:
        bfm_src = fp.read()
    nav_labels = re.findall(
        r'<button[^>]*onclick="switchTab\(\'[^\']+\'\)"[^>]*>\s*<span class="tab-label">([^<]+)</span>',
        bfm_src,
    )
    expected_prefix = [
        "01-FULL SCAN",
        "02-METABOLIC",
        "03-MEAL PLANNER",
        "04-REPORTS",
        "05-LEARNING",
        "06-OPERATIONS",
        "07-FAQ",
        "08-CLINICAL GOALS",
        "09-MEDICATION",
        "10-CONFIG",
        "11-WATCH",
        "12-DATA LOG",
        "13-EXPORT",
        "14-TROUBLESHOOTING",
    ]
    if nav_labels[:14] != expected_prefix:
        defects.append(f"BFM.HTM sidebar order mismatch: {nav_labels[:14]} != {expected_prefix}")
    else:
        print("[PASS] BFM.HTM sidebar order verified: 01-FULL SCAN -> 02-METABOLIC -> 03-MEAL PLANNER -> 04..14")

    # 2. Enforce strict monotonic Tab 01..14 ordering + Screenshot-to-Tab Affinity across slides
    last_tab = 0
    saw_tabs = []
    for entry in cov:
        snum = int(entry["slide_num"])
        mod = entry["module"]
        img_rel = entry["tab_screenshot"]
        img_base = os.path.basename(img_rel)
        m_tab = re.match(r"Tab\s+(\d+):", mod)
        if m_tab:
            t_num = int(m_tab.group(1))
            if t_num < last_tab:
                defects.append(f"Slide {entry['slide_num']}: Out-of-order tab {t_num} after Tab {last_tab} ({mod})")
            last_tab = t_num
            saw_tabs.append(t_num)
            if t_num == 4 and "fly3d/" in img_rel:
                if img_base != "bfm_3d_fly_00.jpg":
                    defects.append(f"Slide {entry['slide_num']}: Unexpected 3D fly frame '{img_rel}'")
            else:
                expected_img_prefix = f"bfm_t{t_num:02d}_"
                if not img_base.startswith(expected_img_prefix):
                    defects.append(
                        f"Slide {entry['slide_num']} ({mod}): Screenshot '{img_base}' does not match Tab {t_num:02d} ('{expected_img_prefix}*')"
                    )
        elif mod.startswith("Mobile Companion"):
            if last_tab != 14:
                defects.append(f"Slide {entry['slide_num']}: Mobile Companion before Tab 14 completed (last_tab={last_tab})")
            if img_base != "bfm_t15_mobile_cell.png":
                defects.append(f"Slide {entry['slide_num']}: Mobile slide uses '{img_base}' instead of 'bfm_t15_mobile_cell.png'")

    if set(saw_tabs) != set(range(1, 15)):
        defects.append(f"Missing tabs in deck! Saw: {sorted(set(saw_tabs))}")
    else:
        print("[PASS] Strict monotonic Tab 01 -> 14 sequence & 100% screenshot-to-tab affinity verified")

    # 3. Verify zero orphan slide HTML or MP3 files (84+)
    orphans = []
    for d in (PRES_DIR, PRES_SLIDES_DIR, ROOT_SLIDES_DIR, AUDIO_DIR, SLIDES_AUDIO_DIR):
        if os.path.isdir(d):
            for fn in os.listdir(d):
                m_s = re.match(r"slide_(\d+)\.(html|mp3)$", fn)
                if m_s and int(m_s.group(1)) > total:
                    orphans.append(os.path.join(d, fn))
    if orphans:
        defects.append(f"Orphan slide/audio files > {total} found: {orphans[:10]}")
    else:
        print(f"[PASS] Zero orphan slide HTML or MP3 files above {total}")

    # 4. Verify preview.html embeds exact matching slides list, 0 empty catches & passes Node AST check
    prev_path = os.path.join(PRES_DIR, "preview.html")
    with open(prev_path, "r", encoding="utf-8") as fp:
        prev_html = fp.read()

    m = re.search(r"<script>(.*)</script>", prev_html, re.S)
    if not m:
        defects.append("preview.html: Missing inline <script> block")
        js_code = ""
    else:
        js_code = m.group(1)
        if re.search(r"catch\s*\([^)]*\)\s*\{\s*\}", js_code):
            defects.append("preview.html: Contains empty catch(e) {} block (PD-8 violation)")
        tmp_js = os.path.join(WORKSPACE, "_tmp_preview_ast.js")
        with open(tmp_js, "w", encoding="utf-8") as fp:
            fp.write(js_code)
        try:
            res = subprocess.run(["node", "--check", tmp_js], capture_output=True, text=True)
            if res.returncode != 0:
                defects.append(f"preview.html JS AST failed: {res.stderr.strip()}")
            else:
                print("[PASS] preview.html inline JS AST compiled cleanly via Node --check (0 empty catch blocks)")
        finally:
            if os.path.exists(tmp_js):
                os.remove(tmp_js)

    raw_arr = prev_html[prev_html.find("const slides = ") + len("const slides = ") :]
    end_idx = raw_arr.find("];\n")
    slides_data = json.loads(raw_arr[: end_idx + 1])
    if len(slides_data) != total:
        defects.append(f"preview.html slides count {len(slides_data)} != coverage JSON {total}")
    else:
        print(f"[PASS] preview.html contains {len(slides_data)} slides matching coverage JSON")

    # 5. Audit 36-frame animated 3D fly-through assets across all 4 fly3d folders
    fly3d_checked = 0
    for idir in IMG_DIRS:
        fdir = os.path.join(idir, "fly3d")
        for frame_idx in range(36):
            fp_jpg = os.path.join(fdir, f"bfm_3d_fly_{frame_idx:02d}.jpg")
            if not os.path.exists(fp_jpg):
                defects.append(f"Missing 3D fly frame: {fp_jpg}")
            else:
