  clearTimeout(slideTimer);

  const audioEl = document.getElementById('audioPlayer');
  if (audioEl) {
    try { audioEl.pause(); } catch(e) { console.warn('[MIL-SPEC HANDLED FAULT]', e); }
  }
  if (!isPlaying || !audioEl) return;

  const s = slides[currentIndex];
  const nextSrc = `audio/slide_${s.num}.mp3`;
  audioEl.onended = () => {
    if (myToken !== audioPlayToken || !isPlaying) return;
    slideTimer = setTimeout(() => {
      if (myToken === audioPlayToken && isPlaying) nextSlide();
    }, 1200);
  };
  audioEl.onerror = (ev) => {
    if (myToken !== audioPlayToken || !isPlaying) return;
    console.warn('[MIL-SPEC HANDLED FAULT] Audio element load error for', nextSrc, ev);
  };

  audioEl.src = nextSrc;
  audioEl.playbackRate = playbackSpeed;
  audioEl.volume = 1.0;
  audioEl.muted = false;
  audioEl.load();

  const attemptPlay = (retriesLeft) => {
    if (myToken !== audioPlayToken || !isPlaying) return;
    const p = audioEl.play();
    if (p !== undefined) {
      p.catch((err) => {
        if (myToken !== audioPlayToken || !isPlaying) return;
        if (err && err.name === 'AbortError') return;
        console.warn('[MIL-SPEC HANDLED FAULT] Aussie MP3 play error:', err);
        if (err && err.name === 'NotAllowedError') {
          isPlaying = false;
          const btn = document.getElementById('btnPlayPause');
          if (btn) { btn.innerHTML = '▶ RUN'; btn.classList.remove('active'); }
          return;
        }
        if (retriesLeft > 0) {
          setTimeout(() => attemptPlay(retriesLeft - 1), 250);
        }
      });
    }
  };
  attemptPlay(1);
}

