function getTodayOffWristIntervals() {
  const raw = [];
  if (cached2DayTimeline && Array.isArray(cached2DayTimeline)) {
    const todayPts = cached2DayTimeline.filter(d => d.day === 'TODAY' && !d.isFuture && d.time && /^\d{2}:\d{2}/.test(d.time));
    let curStartMin = null;
    let curEndMin = null;
    todayPts.forEach(d => {
      const hh = parseInt(d.time.substring(0, 2), 10);
      const mm = parseInt(d.time.substring(3, 5), 10);
      const mVal = hh * 60 + mm;
      if (d.isChargingGap) {
        if (curStartMin === null) curStartMin = mVal;
        curEndMin = mVal;
      } else if (curStartMin !== null) {
        raw.push({ startMin: Math.max(0, curStartMin - 15), endMin: Math.min(1440, curEndMin + 15) });
        curStartMin = null;
        curEndMin = null;
      }
    });
    if (curStartMin !== null) {
      raw.push({ startMin: Math.max(0, curStartMin - 15), endMin: Math.min(1440, curEndMin + 15) });
    }
  }
  if (window.lastSubReportData && Array.isArray(window.lastSubReportData.OFF_WRIST_INTERVALS)) {
    window.lastSubReportData.OFF_WRIST_INTERVALS.forEach(g => {
      if (g && typeof g.startMin === 'number' && typeof g.endMin === 'number' && g.endMin > g.startMin) {
        raw.push({
          startMin: Math.max(0, g.startMin),
          endMin: Math.min(1440, g.endMin),
          start: g.start || '',
          end: g.end || ''
        });
      }
    });
  }
  if (raw.length === 0) return [];
  raw.sort((a, b) => a.startMin - b.startMin);
  const merged = [Object.assign({}, raw[0])];
  for (let i = 1; i < raw.length; i++) {
    const prev = merged[merged.length - 1];
    const cur = raw[i];
    if (cur.startMin <= prev.endMin) {
      prev.endMin = Math.max(prev.endMin, cur.endMin);
      if (cur.end) prev.end = cur.end;
    } else {
      merged.push(Object.assign({}, cur));
    }
  }
  return merged;
}

