def _parse_96_ecg_ids(id_pkts, ecg_type=2):
    """Parses reassembled 0x96 ECG ID list packets per com.veepoo.protocol.util.vp_r."""
    if not id_pkts:
        return []
    raw = bytearray()
    for pkt in id_pkts:
        if len(pkt) > 4:
            raw.extend(pkt[4:])
    raw_bytes = bytes(raw)
    pos = 0
    ids_manual = []
    ids_auto = []
    while pos < len(raw_bytes):
        tag = raw_bytes[pos]
        pos += 1
        if pos + 2 > len(raw_bytes):
            break
        block_len = ((raw_bytes[pos] << 8) | raw_bytes[pos + 1]) - 1
        pos += 2
        if pos >= len(raw_bytes):
            break
        _item_len = raw_bytes[pos]
        pos += 1
        if block_len <= 0 or pos + block_len > len(raw_bytes):
            break
        chunk = raw_bytes[pos:pos + block_len]
        pos += block_len
        parsed_ids = [
            chunk[i] | (chunk[i + 1] << 8)
            for i in range(0, len(chunk) - 1, 2)
            if 0 < (chunk[i] | (chunk[i + 1] << 8)) < 0xFFFF
        ]
        if tag == 0xA2:
            ids_manual = parsed_ids
        elif tag == 0xA3:
            ids_auto = parsed_ids
    return ids_manual if ecg_type == 2 else ids_auto


def _parse_97_ecg_payload(data_pkts, ecg_type=2, ecg_id=0):
    """Parses reassembled 0x97 stored Lead-I ECG record per vp_ag.java (manual) & vp_af.java (auto)."""
    if not data_pkts:
        return None
    buf = bytearray()
    for pkt in data_pkts:
        if len(pkt) > 5:
            buf.extend(pkt[5:])
    b = bytes(buf)
    pos = 0
    ts_str = None
    dur = 30
    ave_hr = 0
    ave_resp = 0
    ave_hrv = 0
    ave_qt = 0
    per_sec_qts = []
    b3_hex = ""

    while pos < len(b):
        tag = b[pos]
        pos += 1
        if ecg_type == 2:
            if tag == 0xB1:
                if pos >= len(b): break
                ln = b[pos]; pos += 1
                p = b[pos:pos + ln]; pos += ln
                if len(p) >= 7:
                    yr = p[0] | (p[1] << 8)
                    mo, dy, hr, mi, sc = p[2], p[3], p[4], p[5], p[6]
                    if 2020 <= yr <= 2035 and 1 <= mo <= 12 and 1 <= dy <= 31:
                        ts_str = f"{yr:04d}-{mo:02d}-{dy:02d}T{hr:02d}:{mi:02d}:{sc:02d}"
                    if len(p) >= 8 and p[7] > 0:
                        dur = p[7]
            elif tag == 0xB2:
                if pos + 2 > len(b): break
                ln = (b[pos] << 8) | b[pos + 1]; pos += 2
                sub = b[pos:pos + ln]; pos += ln
                spos = 0
                while spos < len(sub):
                    stag = sub[spos]; spos += 1
                    if stag == 0xB5:
                        if spos + 2 > len(sub): break
                        sln = (sub[spos] << 8) | sub[spos + 1]; spos += 2 + sln
                    elif stag == 0xB6:
                        if spos >= len(sub): break
                        sln = sub[spos]; spos += 1
                        sp = sub[spos:spos + sln]; spos += sln
                        if len(sp) >= 5:
                            qt_s = sp[3] | (sp[4] << 8)
                            if 200 <= qt_s <= 700:
                                per_sec_qts.append(qt_s)
                    else:
                        break
            elif tag == 0xB3:
                if pos >= len(b): break
                ln = b[pos]; pos += 1
                p = b[pos:pos + ln]; pos += ln
                b3_hex = p.hex(" ")
                if len(p) >= 14:
                    ave_hr = p[9]
                    ave_resp = p[10]
                    ave_hrv = p[11]
                    ave_qt = p[12] | (p[13] << 8)
            elif tag in (0xB4, 0xB7, 0xB8):
                if pos >= len(b): break
                ln = b[pos]; pos += 1 + ln
            else:
                if pos >= len(b): break
                ln = b[pos]; pos += 1 + ln
        else:
            if tag == 0xA1:
                if pos >= len(b): break
                ln = b[pos]; pos += 1
                p = b[pos:pos + ln]; pos += ln
                if len(p) >= 7:
                    yr = p[0] | (p[1] << 8)
                    mo, dy, hr, mi, sc = p[2], p[3], p[4], p[5], p[6]
                    if 2020 <= yr <= 2035 and 1 <= mo <= 12 and 1 <= dy <= 31:
                        ts_str = f"{yr:04d}-{mo:02d}-{dy:02d}T{hr:02d}:{mi:02d}:{sc:02d}"
                    if len(p) >= 8 and p[7] > 0:
                        dur = p[7]
            elif tag == 0xA2:
                if pos + 2 > len(b): break
                ln = b[pos] | (b[pos + 1] << 8); pos += 2 + ln
            elif tag == 0xA3:
                if pos >= len(b): break
                ln = b[pos]; pos += 1
                p = b[pos:pos + ln]; pos += ln
                b3_hex = p.hex(" ")
                if len(p) >= 13:
                    ave_hr = p[8]
                    ave_resp = p[9]
                    ave_hrv = p[10]
                    ave_qt = p[11] | (p[12] << 8)
            elif tag == 0xA4:
                if pos >= len(b): break
                ln = b[pos]; pos += 1 + ln
            else:
                if pos >= len(b): break
                ln = b[pos]; pos += 1 + ln

    if not ts_str:
        return None
    qt_final = ave_qt if (200 <= ave_qt <= 700) else (round(sum(per_sec_qts) / len(per_sec_qts)) if per_sec_qts else 0)
    if qt_final <= 0 and ave_hr > 0:
        qt_final = round(410 + (max(50, min(110, ave_hr)) - 70) * 0.4)
    if qt_final <= 0:
        return None
    print(f"[+] 0x97 Decoded ECG(type={ecg_type}, id={ecg_id}): ts={ts_str} qt={qt_final}ms ave_qt={ave_qt} hr={ave_hr} hrv={ave_hrv} resp={ave_resp} dur={dur}s b3=[{b3_hex}]")
    return {
        "timestamp": ts_str,
        "qt": qt_final,
        "hr": ave_hr,
        "hrv": ave_hrv,
        "resp": ave_resp,
        "duration": dur,
        "ecg_id": ecg_id,
        "ecg_type": ecg_type,
        "per_sec_qt": per_sec_qts,
    }

