"""Capture targeted live BFM.HTM screenshots for beta.00.01.0062 across all 4 image dirs."""
import asyncio
import json
import os
import shutil
import subprocess
import sys
import time
import urllib.request

import aiohttp

sys.path.insert(0, r"D:\veepoo\tools")
from capture_beta56_screenshots import (
    BASE_URL,
    CHROME_PATH,
    OUT_DIRS,
    WORKSPACE,
    CDPSession,
    scroll_workspace_to,
    switch_tab_top,
)


async def capture_targeted():
    with urllib.request.urlopen(f"{BASE_URL}/api/subreports/today", timeout=5) as resp:
        sub_json = json.loads(resp.read().decode("utf-8"))
    print("[API /api/subreports/today summary]:")
    for k in ("ecg_count", "met_count", "blood_count", "bcomp_count", "breath_count"):
        print(f"  {k}: {sub_json.get(k)}")
    print("  ecg_latest:", json.dumps(sub_json.get("ecg_latest")))
    print("  body_comp_latest:", json.dumps(sub_json.get("body_comp_latest")))
    if sub_json.get("met_5min"):
        print("  met_5min[-2:]:", json.dumps(sub_json["met_5min"][-2:]))
    if sub_json.get("blood_comp"):
        print("  blood_comp[-2:]:", json.dumps(sub_json["blood_comp"][-2:]))
    if sub_json.get("breath_rate"):
        print("  breath_rate[-2:]:", json.dumps(sub_json["breath_rate"][-2:]))

    user_data_dir = os.path.join(WORKSPACE, "_chrome_capture_b62")
    os.makedirs(user_data_dir, exist_ok=True)
    proc = subprocess.Popen(
        [
            CHROME_PATH,
            "--headless=new",
            "--remote-debugging-port=9249",
            f"--user-data-dir={user_data_dir}",
            "--disable-gpu",
            "--no-first-run",
            "--no-default-browser-check",
            "--window-size=1600,1050",
            "about:blank",
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    time.sleep(2.5)

    try:
        async with aiohttp.ClientSession() as session:
            ws_url = None
            for _ in range(15):
                try:
                    async with session.get("http://127.0.0.1:9249/json") as resp:
                        targets = await resp.json()
                        pages = [t for t in targets if t.get("type") == "page"]
                        if pages:
                            ws_url = pages[0]["webSocketDebuggerUrl"]
                            break
                except Exception:
                    await asyncio.sleep(0.4)
            if not ws_url:
                raise RuntimeError("Chrome CDP websocket did not appear on 9249")

            async with session.ws_connect(ws_url, max_msg_size=50 * 1024 * 1024) as ws:
                cdp = CDPSession(ws)
                await cdp.send("Page.enable")
                await cdp.send("Runtime.enable")
                await cdp.send("Page.navigate", {"url": f"{BASE_URL}/"})
                await asyncio.sleep(3.5)

                # Load reports & daily timelines cleanly
                info = await cdp.eval_js(
                    """(async () => {
                        switchTab('reports');
                        const sel = document.getElementById('cfgTimeFormat');
                        if (sel) sel.value = '12h';
                        if (typeof fetchServer2DayTimeline === 'function') await fetchServer2DayTimeline();
                        if (typeof updateWatchMetabolicSubReports === 'function') await updateWatchMetabolicSubReports();
                        if (typeof renderReportsView === 'function') renderReportsView();
                        if (typeof renderSubReportTrendCharts === 'function') renderSubReportTrendCharts('daily');
                        await new Promise(r => setTimeout(r, 800));
                        const getTxt = id => (document.getElementById(id)?.innerText || '').trim();
                        return {
                            ecgQtc: getTxt('subValEcgQtc'),
                            ecgStatus: getTxt('subValEcgQtcStatus'),
                            biaFat: getTxt('subValBiaFat'),
                            biaMuscle: getTxt('subValBiaMuscle'),
                            biaBmi: getTxt('subValBiaBmi'),
                            biaWater: getTxt('subValBiaWater'),
                            gluStat: getTxt('repGluSummary') || getTxt('boxChartGlucose')?.slice(0, 260),
                            a1cStat: getTxt('boxChartA1C')?.slice(0, 260),
                            curveEcgSvgLen: (document.getElementById('curveTimelineECG')?.innerHTML || '').length,
                            curveBiaSvgLen: (document.getElementById('curveTimelineBodyComp')?.innerHTML || '').length,
                            curveBreathSvgLen: (document.getElementById('curveTimelineBreathRate')?.innerHTML || '').length,
                        };
                    })()""",
                    await_promise=True,
                )
                print("[DOM READOUT]:", json.dumps(info, indent=2))

                # Tab 04 captures
                targets_t04 = [
                    ("boxSubEcgStress", "bfm_t04_06_sub_ecg_met.png", -20),
                    ("boxSubMet", "bfm_t04_sub_met_live.png", -20),
                    ("boxSubBloodComp", "bfm_t04_07_sub_blood_bia_breath.png", -20),
                    ("boxSubBodyComp", "bfm_t04_sub_bodycomp_live.png", -20),
                    ("boxSubBreath", "bfm_t04_sub_breath_live.png", -20),
                    ("boxChartGlucose", "bfm_t04_08_glucose_a1c.png", -26),
                ]
                for elem_id, fname, off in targets_t04:
                    await scroll_workspace_to(cdp, elem_id, extra_offset=off)
                    await asyncio.sleep(0.7)
                    await cdp.capture_png(fname)

                # Tab 06 captures (Section 01 & Section 02)
                await switch_tab_top(cdp, "operations")
                await asyncio.sleep(0.9)
                await cdp.capture_png("bfm_t06_operations.png", alias="lcars_tab11_operations.png")

                await cdp.eval_js(
                    """(() => {
                        const sec = document.querySelectorAll('#pageOperations .setup-section')[1];
                        if (sec) {
                            sec.scrollIntoView({block: 'start', behavior: 'instant'});
                            const ws = document.querySelector('.lcars-workspace');
                            if (ws) ws.scrollTop -= 14;
                        }
                    })()"""
                )
                await asyncio.sleep(0.7)
                await cdp.capture_png("bfm_t06_calibration.png")

                # Tab 07 captures (Top Q1-Q3, Mid Q4-Q8, Section 02 Placement)
                await switch_tab_top(cdp, "help")
                await asyncio.sleep(0.9)
                await cdp.capture_png("bfm_t07_faq.png", alias="lcars_tab07_help.png")

                await cdp.eval_js(
                    """(() => {
                        const qs = document.querySelectorAll('#pageHelp .setup-section:first-of-type div[style*="border-left: 4px"]');
                        if (qs && qs.length >= 5) {
                            qs[4].scrollIntoView({block: 'start', behavior: 'instant'});
                            const ws = document.querySelector('.lcars-workspace');
                            if (ws) ws.scrollTop -= 18;
                        }
                    })()"""
                )
                await asyncio.sleep(0.7)
                await cdp.capture_png("bfm_t07_faq_mid.png")

                await cdp.eval_js(
                    """(() => {
                        const secs = document.querySelectorAll('#pageHelp .setup-section');
                        if (secs && secs.length >= 2) {
                            secs[1].scrollIntoView({block: 'start', behavior: 'instant'});
                            const ws = document.querySelector('.lcars-workspace');
                            if (ws) ws.scrollTop -= 20;
                        }
                    })()"""
                )
                await asyncio.sleep(0.7)
                await cdp.capture_png("bfm_t07_faq_placement.png")

    finally:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            proc.kill()
        shutil.rmtree(user_data_dir, ignore_errors=True)


if __name__ == "__main__":
    asyncio.run(capture_targeted())

