"""Capture targeted live BFM.HTM screenshots for beta.00.01.0062 across all 4 image dirs."""
import asyncio
import json
import os
import shutil
import subprocess
import sys
import time
import urllib.request

import aiohttp

sys.path.insert(0, r"D:\veepoo\tools")
from capture_beta56_screenshots import (
    BASE_URL,
    CHROME_PATH,
    OUT_DIRS,
    WORKSPACE,
    CDPSession,
    scroll_workspace_to,
    switch_tab_top,
)


async def capture_targeted():
    with urllib.request.urlopen(f"{BASE_URL}/api/subreports/today", timeout=5) as resp:
        sub_json = json.loads(resp.read().decode("utf-8"))
    print("[API /api/subreports/today summary]:")
    for k in ("ECG_QTC", "BODY_COMP", "MET_5MIN", "BLOOD_COMP", "BREATH_RATE", "OFF_WRIST_INTERVALS"):
        print(f"  {k}: {len(sub_json.get(k) or [])}")

    user_data_dir = os.path.join(WORKSPACE, "_chrome_capture_b62b")
    os.makedirs(user_data_dir, exist_ok=True)
    proc = subprocess.Popen(
        [
            CHROME_PATH,
            "--headless=new",
            "--remote-debugging-port=9250",
            f"--user-data-dir={user_data_dir}",
            "--disable-gpu",
            "--no-first-run",
            "--no-default-browser-check",
            "--window-size=1600,1050",
            "about:blank",
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    time.sleep(2.5)

    try:
        async with aiohttp.ClientSession() as session:
            ws_url = None
            for _ in range(15):
                try:
                    async with session.get("http://127.0.0.1:9250/json") as resp:
                        targets = await resp.json()
                        pages = [t for t in targets if t.get("type") == "page"]
                        if pages:
                            ws_url = pages[0]["webSocketDebuggerUrl"]
                            break
                except Exception:
                    await asyncio.sleep(0.4)
            if not ws_url:
                raise RuntimeError("Chrome CDP websocket did not appear on 9250")

            async with session.ws_connect(ws_url, max_msg_size=50 * 1024 * 1024) as ws:
                cdp = CDPSession(ws)
                await cdp.send("Page.enable")
                await cdp.send("Runtime.enable")
                await cdp.send("Page.navigate", {"url": f"{BASE_URL}/"})
                await asyncio.sleep(3.5)

                await cdp.eval_js(
                    """(async () => {
                        switchTab('reports');
                        const sel = document.getElementById('cfgTimeFormat');
                        if (sel) sel.value = '12h';
                        if (typeof fetchServer2DayTimeline === 'function') await fetchServer2DayTimeline();
                        if (typeof updateWatchMetabolicSubReports === 'function') await updateWatchMetabolicSubReports();
                        if (typeof renderReportsView === 'function') renderReportsView();
                        if (typeof renderSubReportTrendCharts === 'function') renderSubReportTrendCharts('daily');
                        await new Promise(r => setTimeout(r, 800));
                    })()""",
                    await_promise=True,
                )

                # Slide 37 panoramic summary of all live sub-reports (#boxSubEcgStress .. #boxSubBreath)
                await cdp.eval_js(
                    """(() => {
                        const pg = document.getElementById('pageReports');
                        if (pg) pg.style.zoom = '0.62';
                        const el = document.getElementById('boxSubEcgStress');
                        if (el) el.scrollIntoView({block: 'start', behavior: 'instant'});
                        const ws = document.querySelector('.lcars-workspace');
                        if (ws) ws.scrollTop -= 12;
                    })()"""
                )
                await asyncio.sleep(0.7)
                await cdp.capture_png("bfm_t04_met_bloodcomp_live.png")
                await cdp.eval_js("(() => { const pg = document.getElementById('pageReports'); if (pg) pg.style.zoom = ''; })()")

                # Tab 06 Section 01 clean framing (clip right after Section 01 card bottom so Section 02 doesn't dominate)
                await switch_tab_top(cdp, "operations")
                await asyncio.sleep(0.9)
                ops_rect = await cdp.eval_js(
                    """(() => {
                        const sec1 = document.querySelectorAll('#pageOperations .setup-section')[0];
                        const r = sec1 ? sec1.getBoundingClientRect() : null;
                        return r ? {x: 0, y: 0, width: 1600, height: Math.min(1050, Math.ceil(r.bottom + 24)), scale: 1} : null;
                    })()"""
                )
                await cdp.capture_png("bfm_t06_operations.png", alias="lcars_tab11_operations.png", clip=ops_rect)

                # Tab 07 Mid (Q5-Q8) & Section 02 Placement clean framing
                await switch_tab_top(cdp, "help")
                await asyncio.sleep(0.9)
                found_q5 = await cdp.eval_js(
                    """(() => {
                        const strongs = Array.from(document.querySelectorAll('#pageHelp strong'));
                        const target = strongs.find(s => s.textContent.includes('Q5:'));
                        const card = target ? target.closest('div[style*="border-radius"]') : null;
                        if (card) {
                            card.scrollIntoView({block: 'start', behavior: 'instant'});
                            const ws = document.querySelector('.lcars-workspace');
                            if (ws) ws.scrollTop -= 16;
                            return true;
                        }
                        return false;
                    })()"""
                )
                print("  scrolled Q5:", found_q5)
                await asyncio.sleep(0.7)
                await cdp.capture_png("bfm_t07_faq_mid.png")

                place_clip = await cdp.eval_js(
                    """(() => {
                        const secs = document.querySelectorAll('#pageHelp .setup-section');
                        if (secs && secs.length >= 2) {
                            secs[1].scrollIntoView({block: 'start', behavior: 'instant'});
                            const ws = document.querySelector('.lcars-workspace');
                            if (ws) ws.scrollTop -= 20;
                            const r = secs[1].getBoundingClientRect();
                            return {x: 0, y: 0, width: 1600, height: Math.max(480, Math.min(1050, Math.ceil(r.bottom + 28))), scale: 1};
                        }
                        return null;
                    })()"""
                )
                await asyncio.sleep(0.7)
                await cdp.capture_png("bfm_t07_faq_placement.png", clip=place_clip)

    finally:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            proc.kill()
        shutil.rmtree(user_data_dir, ignore_errors=True)


if __name__ == "__main__":
    asyncio.run(capture_targeted())

