import asyncio
import json
import os
import shutil
import subprocess
import sys
import time

import aiohttp

sys.path.insert(0, r"D:\veepoo\tools")
from capture_beta56_screenshots import (
    BASE_URL,
    CHROME_PATH,
    WORKSPACE,
    CDPSession,
    switch_tab_top,
