async def capture_estimator():
    udd = os.path.join(WORKSPACE, "_chrome_capture_b63c")
    os.makedirs(udd, exist_ok=True)
    proc = subprocess.Popen(
        [
            CHROME_PATH,
            "--headless=new",
            "--remote-debugging-port=9260",
            f"--user-data-dir={udd}",
            "--disable-gpu",
            "--no-first-run",
            "--no-default-browser-check",
            "--window-size=1600,1050",
            "about:blank",
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    time.sleep(2.5)

    try:
        async with aiohttp.ClientSession() as session:
            ws_url = None
            for _ in range(15):
                try:
                    async with session.get("http://127.0.0.1:9260/json") as resp:
                        pages = [t for t in await resp.json() if t.get("type") == "page"]
                        if pages:
                            ws_url = pages[0]["webSocketDebuggerUrl"]
                            break
                except Exception:
                    await asyncio.sleep(0.4)
            async with session.ws_connect(ws_url, max_msg_size=50 * 1024 * 1024) as ws:
                cdp = CDPSession(ws)
                await cdp.send("Page.enable")
                await cdp.send("Runtime.enable")
                await cdp.send("Page.navigate", {"url": f"{BASE_URL}/"})
                await asyncio.sleep(3.0)

                await switch_tab_top(cdp, "diettrades")
                await asyncio.sleep(0.8)

                scroll_info = await cdp.eval_js(
                    """(async () => {
                        const inp = document.getElementById('txtMealBuilderInput');
                        if (inp) inp.value = 'Banquet beef pot pie 7oz';
                        if (typeof analyzeMealWithGemini === 'function') analyzeMealWithGemini();
                        for (let i = 0; i < 30; i++) {
                            await new Promise(r => setTimeout(r, 400));
                            const cal = (document.getElementById('chipCalories')?.innerText || '').trim();
                            if (cal && !cal.startsWith('--')) break;
                        }
                        const box = document.getElementById('cardPackagedSnackMatrix');
                        if (box) box.style.display = 'none';

                        const target = document.getElementById('geminiMealAnalysisResult');
                        const scrollers = [];
                        let p = target.parentElement;
                        while (p && p !== document.documentElement) {
                            const cs = getComputedStyle(p);
                            if (p.scrollHeight > p.clientHeight + 20 && (cs.overflowY === 'auto' || cs.overflowY === 'scroll')) {
                                scrollers.push(p);
                            }
                            p = p.parentElement;
                        }
                        if (scrollers.length > 0) {
                            const sc = scrollers[0];
                            const sRect = sc.getBoundingClientRect();
                            const tRect = target.getBoundingClientRect();
                            sc.scrollTop += (tRect.top - sRect.top - 10);
                        }
                        return { scrollerId: scrollers[0]?.id || scrollers[0]?.className || 'none', cal: document.getElementById('chipCalories')?.innerText };
                    })()""",
                    await_promise=True,
                )
                print("[SCROLL INFO]:", json.dumps(scroll_info))
                await asyncio.sleep(0.7)
                await cdp.capture_png("bfm_t03_meal_estimator.png")
    finally:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            proc.kill()
        shutil.rmtree(udd, ignore_errors=True)


if __name__ == "__main__":
