    proc = subprocess.Popen(
        [
            CHROME_PATH,
            "--headless=new",
            "--remote-debugging-port=9261",
            f"--user-data-dir={udd}",
            "--disable-gpu",
            "--no-first-run",
            "--no-default-browser-check",
            "--window-size=1600,1400",
            "about:blank",
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    time.sleep(2.5)

    try:
        async with aiohttp.ClientSession() as session:
            ws_url = None
            for _ in range(15):
                try:
                    async with session.get("http://127.0.0.1:9261/json") as resp:
                        pages = [t for t in await resp.json() if t.get("type") == "page"]
                        if pages:
                            ws_url = pages[0]["webSocketDebuggerUrl"]
                            break
                except Exception:
                    await asyncio.sleep(0.4)
            async with session.ws_connect(ws_url, max_msg_size=50 * 1024 * 1024) as ws:
                cdp = CDPSession(ws)
                await cdp.send("Page.enable")
                await cdp.send("Runtime.enable")
                await cdp.send("Page.navigate", {"url": f"{BASE_URL}/"})
                await asyncio.sleep(3.0)

                await switch_tab_top(cdp, "diettrades")
                await asyncio.sleep(0.8)

                clip_rect = await cdp.eval_js(
                    """(async () => {
                        const inp = document.getElementById('txtMealBuilderInput');
                        if (inp) inp.value = 'Banquet beef pot pie 7oz';
                        if (typeof analyzeMealWithGemini === 'function') analyzeMealWithGemini();
                        for (let i = 0; i < 30; i++) {
                            await new Promise(r => setTimeout(r, 400));
                            const cal = (document.getElementById('chipCalories')?.innerText || '').trim();
                            if (cal && !cal.startsWith('--')) break;
                        }
                        const box = document.getElementById('cardPackagedSnackMatrix');
                        if (box) box.style.display = 'none';
                        const target = document.getElementById('geminiMealAnalysisResult');
                        target.scrollIntoView({block: 'start', behavior: 'instant'});
                        const r = target.getBoundingClientRect();
                        const sy = window.scrollY || 0;
                        return {
                            x: Math.max(0, Math.floor(r.left - 12)),
                            y: Math.max(0, Math.floor(r.top + sy - 10)),
                            width: Math.min(1580, Math.ceil(r.width + 24)),
                            height: Math.min(680, Math.ceil(r.height + 16)),
                            scale: 1
                        };
                    })()""",
                    await_promise=True,
                )
                print("[CLIP RECT]:", json.dumps(clip_rect))
                await asyncio.sleep(0.7)
                await cdp.capture_png("bfm_t03_meal_estimator.png", clip=clip_rect)

                # Spot-check Slide 19 & 20 HTML
                out_dir = r"C:\Users\jclou\.gemini\antigravity\brain\1eb2f37b-9c6a-4b02-88af-c0eebae67964\scratch\slide_check"
                os.makedirs(out_dir, exist_ok=True)
                await cdp.send("Emulation.setDeviceMetricsOverride", {"width": 1440, "height": 860, "deviceScaleFactor": 1, "mobile": False})
                for n in (19, 20):
                    await cdp.send("Page.navigate", {"url": f"{BASE_URL}/presentation/slide_{n}.html"})
                    await asyncio.sleep(0.7)
                    res = await cdp.send("Page.captureScreenshot", {"format": "png", "fromSurface": True})
                    with open(os.path.join(out_dir, f"check_slide_{n}.png"), "wb") as fp:
                        fp.write(base64.b64decode(res["data"]))
                    print(f"[OK] check_slide_{n}.png")
    finally:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            proc.kill()
        shutil.rmtree(udd, ignore_errors=True)


if __name__ == "__main__":
    asyncio.run(capture_estimator_clipped())

