"""Capture updated Tab 03 (no Pantry Favorites) and Tab 04 ECG QTc screenshots for beta.00.01.0066."""
import asyncio
import json
import os
import shutil
import subprocess
import sys
import time
import urllib.request

import aiohttp

sys.path.insert(0, r"D:\veepoo\tools")
from capture_beta56_screenshots import (
    BASE_URL,
    CHROME_PATH,
    WORKSPACE,
    CDPSession,
    scroll_workspace_to,
    switch_tab_top,
)


async def capture_b66():
    with urllib.request.urlopen(f"{BASE_URL}/api/subreports/today", timeout=5) as resp:
        sub = json.loads(resp.read().decode("utf-8"))
    print("[API ECG_QTC]:", json.dumps(sub.get("ECG_QTC")))
    print("[API ECG_LATEST]:", json.dumps(sub.get("ECG_LATEST")))

    udd = os.path.join(WORKSPACE, "_chrome_capture_b66")
    os.makedirs(udd, exist_ok=True)
    proc = subprocess.Popen(
        [
            CHROME_PATH, "--headless=new", "--remote-debugging-port=9269",
            f"--user-data-dir={udd}", "--disable-gpu", "--no-first-run",
            "--no-default-browser-check", "--window-size=1600,1050", "about:blank",
        ],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
    )
    time.sleep(2.5)
    try:
        async with aiohttp.ClientSession() as session:
            ws_url = None
            for _ in range(15):
                try:
                    async with session.get("http://127.0.0.1:9269/json") as resp:
                        pages = [t for t in await resp.json() if t.get("type") == "page"]
                        if pages:
                            ws_url = pages[0]["webSocketDebuggerUrl"]
                            break
                except Exception:
                    await asyncio.sleep(0.4)
            async with session.ws_connect(ws_url, max_msg_size=50 * 1024 * 1024) as ws:
                cdp = CDPSession(ws)
                await cdp.send("Page.enable")
                await cdp.send("Runtime.enable")
                await cdp.send("Page.navigate", {"url": f"{BASE_URL}/"})
                await asyncio.sleep(3.2)

                # 1. Tab 03 Step 1 (no Pantry Favorites)
                await switch_tab_top(cdp, "diettrades")
                await asyncio.sleep(1.0)
                await cdp.capture_png("bfm_t03_meal_pantry.png", alias="lcars_tab02_meal_planner.png")

                # 2. Tab 03 BOM + Step 3 (no Pantry buttons)
                bom_clip = await cdp.eval_js(
                    """(() => {
                        const c = document.getElementById('cardMealBOM');
                        if (c) c.scrollIntoView({block: 'start', behavior: 'instant'});
                        return {x: 0, y: Math.max(0, (window.scrollY || 0) - 10), width: 1584, height: 955, scale: 1};
                    })()"""
                )
                await asyncio.sleep(0.7)
                await cdp.capture_png("bfm_t03_meal_bom_grocers.png", clip=bom_clip)

                # 3. Tab 04 Sub-Report 02 ECG (reset window scroll cleanly)
                ecg_dom = await cdp.eval_js(
                    """(async () => {
                        window.scrollTo(0, 0);
                        switchTab('reports');
                        const sel = document.getElementById('cfgTimeFormat');
                        if (sel) sel.value = '12h';
                        if (typeof fetchTodaySubReports === 'function') await fetchTodaySubReports();
                        if (typeof fetchServer2DayTimeline === 'function') await fetchServer2DayTimeline();
                        if (typeof updateWatchMetabolicSubReports === 'function') await updateWatchMetabolicSubReports();
                        if (typeof renderReportsView === 'function') renderReportsView();
                        if (typeof renderSubReportTrendCharts === 'function') renderSubReportTrendCharts('daily');
                        await new Promise(r => setTimeout(r, 800));
                        const box = document.getElementById('boxSubEcgStress');
                        if (box) {
                            const wsEl = document.querySelector('.lcars-workspace');
                            if (wsEl) wsEl.scrollTop += (box.getBoundingClientRect().top - wsEl.getBoundingClientRect().top - 16);
                        }
                        window.scrollTo(0, 0);
                        return {
                            qtc: document.getElementById('subValEcgQtc')?.innerText,
                            qtcStatus: document.getElementById('subValEcgQtcStatus')?.innerText,
                            lfHf: document.getElementById('subValLfHf')?.innerText,
                            chartText: (document.getElementById('curveTimelineECG')?.innerText || '').trim()
                        };
                    })()""",
                    await_promise=True,
                )
                print("[ECG DOM]:", json.dumps(ecg_dom, indent=2))
                await asyncio.sleep(0.6)
                await cdp.capture_png("bfm_t04_06_sub_ecg_met.png")

                # 4. Update vertical 5-panel collage for Slide 37 using refreshed ECG image
                await cdp.send(
                    "Emulation.setDeviceMetricsOverride",
                    {"width": 1600, "height": 2500, "deviceScaleFactor": 1, "mobile": False},
                )
                collage_html = """<!doctype html><html><body style="margin:0;padding:12px;background:#f8fafc;font-family:monospace;box-sizing:border-box;">
                <div style="display:flex;flex-direction:column;gap:12px;width:1576px;">
                  <div style="border:2px solid #cbd5e1;border-radius:8px;background:#fff;overflow:hidden;">
                    <div style="background:#0f172a;color:#38bdf8;font-weight:800;font-size:15px;padding:6px 12px;">SUB-REPORT 02 • LIVE SYNCED LEAD-I ECG &amp; BAZETT QTC (WITH 412 / 440 MS CLINICAL THRESHOLDS)</div>
                    <img src="http://127.0.0.1:8899/images/bfm_t04_06_sub_ecg_met.png" style="width:100%;height:auto;display:block;">
                  </div>
                  <div style="border:2px solid #cbd5e1;border-radius:8px;background:#fff;overflow:hidden;">
                    <div style="background:#0f172a;color:#fbbf24;font-weight:800;font-size:15px;padding:6px 12px;">SUB-REPORT 03 &amp; 04 • LIVE MET ENERGY EXPENDITURE + OPTICAL BLOOD COMPOSITION</div>
