// Automatic Host Connection & Auto-Sync Detector
async function checkHostConnection() {
  const pill = document.getElementById('wifiStatusPill');
  const text = document.getElementById('wifiStatusText');
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 4000);
  try {
    const resp = await fetch('/api/telemetry/latest', { cache: 'no-store', signal: ctrl.signal });
    clearTimeout(timer);
    if (resp.ok) {
      isConnectedToHost = true;
      pill.className = "wifi-pill";
      text.textContent = "CONNECTED TO BFM SERVER";

      await ensureCellRegisteredWithServer();

      // Auto-upload any locally queued field meals, feelings, and med adherence
      const queue = getStagedQueue();
      if (queue.length > 0) {
        console.log(`Auto-uploading ${queue.length} staged meals now that PC is reachable...`);
        syncAllStagedMeals();
      }
      const feelingQueue = getStagedFeelings();
      if (feelingQueue.length > 0) {
        syncStagedFeelingsWithServer();
      }
      syncDailyMedWithServer();
    } else {
      throw new Error("HTTP " + resp.status);
    }
  } catch (e) {
    clearTimeout(timer);
    isConnectedToHost = false;
    pill.className = "wifi-pill offline";
    text.textContent = "FIELD MODE (SAVING LOCALLY)";
  }
}

