"""Build and sign the standalone Android BFM-Cell.apk installer (beta.00.01.0068).

Zero Bluetooth permissions: the phone Cell app exclusively logs Meals/Intake,
Feelings, and Daily Medication adherence and syncs to the BFM PC Server over
home Wi-Fi (or stages locally offline in field mode).
"""
import math
import os
import shutil
import subprocess
import sys
import zipfile

from PIL import Image, ImageDraw

WORKSPACE = r"D:\veepoo"
W11_DIR = os.path.join(WORKSPACE, "w11_htm_app")
CELL_HTML_SRC = os.path.join(W11_DIR, "cell.html")
APK_OUT = os.path.join(W11_DIR, "BFM-Cell.apk")

BUILD_DIR = os.path.join(WORKSPACE, "tools", "android_cell_apk")
JDK_BIN = os.path.join(WORKSPACE, "tools", "jdk17", "bin")
SDK_ROOT = os.path.join(WORKSPACE, "tools", "android_sdk")
BUILD_TOOLS = os.path.join(SDK_ROOT, "build-tools", "34.0.0")
ANDROID_JAR = os.path.join(SDK_ROOT, "platforms", "android-34", "android.jar")

KEYSTORE_PATH = os.path.join(BUILD_DIR, "bfm_cell_release.jks")
KEY_ALIAS = "bfmcell"
KEY_PASS = "bfm5010cell"


def get_wifi_ip():
    sys.path.insert(0, W11_DIR)
    import server
    return server.get_local_wifi_ip()


def render_cell_icons():
    """Render clean high-DPI BFM Cell icon (medical cross + Wi-Fi sync arcs, no BLE)."""
    size = 512
    img = Image.new("RGBA", (size, size), (9, 20, 40, 255))
    draw = ImageDraw.Draw(img)

    # Outer cyan ring
    draw.ellipse([18, 18, 494, 494], fill=(9, 20, 40, 255), outline=(56, 189, 248, 255), width=22)
    draw.ellipse([54, 54, 458, 458], fill=(15, 32, 63, 255), outline=(14, 165, 233, 255), width=6)

    # Bold white clinical medical cross (left-center)
    cx, cy = 220, 266
    arm_len = 86
    arm_w = 34
    draw.rounded_rectangle([cx - arm_w, cy - arm_len, cx + arm_w, cy + arm_len], radius=14, fill=(248, 250, 252, 255))
    draw.rounded_rectangle([cx - arm_len, cy - arm_w, cx + arm_len, cy + arm_w], radius=14, fill=(248, 250, 252, 255))

