    zipalign = os.path.join(BUILD_TOOLS, "zipalign.exe")
    apksigner = os.path.join(BUILD_TOOLS, "apksigner.bat")
    javac = os.path.join(JDK_BIN, "javac.exe")
    keytool = os.path.join(JDK_BIN, "keytool.exe")

    compiled_res_zip = os.path.join(BUILD_DIR, "bin", "res.zip")
    base_apk = os.path.join(BUILD_DIR, "bin", "base.apk")
    aligned_apk = os.path.join(BUILD_DIR, "bin", "aligned.apk")

    run_cmd([aapt2, "compile", "--dir", os.path.join(BUILD_DIR, "res"), "-o", compiled_res_zip], env)
    run_cmd([
        aapt2, "link",
        "-I", ANDROID_JAR,
        "--manifest", os.path.join(BUILD_DIR, "AndroidManifest.xml"),
        "--java", os.path.join(BUILD_DIR, "gen"),
        "-A", os.path.join(BUILD_DIR, "assets"),
        "-o", base_apk,
        compiled_res_zip,
    ], env)

    java_files = []
    for root in (os.path.join(BUILD_DIR, "src"), os.path.join(BUILD_DIR, "gen")):
        for dp, _, fns in os.walk(root):
            for fn in fns:
                if fn.endswith(".java"):
                    java_files.append(os.path.join(dp, fn))

    run_cmd([
        javac, "--release", "8",
        "-classpath", ANDROID_JAR,
        "-d", os.path.join(BUILD_DIR, "obj"),
        *java_files,
    ], env)

    class_files = []
    for dp, _, fns in os.walk(os.path.join(BUILD_DIR, "obj")):
        for fn in fns:
            if fn.endswith(".class"):
                class_files.append(os.path.join(dp, fn))

    run_cmd([
        d8, "--min-api", "24",
        "--lib", ANDROID_JAR,
        "--output", os.path.join(BUILD_DIR, "bin"),
        *class_files,
    ], env)

    dex_path = os.path.join(BUILD_DIR, "bin", "classes.dex")
    with zipfile.ZipFile(base_apk, "a", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.write(dex_path, "classes.dex")

    run_cmd([zipalign, "-f", "-p", "4", base_apk, aligned_apk], env)

    if not os.path.exists(KEYSTORE_PATH):
        run_cmd([
            keytool, "-genkeypair", "-v",
            "-keystore", KEYSTORE_PATH,
            "-storepass", KEY_PASS,
            "-keypass", KEY_PASS,
            "-alias", KEY_ALIAS,
            "-keyalg", "RSA",
            "-keysize", "2048",
            "-validity", "10000",
            "-dname", "CN=BFM Cell, OU=Medical, O=BFM System, L=Sultan, ST=WA, C=US",
        ], env)

    run_cmd([
        apksigner, "sign",
        "--ks", KEYSTORE_PATH,
        "--ks-key-alias", KEY_ALIAS,
        "--ks-pass", f"pass:{KEY_PASS}",
        "--key-pass", f"pass:{KEY_PASS}",
        "--out", APK_OUT,
        aligned_apk,
    ], env)

    verify_out = run_cmd([apksigner, "verify", "--verbose", APK_OUT], env)
    size_kb = os.path.getsize(APK_OUT) / 1024.0
    print(f"[OK] Built & signed {APK_OUT} ({size_kb:.1f} KB)")
    print(verify_out)


if __name__ == "__main__":
    build_apk()

