def _encode_png_rgba(width, height, rgba_bytes):
    def chunk(tag, data):
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    raw = bytearray()
    stride = width * 4
    for y in range(height):
        raw.append(0)
        start = y * stride
        raw.extend(rgba_bytes[start : start + stride])
    ihdr = struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)
    idat = zlib.compress(bytes(raw), 6)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) + chunk(b"IDAT", idat) + chunk(b"IEND", b"")


def _render_icon_bytes(px):
    """Pure-Python rasterizer for crisp BFM Cell launcher icon (navy + cyan ring + cross + Wi-Fi arcs)."""
    buf = bytearray(px * px * 4)
    inv = 512.0 / px
    ax, ay = 342.0, 224.0
    cx, cy = 216.0, 272.0

    for y in range(px):
        fy = (y + 0.5) * inv
        for x in range(px):
            fx = (x + 0.5) * inv
            dx_c = fx - 256.0
            dy_c = fy - 256.0
            dist_c = math.hypot(dx_c, dy_c)

            # Base background: deep navy
            r, g, b, a = 9, 20, 40, 255
            if 228.0 <= dist_c <= 248.0:
                r, g, b = 56, 189, 248
            elif dist_c < 228.0:
                r, g, b = 15, 32, 63

            # Bold white medical cross
            in_vert = abs(fx - cx) <= 28.0 and abs(fy - cy) <= 78.0
            in_horiz = abs(fx - cx) <= 78.0 and abs(fy - cy) <= 28.0
            if in_vert or in_horiz:
                r, g, b = 248, 250, 252

            # Upper-right Wi-Fi sync arcs + dot (no BLE)
            dw = math.hypot(fx - ax, fy - ay)
            ang = math.degrees(math.atan2(fy - ay, fx - ax))
            if dw <= 16.0:
                r, g, b = 74, 222, 128
            elif -138.0 <= ang <= -42.0:
                if 34.0 <= dw <= 49.0:
                    r, g, b = 56, 189, 248
                elif 68.0 <= dw <= 83.0:
                    r, g, b = 125, 211, 252
                elif 102.0 <= dw <= 117.0:
                    r, g, b = 74, 222, 128

            idx = (y * px + x) * 4
            buf[idx : idx + 4] = bytes((r, g, b, a))
    return _encode_png_rgba(px, px, buf)


