async function callDirectGeminiApi(text, photos) {
  const apiKey = getCellGeminiKey();
  if (!apiKey) return null;
  const prompt = [
    'You are a clinical diabetic nutritionist analyzing a planned meal before the patient eats.',
    `Query: ${text || 'Analyze the attached food/menu photo.'}`,
    'Instructions:',
    '1. Use Google Search to locate the exact restaurant/vendor by name & city/ZIP if specified.',
    '2. Use published restaurant nutrition facts if available. If unpublished, provide a realistic grounded clinical midpoint estimate and state the typical calorie/carb range, known menu versions, and clarifying details in gemini_notes.',
    '3. Return ONLY one valid JSON object with these exact keys:',
    '{',
    '  "meal_name": "short descriptive title",',
    '  "vendor_matched": "Specific Restaurant Name (Street/City, State ZIP)",',
    '  "calories": 0,',
    '  "net_carbs": 0.0,',
    '  "total_carbs": 0.0,',
    '  "fiber": 0.0,',
    '  "protein": 0.0,',
    '  "fat": 0.0,',
    '  "glycemic_load": "number (Safe Low-Med | Moderate | SEVERE SPIKE HAZARD)",',
    '  "meets_goal": true,',
    '  "projected_spike": "+X to +Y mg/dL postprandial rise",',
    '  "gemini_notes": "Location confirmation, official vs typical range explanation, menu variations, and what clarifying details refine accuracy.",',
    '  "trade_alternatives": ["swap 1", "swap 2"],',
    '  "glut4_recommendation": "Specific post-meal GLUT4 walking prescription."',
    '}'
  ].join('\n');

  const parts = [{ text: prompt }];
  if (Array.isArray(photos)) {
    for (const p of photos) {
      if (typeof p === 'string' && p.includes('base64,')) {
        const splitIdx = p.indexOf('base64,');
        const hdr = p.slice(0, splitIdx);
        const b64 = p.slice(splitIdx + 7);
        const mime = hdr.includes('image/png') ? 'image/png' : 'image/jpeg';
        parts.push({ inline_data: { mime_type: mime, data: b64 } });
      }
    }
  }

  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${encodeURIComponent(apiKey)}`;
  const resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [{ parts }],
      tools: [{ google_search: {} }],
      generationConfig: { temperature: 0.2 }
    })
  });
  if (!resp.ok) {
    const errTxt = await resp.text().catch(() => '');
    throw new Error(`Gemini HTTP ${resp.status}: ${errTxt.slice(0, 160)}`);
  }
  const raw = await resp.json();
  let textOut = '';
  for (const cand of (raw.candidates || [])) {
    for (const pt of (cand.content?.parts || [])) {
      if (pt.text) textOut += pt.text;
    }
  }
  textOut = textOut.trim().replace(/^```[a-zA-Z]*\s*/, '').replace(/\s*```$/, '');
  const m = textOut.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Gemini returned non-JSON response');
  const parsed = JSON.parse(m[0]);
  const totC = Math.round((parseFloat(parsed.total_carbs ?? parsed.net_carbs ?? 0) || 0) * 10) / 10;
  const fib = Math.round((parseFloat(parsed.fiber ?? 0) || 0) * 10) / 10;
  const netC = Math.round((parseFloat(parsed.net_carbs ?? Math.max(0, totC - fib)) || 0) * 10) / 10;
  const cals = Math.round(parseFloat(parsed.calories ?? 0) || 0);
  parsed.calories = cals;
  parsed.net_carbs = netC;
  parsed.total_carbs = totC;
  parsed.fiber = fib;
  parsed.protein = Math.round((parseFloat(parsed.protein ?? 0) || 0) * 10) / 10;
  parsed.fat = Math.round((parseFloat(parsed.fat ?? 0) || 0) * 10) / 10;
  parsed.meets_goal = (parsed.meets_goal !== undefined) ? Boolean(parsed.meets_goal) : (netC <= 45);
  const vm = String(parsed.vendor_matched || 'Google Gemini Nutrition');
  parsed.vendor_matched = vm.includes('Live Google Gemini') ? vm : `${vm} (Live Google Gemini)`;
  return parsed;
}

async function analyzeMeal() {
  const input = document.getElementById('txtMealInput');
  const text = input ? input.value.trim() : '';
  if (!text && uploadedPhotos.length === 0) {
    alert('Describe your meal or restaurant, record voice, or attach a plate photo first.');
    return;
  }

  const btn = document.getElementById('btnAnalyze');
  const originalText = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span>⏳ CALLING LIVE GOOGLE GEMINI...</span>';

  try {
    // 1. Direct cellular/Wi-Fi call to Google Gemini whenever key is on phone
    if (!getCellGeminiKey() && isConnectedToHost) {
      await syncGeminiKeyWithServer();
    }
    if (getCellGeminiKey()) {
      const liveResult = await callDirectGeminiApi(text, uploadedPhotos);
      if (liveResult) {
        renderAnalysis(liveResult);
        return;
      }
    }

    // 2. If connected to BFM PC Server (e.g. env var GEMINI_API_KEY on PC), ask server
    if (isConnectedToHost) {
      const resp = await fetch('/api/meal/analyze', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          meal_name: text || 'Mobile Plate Photo',
          meal_type: selectedMealType,
          description: text,
          photo_data: uploadedPhotos.length > 0 ? uploadedPhotos[0] : '',
          photo_count: uploadedPhotos.length,
          source: 'MOBILE_CELL_APK',
          analyze_only: true
        })
      });
      if (!resp.ok) throw new Error('HTTP error ' + resp.status);
      const data = await resp.json();
      const a = data.analysis || data;
      if (a && (a.vendor_matched || '').includes('Live Gemini')) {
        renderAnalysis(a);
        return;
      }
    }

    // 3. Pure Zero-Data Reality: never invent fake macros when no Gemini key is set
    renderAnalysis(makeZeroUnanalyzedRecord(
      text,
      "⚠️ Live Google Gemini API key not set. Tap '🔑 SET GEMINI API KEY' at top (or save once in BFM Server 10-CONFIG -> Section 11B on Home Wi-Fi) so this phone can look up real restaurant/meal data over cellular or Wi-Fi."
    ));
  } catch (err) {
    console.warn('[MIL-SPEC HANDLED FAULT] Live Gemini analyzeMeal failed:', err);
    renderAnalysis(makeZeroUnanalyzedRecord(
      text,
      `⚠️ Live Gemini lookup failed (${err.message || err}). Check cellular/Wi-Fi signal or tap '🔑 GEMINI API KEY' to verify your key, or tap '💾 STAGE FOR HOME PC' to save locally. Zero fake guesses shown.`
    ));
  } finally {
    btn.disabled = false;
    btn.innerHTML = originalText;
  }
}

