    };
  }

  // 7. General Semantic Fallback (Sultan Bakery & Deli Sandwiches first)
  if (/sultan bakery|bakery.*sandwich|ham and cheese|ham & cheese|grilled cheese|sandwich|panini|club|blt/.test(t)) {
