  };
}

async function analyzeMeal() {
  const input = document.getElementById('txtMealInput');
  const text = input ? input.value.trim() : "";
  const btn = document.getElementById('btnAnalyze');
  const originalText = btn.innerHTML;

  btn.disabled = true;
  btn.innerHTML = "<span>⏳ GEMINI DECOMPOSING INGREDIENTS...</span>";

  try {
    const payload = {
      meal_name: text || "Custom Ambulatory Meal",
      meal_type: selectedMealType,
      description: text,
      photo_data: uploadedPhotos.length > 0 ? uploadedPhotos[0] : "",
      photo_count: uploadedPhotos.length,
      source: "MOBILE_WI-FI_GATEWAY",
      analyze_only: true // Do not write to DB on pre-check
    };

    const resp = await fetch('/api/meal/analyze', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    if (!resp.ok) throw new Error("HTTP error " + resp.status);
    const data = await resp.json();
    const a = data.analysis || data;
    if (a && (data.status === "SUCCESS" || data.status === "ANALYSIS_PREVIEW" || a.calories !== undefined)) {
      renderAnalysis(a);
    } else {
      throw new Error("Analysis failed");
    }
  } catch (err) {
    console.warn("Server call failed, using high-precision clinical fallback:", err);
    const fallback = calculateClinicalNutrition(text);
    renderAnalysis(fallback);
  } finally {
    btn.disabled = false;
    btn.innerHTML = originalText;
  }
}

