"""Verify clean APK (zero hardcoded crap), Pure Zero-Data unconfigured response, and direct Gemini API wiring."""
import asyncio
import json
import os
import re
import shutil
import subprocess
import sys
import time
import urllib.request

import aiohttp

sys.path.insert(0, r"D:\veepoo\tools")
from capture_beta56_screenshots import CHROME_PATH, WORKSPACE, CDPSession

LAN_BASE = "http://192.168.12.207:8899"
CELL_PATH = r"D:\veepoo\w11_htm_app\cell.html"


def check_static_and_http():
    src = open(CELL_PATH, "r", encoding="utf-8").read()
    forbidden = ["calculateClinicalNutrition", "setPreset", "Costco Hot Dog", "Clove and cinnamon tea", "cellPackagedSnackMatrix"]
    for tok in forbidden:
        assert tok not in src, f"Forbidden legacy string still in cell.html: {tok}"
    opens = len(re.findall(r"<div\b[^>]*>", src, re.I))
    closes = len(re.findall(r"</div>", src, re.I))
    assert opens == closes, f"cell.html div imbalance {opens} vs {closes}"
    print(f"[PASS] cell.html purged cleanly (Opens={opens}, Closes={closes}, Diff=0, zero forbidden junk)")

    with urllib.request.urlopen(f"{LAN_BASE}/api/config/gemini_key_sync", timeout=5) as r:
        assert r.status == 200
        d = json.loads(r.read().decode("utf-8"))
        assert "configured" in d and "api_key" in d
        print("[PASS] /api/config/gemini_key_sync -> 200:", {"configured": d["configured"]})


async def check_cdp_cell_clean():
    udd = os.path.join(WORKSPACE, "_chrome_b71_verify")
    if os.path.exists(udd):
        shutil.rmtree(udd)
    os.makedirs(udd, exist_ok=True)
    proc = subprocess.Popen(
        [
            CHROME_PATH, "--headless=new", "--remote-debugging-port=9285",
            f"--user-data-dir={udd}", "--disable-gpu", "--no-first-run",
            "--no-default-browser-check", "--window-size=430,900", "about:blank",
        ],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
    )
    time.sleep(2.2)
    try:
        async with aiohttp.ClientSession() as session:
            ws_url = None
            for _ in range(15):
                try:
                    async with session.get("http://127.0.0.1:9285/json") as resp:
                        pages = [t for t in await resp.json() if t.get("type") == "page"]
                        if pages:
                            ws_url = pages[0]["webSocketDebuggerUrl"]
                            break
                except Exception:
                    await asyncio.sleep(0.3)
            async with session.ws_connect(ws_url, max_msg_size=20 * 1024 * 1024) as ws:
                cdp = CDPSession(ws)
                await cdp.send("Page.enable")
                await cdp.send("Runtime.enable")
                await cdp.send("Page.navigate", {
                    "url": "file:///D:/veepoo/w11_htm_app/cell.html?server=http://127.0.0.1:8899&native=1"
                })
                await asyncio.sleep(2.0)

                init_state = await cdp.eval_js(
                    """(() => ({
                        inputVal: document.getElementById('txtMealInput').value,
                        bannerDisplay: getComputedStyle(document.getElementById('pwaInstallBanner')).display,
                        wifiText: document.getElementById('wifiStatusText').textContent,
                        geminiBtnText: document.getElementById('btnCellGeminiKey').textContent.trim()
                    }))()"""
                )
                print("[PASS] CDP Init:", init_state)
                assert init_state["inputVal"] == ""
                assert init_state["bannerDisplay"] == "none"
                assert init_state["wifiText"] == "CONNECTED TO BFM SERVER"

                # 1. With NO Gemini key configured, must return strict 0 (Zero Mock Data) + prompt
                await cdp.eval_js(
                    """(() => {
                        localStorage.removeItem('bfm_gemini_api_key');
                        document.getElementById('txtMealInput').value = 'Sultan Bakery Sultan WA 98294, Ham and cheese sandwich';
                        document.getElementById('btnAnalyze').click();
                    })()"""
                )
                await asyncio.sleep(1.5)
                zero_res = await cdp.eval_js(
                    """(() => ({
                        calories: document.getElementById('resCalories').textContent,
                        netCarbs: document.getElementById('resNetCarbs').textContent,
                        vendor: document.getElementById('resVendor').textContent,
                        notes: document.getElementById('resNotes').textContent
                    }))()"""
                )
                print("[PASS] CDP Unconfigured Zero-Data Check:", zero_res)
                assert zero_res["calories"] == "0"
                assert zero_res["netCarbs"] == "0 g"
                assert "API key" in zero_res["notes"]

                # 2. Verify callDirectGeminiApi() builds valid gemini-2.5-flash + google_search payload,
                #    parses real JSON response cleanly, and stages locally to staged_meals_queue
                direct_test = await cdp.eval_js(
                    """(async () => {
                        let capturedUrl = '';
                        let capturedBody = null;
                        const realFetch = window.fetch;
                        window.fetch = async (url, init) => {
                            if (String(url).includes('generativelanguage.googleapis.com')) {
                                capturedUrl = String(url);
                                capturedBody = JSON.parse(init.body);
                                const fakeGeminiPayload = {
                                    candidates: [{
                                        content: {
                                            parts: [{
                                                text: JSON.stringify({
                                                    meal_name: 'Sultan Bakery Deli Ham & Cheese Sandwich',
                                                    vendor_matched: 'Sultan Bakery (31407 US-2, Sultan, WA 98294)',
                                                    calories: 395,
                                                    net_carbs: 29.0,
                                                    total_carbs: 32.0,
                                                    fiber: 3.0,
                                                    protein: 23.0,
                                                    fat: 18.0,
                                                    glycemic_load: '16 (Safe Low-Med)',
                                                    meets_goal: true,
                                                    projected_spike: '+22 to +35 mg/dL',
                                                    gemini_notes: 'Live grounded range 350-440 kcal.',
                                                    trade_alternatives: ['Open-faced cut saves ~14g carbs'],
                                                    glut4_recommendation: '15-min gentle walk'
                                                })
                                            }]
                                        }
                                    }]
                                };
                                return new Response(JSON.stringify(fakeGeminiPayload), {status: 200, headers: {'Content-Type': 'application/json'}});
                            }
                            return realFetch(url, init);
                        };
                        localStorage.setItem('bfm_gemini_api_key', 'AIzaTestHarnessKey00000000');
                        renderGeminiKeyButton();
                        document.getElementById('txtMealInput').value = 'Sultan Bakery Sultan WA 98294, Ham and cheese sandwich';
                        await analyzeMeal();
                        const resCals = document.getElementById('resCalories').textContent;
                        const resVendor = document.getElementById('resVendor').textContent;
                        stageMealForSync();
                        const queuedCount = getStagedQueue().length;
                        localStorage.removeItem('staged_meals_queue');
                        localStorage.removeItem('bfm_gemini_api_key');
                        renderGeminiKeyButton();
                        window.fetch = realFetch;
                        return {
                            capturedUrl: capturedUrl.split('?')[0],
                            hasGoogleSearchTool: Array.isArray(capturedBody?.tools) && ('google_search' in capturedBody.tools[0]),
                            resCals,
                            resVendor,
                            queuedCount
                        };
                    })()""",
                    await_promise=True,
                )
                print("[PASS] CDP Direct Gemini + Field Stage Check:", direct_test)
                assert direct_test["capturedUrl"].endswith("/models/gemini-2.5-flash:generateContent")
                assert direct_test["hasGoogleSearchTool"] is True
                assert direct_test["resCals"] == "395"
                assert "Live Google Gemini" in direct_test["resVendor"]
                assert direct_test["queuedCount"] == 1
    finally:
        proc.terminate()
        try:
            proc.wait(timeout=3)
        except Exception:
            proc.kill()
        if os.path.exists(udd):
            shutil.rmtree(udd, ignore_errors=True)


if __name__ == "__main__":
    check_static_and_http()
    asyncio.run(check_cdp_cell_clean())

