"""Verify Tab 03 Saved Meals DOM on http://127.0.0.1:8899 & file:///D:/veepoo/BFM.HTM and refresh Tab 03 PNGs."""
import asyncio
import base64
import json
import os
import shutil
import struct
import subprocess
import time
import urllib.request

import aiohttp

CHROME_PATH = r"C:\Program Files\Google\Chrome\Application\chrome.exe"
BASE_URL = "http://127.0.0.1:8899"
WORKSPACE = r"D:\veepoo"
OUT_DIRS = [
    os.path.join(WORKSPACE, "presentation", "images"),
    os.path.join(WORKSPACE, "presentation", "slides", "images"),
    os.path.join(WORKSPACE, "slides", "images"),
    os.path.join(WORKSPACE, "images"),
]


class CDPSession:
    def __init__(self, ws):
        self.ws = ws
        self.msg_id = 1

    async def send(self, method, params=None):
        mid = self.msg_id
        self.msg_id += 1
        payload = {"id": mid, "method": method}
        if params:
            payload["params"] = params
        await self.ws.send_json(payload)
        while True:
            raw = await self.ws.receive_json()
            if raw.get("id") == mid:
                if "error" in raw:
                    raise RuntimeError(f"CDP error on {method}: {raw['error']}")
                return raw.get("result", {})

    async def eval_js(self, expr, await_promise=False):
        res = await self.send(
            "Runtime.evaluate",
            {"expression": expr, "returnByValue": True, "awaitPromise": await_promise},
        )
        if "exceptionDetails" in res:
            raise RuntimeError(f"JS exception: {res['exceptionDetails']}")
        return res.get("result", {}).get("value")

    async def capture_png(self, filename, alias=None):
        res = await self.send("Page.captureScreenshot", {"format": "png", "fromSurface": True})
        data = base64.b64decode(res["data"])
        if data[:8] != b"\x89PNG\r\n\x1a\n":
            raise ValueError(f"Invalid PNG signature for {filename}")
        w, h = struct.unpack(">II", data[16:24])
        if len(data) < 15000:
            raise ValueError(f"Captured PNG too small ({len(data)} bytes) for {filename}")
        primary_path = os.path.join(OUT_DIRS[0], filename)
        with open(primary_path, "wb") as fp:
            fp.write(data)
        for d in OUT_DIRS[1:]:
            shutil.copy2(primary_path, os.path.join(d, filename))
        if alias:
            for d in OUT_DIRS:
                shutil.copy2(primary_path, os.path.join(d, alias))
        print(f"  [OK] {filename:<42} {len(data):>8} bytes  ({w}x{h})")


async def verify_vector(cdp, url, capture=False):
    await cdp.send("Page.navigate", {"url": url})
    await asyncio.sleep(3.2)
    await cdp.eval_js(
        """(async () => {
            localStorage.setItem('bfm_legal_accepted', 'BFM-BETA1-2026');
            localStorage.setItem('bfm_time_format', '12h');
            localStorage.setItem('bfm_time_format_user_set', '1');
            const m = document.getElementById('modalLegalStartup');
            if (m) m.style.display = 'none';
            if (typeof applyTheme === 'function') applyTheme('light');
            if (typeof loadMealsFromServer === 'function') await loadMealsFromServer();
            switchTab('diettrades');
            const ws = document.querySelector('.lcars-workspace');
            if (ws) ws.scrollTop = 0;
        })()""",
        await_promise=True,
    )
    await asyncio.sleep(1.5)

    info = await cdp.eval_js(
        """(() => {
            const pantry = document.getElementById('sectionMealPantry');
            const lb = document.getElementById('listboxPopularMeals');
            const opts = lb ? Array.from(lb.options).filter(o => o.value) : [];
            const secNew = document.getElementById('sectionNewMeal');
            const discoveryCount = secNew ? Array.from(secNew.querySelectorAll('button')).filter(b => /hot candy|blueberry cake|ice cream parfait|chocolate candy/i.test(b.textContent)).length : -1;
            const btns = Array.from(document.querySelectorAll('#tab-diettrades button')).map(b => b.textContent.trim());
            const hasAddMeal = btns.some(t => t.includes('ADD TO PANTRY AS MEAL'));
            const hasAddSnack = btns.some(t => t.includes('ADD TO PANTRY AS SNACK'));
            const hasConsume = btns.some(t => t.includes('CONSUME NOW'));
            const has13Lane = btns.some(t => t.includes('VIEW IN 13-LANE CHART'));
            return {
                pantryVisible: Boolean(pantry && pantry.offsetParent !== null),
                optionCount: opts.length,
                firstOption: opts[0] ? opts[0].textContent : null,
                discoveryCount,
                hasAddMeal,
                hasAddSnack,
                hasConsume,
                has13Lane,
            };
        })()"""
    )
    print(f"VECTOR {url}: {json.dumps(info)}")
    assert info["pantryVisible"], f"Pantry not visible on {url}"
    assert info["optionCount"] >= 15, f"Expected >=15 saved meals, got {info['optionCount']} on {url}"
    assert info["discoveryCount"] == 0, f"Discovery buttons still present on {url}"
    assert info["hasAddMeal"] and info["hasAddSnack"] and info["hasConsume"] and info["has13Lane"], f"Missing Step 3 buttons on {url}: {info}"

    if capture:
        await cdp.capture_png("bfm_t03_meal_pantry.png", alias="lcars_tab02_meal_planner.png")
        await cdp.eval_js(
            """(() => {
                const ws = document.querySelector('.lcars-workspace') || document.scrollingElement;
                const el = document.getElementById('cardMealBOM');
                if (el) { el.scrollIntoView({block: 'start', behavior: 'instant'}); if (ws) ws.scrollTop -= 16; }
            })()"""
        )
        await asyncio.sleep(0.7)
        await cdp.capture_png("bfm_t03_meal_bom_grocers.png")


async def main():
    with urllib.request.urlopen(f"{BASE_URL}/api/telemetry/latest", timeout=5) as resp:
        assert resp.status == 200
    for d in OUT_DIRS:
        os.makedirs(d, exist_ok=True)
    user_data_dir = os.path.join(WORKSPACE, "_chrome_capture_profile3")
    os.makedirs(user_data_dir, exist_ok=True)
    proc = subprocess.Popen(
        [
            CHROME_PATH,
            "--headless=new",
            "--remote-debugging-port=9252",
            f"--user-data-dir={user_data_dir}",
            "--disable-gpu",
            "--no-first-run",
            "--no-default-browser-check",
            "--window-size=1600,1050",
            "about:blank",
        ],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    time.sleep(2.2)
    try:
        async with aiohttp.ClientSession() as session:
            ws_url = None
            for _ in range(15):
                try:
                    async with session.get("http://127.0.0.1:9252/json") as resp:
                        pages = [t for t in await resp.json() if t.get("type") == "page"]
                        if pages:
                            ws_url = pages[0]["webSocketDebuggerUrl"]
                            break
                except Exception:
                    time.sleep(0.4)
            if not ws_url:
                raise RuntimeError("No CDP page")
            async with session.ws_connect(ws_url, max_msg_size=64 * 1024 * 1024) as ws:
                cdp = CDPSession(ws)
                await cdp.send("Page.enable")
                await cdp.send("Runtime.enable")
                await cdp.send(
                    "Emulation.setDeviceMetricsOverride",
                    {"width": 1600, "height": 1050, "deviceScaleFactor": 1, "mobile": False},
                )
                await verify_vector(cdp, f"{BASE_URL}/index.html", capture=True)
                await verify_vector(cdp, "file:///D:/veepoo/BFM.HTM", capture=False)
    finally:
        proc.terminate()


if __name__ == "__main__":
    asyncio.run(main())

