38: def _encode_png_rgba(width, height, rgba_bytes):
39:     def chunk(tag, data):
40:         return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
41: 
42:     raw = bytearray()
43:     stride = width * 4
44:     for y in range(height):
45:         raw.append(0)
46:         start = y * stride
47:         raw.extend(rgba_bytes[start : start + stride])
48:     ihdr = struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)
49:     idat = zlib.compress(bytes(raw), 6)
50:     return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) + chunk(b"IDAT", idat) + chunk(b"IEND", b"")
