53: def _render_icon_bytes(px):
54:     """Pure-Python rasterizer for crisp BFM Cell launcher icon (navy + cyan ring + cross + Wi-Fi arcs)."""
55:     buf = bytearray(px * px * 4)
56:     inv = 512.0 / px
57:     ax, ay = 342.0, 224.0
58:     cx, cy = 216.0, 272.0
59: 
60:     for y in range(px):
61:         fy = (y + 0.5) * inv
62:         for x in range(px):
63:             fx = (x + 0.5) * inv
64:             dx_c = fx - 256.0
65:             dy_c = fy - 256.0
66:             dist_c = math.hypot(dx_c, dy_c)
67: 
68:             # Base background: deep navy
69:             r, g, b, a = 9, 20, 40, 255
70:             if 228.0 <= dist_c <= 248.0:
71:                 r, g, b = 56, 189, 248
72:             elif dist_c < 228.0:
73:                 r, g, b = 15, 32, 63
74: 
75:             # Bold white medical cross
76:             in_vert = abs(fx - cx) <= 28.0 and abs(fy - cy) <= 78.0
77:             in_horiz = abs(fx - cx) <= 78.0 and abs(fy - cy) <= 28.0
78:             if in_vert or in_horiz:
79:                 r, g, b = 248, 250, 252
80: 
81:             # Upper-right Wi-Fi sync arcs + dot (no BLE)
82:             dw = math.hypot(fx - ax, fy - ay)
83:             ang = math.degrees(math.atan2(fy - ay, fx - ax))
84:             if dw <= 16.0:
85:                 r, g, b = 74, 222, 128
86:             elif -138.0 <= ang <= -42.0:
87:                 if 34.0 <= dw <= 49.0:
88:                     r, g, b = 56, 189, 248
89:                 elif 68.0 <= dw <= 83.0:
90:                     r, g, b = 125, 211, 252
91:                 elif 102.0 <= dw <= 117.0:
92:                     r, g, b = 74, 222, 128
93: 
94:             idx = (y * px + x) * 4
95:             buf[idx : idx + 4] = bytes((r, g, b, a))
96:     return _encode_png_rgba(px, px, buf)
