function initMealTypeByTime() {
  const hr = new Date().getHours();
  if (hr >= 5 && hr < 11) setMealType('Breakfast');
  else if (hr >= 11 && hr < 15) setMealType('Lunch');
  else if (hr >= 17 && hr < 22) setMealType('Dinner');
  else setMealType('Snack');
