function parseMealQueryAndVenue(rawText) {
  const clean = (rawText || '').trim();
  if (!clean) return { venue: '', items: [] };
  let venue = '';
  let foodText = clean;
  if (clean.includes(',')) {
    const commaParts = clean.split(',').map(s => s.trim()).filter(Boolean);
    if (commaParts.length >= 2) {
      const head = commaParts[0];
      const looksLikeVenue = /\b\d{5}\b|\b(?:wa|or|ca|id|ny|tx|fl)\b|bakery|restaurant|resturant|pizzeria|cafe|diner|drive-?in|bistro|grill|kitchen|deli|market|house|sultan/i.test(head);
      if (looksLikeVenue) {
        venue = head;
        foodText = commaParts.slice(1).join(', ');
      }
    }
  }
  const pairedRe = /\b(ham|mac|macaroni|peanut\s+butter|pb|fish|rice|beans|bacon|chips|biscuits|franks)\s+and\s+(cheese|jelly|chips|beans|rice|eggs|salsa|gravy)\b/gi;
  const guarded = foodText.replace(pairedRe, (_, a, b) => `${a}__PAIR_AND__${b}`);
  const items = guarded
    .split(/,|\band\b/i)
    .map(s => s.replace(/__PAIR_AND__/g, ' and ').trim())
    .filter(Boolean)
    .slice(0, 4);
  return { venue, items };
}

function pickUsdaNutrient(food, nameStartsWith, requireKcal) {
  const list = Array.isArray(food.foodNutrients) ? food.foodNutrients : [];
  for (const n of list) {
    const nm = String(n.nutrientName || '');
    const u = String(n.unitName || '').toUpperCase();
    if (nm === nameStartsWith || nm.startsWith(nameStartsWith)) {
      if (requireKcal && u !== 'KCAL') continue;
      const v = parseFloat(n.value);
      if (!Number.isNaN(v)) return v;
    }
  }
  return 0;
}

function pickUsdaServingGrams(food) {
  const measures = Array.isArray(food.foodMeasures) ? food.foodMeasures : [];
  const preferredOrder = [/regular|medium|standard|sandwich/i, /cup|bowl|serving/i];
  for (const rx of preferredOrder) {
    for (const m of measures) {
      const gw = parseFloat(m.gramWeight);
      if (rx.test(String(m.disseminationText || '')) && gw >= 30 && gw <= 450) {
        return { grams: gw, label: m.disseminationText || `${Math.round(gw)}g` };
      }
    }
  }
  for (const m of measures) {
    const gw = parseFloat(m.gramWeight);
    if (gw >= 30 && gw <= 450) {
      return { grams: gw, label: m.disseminationText || `${Math.round(gw)}g` };
    }
  }
  const ss = parseFloat(food.servingSize);
  const su = String(food.servingSizeUnit || '').toLowerCase();
  if ((su === 'g' || su === 'ml') && ss >= 30 && ss <= 450) {
    return { grams: ss, label: `${Math.round(ss)}${su} serving` };
  }
  return { grams: 100, label: '100g standard serving' };
}

async function callPublicUsdaNutritionApi(text) {
  const { venue, items } = parseMealQueryAndVenue(text);
  if (!items.length) return null;
  let totalKcal = 0, totalCarbs = 0, totalFiber = 0, totalPro = 0, totalFat = 0;
  const matchedNotes = [];
  for (const comp of items) {
    try {
      const url = `https://api.nal.usda.gov/fdc/v1/foods/search?api_key=DEMO_KEY&pageSize=6&query=${encodeURIComponent(comp)}`;
      const resp = await fetch(url, { cache: 'no-store' });
      if (!resp.ok) continue;
      const data = await resp.json();
      const foods = Array.isArray(data.foods) ? data.foods : [];
      if (!foods.length) continue;
      let chosen = foods.find(f => f.dataType === 'Survey (FNDDS)' && Array.isArray(f.foodMeasures) && f.foodMeasures.length > 0)
        || foods.find(f => (f.dataType === 'Survey (FNDDS)' || f.dataType === 'SR Legacy'))
        || foods.find(f => parseFloat(f.servingSize) >= 30 && parseFloat(f.servingSize) <= 450)
        || foods[0];
      const kcal100 = pickUsdaNutrient(chosen, 'Energy', true);
      const carb100 = pickUsdaNutrient(chosen, 'Carbohydrate, by difference', false);
      const fib100 = pickUsdaNutrient(chosen, 'Fiber, total dietary', false);
      const pro100 = pickUsdaNutrient(chosen, 'Protein', false);
      const fat100 = pickUsdaNutrient(chosen, 'Total lipid (fat)', false);
      if (kcal100 <= 0 && carb100 <= 0 && pro100 <= 0 && fat100 <= 0) continue;
      const srv = pickUsdaServingGrams(chosen);
      const scale = srv.grams / 100.0;
      const k = Math.round(kcal100 * scale);
      const c = Math.round(carb100 * scale * 10) / 10;
      const fb = Math.round(fib100 * scale * 10) / 10;
      const pr = Math.round(pro100 * scale * 10) / 10;
      const ft = Math.round(fat100 * scale * 10) / 10;
      totalKcal += k;
      totalCarbs += c;
      totalFiber += fb;
      totalPro += pr;
      totalFat += ft;
      matchedNotes.push(`${chosen.description} (${srv.label}, ${Math.round(srv.grams)}g -> ${k} kcal, ${Math.max(0, Math.round((c - fb) * 10) / 10)}g net)`);
    } catch (e) {
      console.warn('[MIL-SPEC HANDLED FAULT] USDA component lookup failed:', comp, e);
    }
  }
  if (!matchedNotes.length) return null;
  totalCarbs = Math.round(totalCarbs * 10) / 10;
  totalFiber = Math.round(totalFiber * 10) / 10;
  totalPro = Math.round(totalPro * 10) / 10;
  totalFat = Math.round(totalFat * 10) / 10;
  const netCarbs = Math.max(0, Math.round((totalCarbs - totalFiber) * 10) / 10);
  const glVal = Math.max(1, Math.round(netCarbs * 0.52));
  const glCat = netCarbs <= 15 ? 'Safe Low' : (netCarbs <= 35 ? 'Safe Low-Med' : (netCarbs <= 45 ? 'Moderate' : 'SEVERE SPIKE HAZARD'));
  const meets = netCarbs <= 45;
  const spikeLow = Math.round(netCarbs * 0.75);
  const spikeHigh = Math.max(spikeLow + 4, Math.round(netCarbs * 1.15));
  const walkMin = netCarbs <= 15 ? 10 : Math.min(45, Math.max(15, Math.round(netCarbs * 0.6)));
  const swaps = [];
  if (netCarbs > 30) {
    swaps.push('Swap half bread/bun for open-face or lettuce wrap (-14g net carbs)');
    swaps.push('Pair with unsweetened drink & add 16 fl oz water buffer');
  }
  const venueLine = venue
    ? `${venue} does not publish official bakery/cafe nutrition; grounded via USDA FoodData Central equivalent: `
    : 'Matched via U.S. Gov USDA FoodData Central: ';
  return {
    meal_name: text.trim(),
    vendor_matched: venue ? `${venue} (USDA FoodData Central Live)` : 'USDA FoodData Central (Zero-Account Live)',
    calories: totalKcal,
    net_carbs: netCarbs,
    total_carbs: totalCarbs,
    fiber: totalFiber,
    protein: totalPro,
    fat: totalFat,
    glycemic_load: `${glVal} (${glCat})`,
    meets_goal: meets,
    projected_spike: `+${spikeLow} to +${spikeHigh} mg/dL postprandial rise`,
    gemini_notes: venueLine + matchedNotes.join('; ') + '.',
    trade_alternatives: swaps,
    glut4_recommendation: netCarbs <= 15
      ? 'Mild 10-minute light walk after eating keeps glucose flat.'
      : `Take a ${walkMin}-minute brisk walk 20 minutes after eating to activate GLUT4 glucose clearance.`
  };
}

