// Detect meal type based on local time of day
let lastManualMealTypeAt = 0;

function initMealTypeByTime() {
  const hr = new Date().getHours();
  if (hr >= 5 && hr < 11) setMealType('Breakfast');
  else if (hr >= 11 && hr < 15) setMealType('Lunch');
  else if (hr >= 17 && hr < 22) setMealType('Dinner');
  else setMealType('Snack');
}

function setMealType(type, isManual = false) {
  selectedMealType = type;
  if (isManual) lastManualMealTypeAt = Date.now();
  ['Breakfast', 'Lunch', 'Dinner', 'Snack'].forEach(t => {
    const btn = document.getElementById('btnType' + t);
    if (btn) {
      if (t === type) btn.classList.add('active');
      else btn.classList.remove('active');
    }
  });
}

function refreshMealTypeIfStale() {
  if (Date.now() - lastManualMealTypeAt > 10 * 60 * 1000) {
    initMealTypeByTime();
  }
}

