function saveStandaloneVitalToCache(metric, val1, val2, unit, modeStr) {
  try {
    const raw = localStorage.getItem('bfm_local_latest_v1');
    const map = raw ? JSON.parse(raw) : {};
    map[metric] = {
      metric: metric,
      value1: val1,
      value2: val2,
      unit: unit || '',
      mode: modeStr || 'WEB_BLUETOOTH_STREAM',
      timestamp: new Date().toISOString()
    };
