// =========================================================================
// OFFLINE STAGED MEALS QUEUE (For Users Out All Day Away from PC)
// =========================================================================
function getStagedQueue() {
  try {
    const q = localStorage.getItem('staged_meals_queue');
    return q ? JSON.parse(q) : [];
  } catch (e) {
    return [];
  }
}

function saveStagedQueue(queue) {
  try {
    localStorage.setItem('staged_meals_queue', JSON.stringify(queue));
  } catch (e) {
    console.warn('[MIL-SPEC HANDLED FAULT] saveStagedQueue failed:', e);
  }
  renderStagedQueue();
}

function stageMealForSync() {
  const input = document.getElementById('txtMealInput');
  const text = input ? input.value.trim() : "";
  if (!text && uploadedPhotos.length === 0 && !currentAnalysis) {
    alert("Enter a meal, take a photo, or record voice before staging.");
    return;
  }
  if (!currentAnalysis) {
    currentAnalysis = makeZeroUnanalyzedRecord(
      text || "Mobile Plate Photo",
      "Staged in Field Mode — awaiting live Gemini lookup / Home PC sync."
    );
  }

  const stagedItem = {
    id: "meal_" + Date.now(),
    meal_type: selectedMealType,
    meal_name: text || currentAnalysis.meal_name,
    timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    photo_count: uploadedPhotos.length,
    photos: [...uploadedPhotos],
    audio_memo: recordedAudioBase64,
    analysis: currentAnalysis
  };

  const queue = getStagedQueue();
  queue.push(stagedItem);
  saveStagedQueue(queue);

  // Reset form for next meal/snack
  uploadedPhotos = [];
  recordedAudioBase64 = "";
  const memoBox = document.getElementById('audioMemoPlayerBox');
  if (memoBox) memoBox.style.display = 'none';
  renderPreviewStrip();
  document.getElementById('txtMealInput').value = "";
  document.getElementById('cardAnalysis').style.display = 'none';
  currentAnalysis = null;

  // Auto-advance meal type based on time
  initMobileDeviceIdentity();
initMealTypeByTime();

  const succ = document.getElementById('lblSubmitSuccess');
  succ.style.display = 'block';
  succ.innerHTML = `📦 <strong>${stagedItem.meal_type} (${stagedItem.meal_name})</strong> staged in phone memory! Will auto-sync when you arrive home at your PC.`;
  setTimeout(() => { succ.style.display = 'none'; }, 4000);
}

function renderStagedQueue() {
  const queue = getStagedQueue();
  const card = document.getElementById('cardStagedQueue');
  const list = document.getElementById('stagedList');
  const countLbl = document.getElementById('lblStagedCount');

  if (queue.length === 0) {
    card.style.display = 'none';
    return;
  }

  card.style.display = 'block';
  countLbl.textContent = `${queue.length} MEAL${queue.length > 1 ? 'S' : ''} QUEUED`;

  list.innerHTML = queue.map((item, idx) => `
    <div style="background: rgba(30, 41, 59, 0.8); border: 1px solid #475569; border-radius: 6px; padding: 8px 10px; display: flex; justify-content: space-between; align-items: center;">
      <div>
        <div style="font-weight: 800; font-size: 0.85rem; color: #38bdf8;">
          ${item.meal_type.toUpperCase()}: ${item.meal_name}
        </div>
        <div style="font-size: 0.72rem; color: #94a3b8;">
          ${item.timestamp} &bull; ${item.photo_count} photo(s) &bull; ${item.analysis.calories} kcal &bull; ${item.analysis.net_carbs}g net carbs
        </div>
      </div>
      <button type="button" onclick="removeStagedMeal(${idx})" style="background: #ef4444; color: white; border: none; border-radius: 4px; padding: 4px 8px; font-size: 0.72rem; cursor: pointer;">
        &times;
      </button>
    </div>
  `).join('');
}

function removeStagedMeal(idx) {
  const queue = getStagedQueue();
  queue.splice(idx, 1);
  saveStagedQueue(queue);
}

// Device Interrogation & Registration Initialization
function initMobileDeviceIdentity() {
  let esn = localStorage.getItem("bfm_phone_esn");
  let cellId = localStorage.getItem("bfm_cell_id") || "Cell 1";
  if (!esn) {
    esn = "ESN-9482-A01";
    localStorage.setItem("bfm_phone_esn", esn);
    localStorage.setItem("bfm_cell_id", cellId);
  }
  const esnLbl = document.getElementById('lblMobileEsn');
  if (esnLbl) esnLbl.textContent = `${cellId} • ${esn}`;
  return { esn, cellId };
}

async function syncAllStagedMeals() {
  const queue = getStagedQueue();
  if (queue.length === 0) return;

  const btn = document.getElementById('btnSyncAllStaged');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = "<span>🚀 DOCKING WITH BFM SYSTEM...</span>";
  }

  const { esn, cellId } = initMobileDeviceIdentity();

  // Attempt atomic bulk docking to /api/shuttle/dock
  try {
    const batchRecords = queue.map(item => ({
      intake_timestamp: item.timestamp || new Date().toISOString(),
      meal_name: `[${item.meal_type}] ${item.meal_name}`,
      calories: item.analysis ? item.analysis.calories : item.calories,
      net_carbs: item.analysis ? item.analysis.net_carbs : item.net_carbs,
      total_carbs: item.analysis ? item.analysis.total_carbs : item.total_carbs,
      fiber: item.analysis ? item.analysis.fiber : item.fiber,
