function _parseNumWithMultiplier(strVal, mult) {
  const n = parseFloat(strVal);
  if (isNaN(n) || n < 0) return null;
  return Math.round(n * mult * 10) / 10;
}

function parseNutritionFactsOcrText(ocrText, typedText = '') {
  const norm = String(ocrText || '').replace(/\r/g, '\n');
  if (norm.trim().length < 8) return null;

  let mult = 1.0;
  const tLow = String(typedText || '').toLowerCase();
  if (/\bhalf\b|\b1\/2\b/.test(tLow)) mult = 0.5;
  else if (/\bdouble\b|\btwo\b|\b2\s*(?:servings?|slices?|pieces?|bars?|packs?)\b/.test(tLow)) mult = 2.0;
  else {
    const mServ = tLow.match(/(\d+(?:\.\d+)?)\s*(?:servings?|x)\b/);
    if (mServ) {
      const v = parseFloat(mServ[1]);
      if (v > 0 && v <= 10) mult = v;
    }
  }

  const mCal = norm.match(/calories[^0-9]{0,16}(\d{1,4})/i);
  const mCarb = norm.match(/total\s+carb(?:ohydrate)?s?[^0-9]{0,16}(\d+(?:\.\d+)?)\s*g?/i)
    || norm.match(/\bcarbohydrates?[^0-9]{0,16}(\d+(?:\.\d+)?)\s*g?/i);
  const mFib = norm.match(/(?:dietary\s+)?fiber[^0-9]{0,16}(\d+(?:\.\d+)?)\s*g?/i);
  const mSug = norm.match(/(?:total\s+)?sugars?[^0-9]{0,16}(\d+(?:\.\d+)?)\s*g?/i);
  const mPro = norm.match(/protein[^0-9]{0,16}(\d+(?:\.\d+)?)\s*g?/i);
  const mFat = norm.match(/total\s+fat[^0-9]{0,16}(\d+(?:\.\d+)?)\s*g?/i);
  const mSrv = norm.match(/serving\s+size[:\s]*([^\n]{2,42})/i);

  const cals = mCal ? Math.round(parseFloat(mCal[1]) * mult) : 0;
  const totCarbs = mCarb ? (_parseNumWithMultiplier(mCarb[1], mult) ?? 0) : 0;
  const fib = mFib ? (_parseNumWithMultiplier(mFib[1], mult) ?? 0) : 0;
  const sugars = mSug ? (_parseNumWithMultiplier(mSug[1], mult) ?? 0) : 0;
  const pro = mPro ? (_parseNumWithMultiplier(mPro[1], mult) ?? 0) : 0;
  const fat = mFat ? (_parseNumWithMultiplier(mFat[1], mult) ?? 0) : 0;

  if (cals <= 0 && totCarbs <= 0 && pro <= 0 && fat <= 0) return null;

  const netCarbs = Math.max(0, Math.round((totCarbs - fib) * 10) / 10);
