async function _loadTesseractOnce() {
  if (window.Tesseract && typeof window.Tesseract.recognize === 'function') {
    return window.Tesseract;
  }
  if (!window._tesseractLoadingPromise) {
    window._tesseractLoadingPromise = new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';
      s.async = true;
      const timer = setTimeout(() => reject(new Error('Tesseract CDN load timed out')), 15000);
      s.onload = () => {
        clearTimeout(timer);
        if (window.Tesseract) resolve(window.Tesseract);
        else reject(new Error('Tesseract global missing after script load'));
      };
      s.onerror = () => {
        clearTimeout(timer);
        reject(new Error('Failed loading Tesseract OCR script'));
      };
      document.head.appendChild(s);
    });
  }
  try {
    return await window._tesseractLoadingPromise;
  } catch (e) {
    window._tesseractLoadingPromise = null;
    throw e;
  }
}

async function _preprocessLabelPhotoCanvas(dataUrl) {
  return await new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const maxW = 1400;
      const scale = img.width > maxW ? (maxW / img.width) : 1.0;
      const w = Math.max(1, Math.round(img.width * scale));
      const h = Math.max(1, Math.round(img.height * scale));
      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);
      try {
        const imgData = ctx.getImageData(0, 0, w, h);
        const d = imgData.data;
        const contrast = 1.45;
        for (let i = 0; i < d.length; i += 4) {
          const lum = 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
          const v = Math.min(255, Math.max(0, Math.round((lum - 128) * contrast + 128)));
          d[i] = v; d[i + 1] = v; d[i + 2] = v;
        }
        ctx.putImageData(imgData, 0, 0);
      } catch (e) {
        console.warn('[MIL-SPEC HANDLED FAULT] Label contrast boost skipped:', e);
      }
      resolve(canvas);
    };
    img.onerror = () => reject(new Error('Invalid image data for label OCR'));
    img.src = dataUrl;
  });
}

async function extractNutritionLabelFromPhoto(photoDataUrl, typedText = '') {
  if (!photoDataUrl) return null;
  const tess = await _loadTesseractOnce();
  const canvas = await _preprocessLabelPhotoCanvas(photoDataUrl);
  const res = await tess.recognize(canvas, 'eng');
  const ocrText = (res && res.data && res.data.text) ? res.data.text : '';
  return parseNutritionFactsOcrText(ocrText, typedText);
}

function parseMealQueryAndVenue(rawText) {
  const clean = (rawText || '').trim();
  if (!clean) return { venue: '', items: [] };
  let venue = '';
  let foodText = clean;
  if (clean.includes(',')) {
    const commaParts = clean.split(',').map(s => s.trim()).filter(Boolean);
    if (commaParts.length >= 2) {
      const head = commaParts[0];
      const looksLikeVenue = /\b\d{5}\b|\b(?:wa|or|ca|id|ny|tx|fl)\b|bakery|restaurant|resturant|pizzeria|cafe|diner|drive-?in|bistro|grill|kitchen|deli|market|house|sultan/i.test(head);
      if (looksLikeVenue) {
        venue = head;
        foodText = commaParts.slice(1).join(', ');
      }
    }
  }
  const pairedRe = /\b(ham|mac|macaroni|peanut\s+butter|pb|fish|rice|beans|bacon|chips|biscuits|franks|crackers|cream)\s+(and|&|with)\s+(cheese|jelly|chips|beans|rice|eggs|salsa|gravy|dreamwip|cool\s*whip|whipped\s+cream)\b/gi;
  const guarded = foodText.replace(pairedRe, (_, a, conj, b) => `${a}__PAIR_CONJ_${conj.trim()}__${b}`);
  const items = guarded
    .split(/,|;|\+|\b(?:and|with|plus)\b/i)
    .map(s => s.replace(/__PAIR_CONJ_([^_]+)__/g, ' $1 ').trim())
    .filter(Boolean)
    .slice(0, 6);
  return { venue, items };
}

function _cleanFoodComponentQuery(comp) {
  const raw = String(comp || '').trim();
  const low = raw.toLowerCase();
  if (/^(?:\d+\s*(?:fl\s*oz|oz|cups?|glasses?|bottles?)\s+)?(?:water|tap water|spring water|seltzer|sparkling water|diet\s+(?:coke|cola|soda|pepsi|root\s*beer|sprite|dr\.?\s*pepper)|zero\s+sugar\s+soda|coke\s+zero|unsweetened\s+(?:iced\s+)?tea|green\s+tea|black\s+coffee|plain\s+tea|tea\s+\d+\s*oz|coffee\s+\d+\s*oz)$/i.test(low)) {
    return { isZeroCalDrink: true, query: raw, portionScale: 1.0, note: `${raw} (0 kcal, 0g net carbs)` };
  }
  let portionScale = 1.0;
  if (/\bhalf\b|\b1\/2\b/.test(low)) portionScale = 0.5;
  else if (/\bsmall\b/.test(low)) portionScale = 0.75;
  else if (/\btwo\b|\b2\s*(?:slices?|pieces?|bars?)\b/.test(low)) portionScale = 2.0;
  const mOz = low.match(/(\d+(?:\.\d+)?)\s*oz\b/);
  if (mOz && parseFloat(mOz[1]) > 0 && parseFloat(mOz[1]) <= 16) {
    portionScale = Math.max(0.25, Math.min(3.0, parseFloat(mOz[1]) / 3.5));
  }
  let q = raw
    .replace(/\b(?:one|two|three|a|an|half|1\/2)\s+(?:small|large|medium|regular)?\s*(?:slice|piece|bowl|cup|serving|order)\s*(?:of)?\b/gi, ' ')
    .replace(/\b\d+(?:\.\d+)?\s*(?:fl\s*oz|oz|grams?|g|ml)\b/gi, ' ')
    .replace(/\b(?:sugar\s*free|unsweetened|small|medium|large|homemade)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return { isZeroCalDrink: false, query: q || raw, portionScale, note: '' };
}

async function searchOpenFoodFactsComponent(searchQuery) {
  try {
    const url = `https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(searchQuery)}&search_simple=1&action=process&json=1&page_size=6`;
    const ctrl = new AbortController();
    const tId = setTimeout(() => ctrl.abort(), 7000);
    const resp = await fetch(url, { cache: 'no-store', signal: ctrl.signal });
    clearTimeout(tId);
    if (!resp.ok) return null;
    const data = await resp.json();
    const products = Array.isArray(data.products) ? data.products : [];
    for (const p of products) {
      const nu = p.nutriments || {};
      const kSrv = parseFloat(nu['energy-kcal_serving']);
      const k100 = parseFloat(nu['energy-kcal_100g']);
      const cSrv = parseFloat(nu['carbohydrates_serving']);
      const c100 = parseFloat(nu['carbohydrates_100g']);
      const fSrv = parseFloat(nu['fiber_serving']);
      const f100 = parseFloat(nu['fiber_100g']);
      const pSrv = parseFloat(nu['proteins_serving']);
      const p100 = parseFloat(nu['proteins_100g']);
      const ftSrv = parseFloat(nu['fat_serving']);
      const ft100 = parseFloat(nu['fat_100g']);

      let kcal = 0, carbs = 0, fib = 0, pro = 0, fat = 0, srvLbl = '1 serving';
      if (!isNaN(kSrv) && kSrv > 0 && (!isNaN(cSrv) || !isNaN(pSrv))) {
        kcal = Math.round(kSrv);
        carbs = Math.round((isNaN(cSrv) ? 0 : cSrv) * 10) / 10;
        fib = Math.round((isNaN(fSrv) ? 0 : fSrv) * 10) / 10;
        pro = Math.round((isNaN(pSrv) ? 0 : pSrv) * 10) / 10;
        fat = Math.round((isNaN(ftSrv) ? 0 : ftSrv) * 10) / 10;
        srvLbl = p.serving_size ? String(p.serving_size) : '1 labeled serving';
      } else if (!isNaN(k100) && k100 > 0) {
        kcal = Math.round(k100);
        carbs = Math.round((isNaN(c100) ? 0 : c100) * 10) / 10;
        fib = Math.round((isNaN(f100) ? 0 : f100) * 10) / 10;
        pro = Math.round((isNaN(p100) ? 0 : p100) * 10) / 10;
        fat = Math.round((isNaN(ft100) ? 0 : ft100) * 10) / 10;
        srvLbl = '100g reference';
      } else {
        continue;
      }
      const name = String(p.product_name || searchQuery).trim();
      return { name, srvLbl, kcal, carbs, fib, pro, fat, sourceTag: 'Open Food Facts' };
    }
  } catch (e) {
    console.warn('[MIL-SPEC HANDLED FAULT] Open Food Facts lookup failed:', searchQuery, e);
  }
  return null;
}

